insert into public.game_content (game, data, updated_at) values ('battle-cries', $seed$[{"id": "cry-crit-low-1", "band": "low", "kind": "crit", "text": "暴击!好厉害!💥"}, {"id": "cry-crit-low-2", "band": "low", "kind": "crit", "text": "闪闪发光·全对!✨"}, {"id": "cry-crit-low-3", "band": "low", "kind": "crit", "text": "哇!满分啦!🌟"}, {"id": "cry-crit-low-4", "band": "low", "kind": "crit", "text": "小脑袋开窍咯!💡"}, {"id": "cry-crit-low-5", "band": "low", "kind": "crit", "text": "超级超级棒!⭐"}, {"id": "cry-crit-low-6", "band": "low", "kind": "crit", "text": "啪!正中红心!🎯"}, {"id": "cry-crit-low-7", "band": "low", "kind": "crit", "text": "金光闪闪暴击!"}, {"id": "cry-crit-low-8", "band": "low", "kind": "crit", "text": "答对!力量up!💪"}, {"id": "cry-crit-high-1", "band": "high", "kind": "crit", "text": "暴 击!力量觉醒——学神降临!⚡"}, {"id": "cry-crit-high-2", "band": "high", "kind": "crit", "text": "致命一击!真理之光贯穿全场!🌟"}, {"id": "cry-crit-high-3", "band": "high", "kind": "crit", "text": "完美正解·伤害翻倍·无人能挡!💥"}, {"id": "cry-crit-high-4", "band": "high", "kind": "crit", "text": "暴击觉醒——脑域全开,极限超越!🔥"}, {"id": "cry-crit-high-5", "band": "high", "kind": "crit", "text": "命运暴击!这就是学霸的力量!⚡"}, {"id": "cry-crit-high-6", "band": "high", "kind": "crit", "text": "绝对领域·满分暴击,降维打击!💫"}, {"id": "cry-crit-high-7", "band": "high", "kind": "crit", "text": "天降暴击!智慧之刃,势不可挡!⚔️"}, {"id": "cry-crit-high-8", "band": "high", "kind": "crit", "text": "超·暴击!真我觉醒,无可阻挡!🌠"}, {"id": "cry-combo-low-1", "band": "low", "kind": "combo", "text": "三连击!好棒哦!✨"}, {"id": "cry-combo-low-2", "band": "low", "kind": "combo", "text": "五连击!冲冲冲!💨"}, {"id": "cry-combo-low-3", "band": "low", "kind": "combo", "text": "连对啦!停不下!🌟"}, {"id": "cry-combo-low-4", "band": "low", "kind": "combo", "text": "二连击!再来一个!"}, {"id": "cry-combo-low-5", "band": "low", "kind": "combo", "text": "七连击!小英雄!⭐"}, {"id": "cry-combo-low-6", "band": "low", "kind": "combo", "text": "连击连击!好开心!😆"}, {"id": "cry-combo-low-7", "band": "low", "kind": "combo", "text": "十连击!满天星!🌠"}, {"id": "cry-combo-low-8", "band": "low", "kind": "combo", "text": "越打越厉害啦!💪"}, {"id": "cry-combo-high-1", "band": "high", "kind": "combo", "text": "五连击!知识风暴降临!🌪️"}, {"id": "cry-combo-high-2", "band": "high", "kind": "combo", "text": "三连暴击·学神觉醒!⚡"}, {"id": "cry-combo-high-3", "band": "high", "kind": "combo", "text": "十连击!连锁真理,无限超越!🔥"}, {"id": "cry-combo-high-4", "band": "high", "kind": "combo", "text": "七连斩!错题尽数湮灭!💥"}, {"id": "cry-combo-high-5", "band": "high", "kind": "combo", "text": "连击狂潮!智慧之轮永不停转!🌀"}, {"id": "cry-combo-high-6", "band": "high", "kind": "combo", "text": "无双连段·满分收割者降临!🌟"}, {"id": "cry-combo-high-7", "band": "high", "kind": "combo", "text": "极限连击!这波操作,封神!💫"}, {"id": "cry-combo-high-8", "band": "high", "kind": "combo", "text": "二十连击!知识海啸,席卷天地!🌊"}, {"id": "cry-finish-low-1", "band": "low", "kind": "finish", "text": "终极一击!赢啦!🎉"}, {"id": "cry-finish-low-2", "band": "low", "kind": "finish", "text": "毕业咯!撒花!🌸"}, {"id": "cry-finish-low-3", "band": "low", "kind": "finish", "text": "大胜利!冠军!🏆"}, {"id": "cry-finish-low-4", "band": "low", "kind": "finish", "text": "通关啦!最棒的!⭐"}, {"id": "cry-finish-low-5", "band": "low", "kind": "finish", "text": "知识小英雄,登场!🦸"}, {"id": "cry-finish-high-1", "band": "high", "kind": "finish", "text": "终焉一击——毕业·封印解除!🎓"}, {"id": "cry-finish-high-2", "band": "high", "kind": "finish", "text": "终极奥义·知识审判·终焉一击!⚖️"}, {"id": "cry-finish-high-3", "band": "high", "kind": "finish", "text": "真理终结·满分降临,胜负已定!🌟"}, {"id": "cry-finish-high-4", "band": "high", "kind": "finish", "text": "学神奥义·最终章——完美通关!🔥"}, {"id": "cry-finish-high-5", "band": "high", "kind": "finish", "text": "知识之神苏醒,以此一击,终结一切!💥"}, {"id": "cry-finish-high-6", "band": "high", "kind": "finish", "text": "封印全解·智慧无双——胜利,属于我!👑"}, {"id": "cry-taunt-low-1", "band": "low", "kind": "taunt", "text": "嘿嘿,我超棒!😎"}, {"id": "cry-taunt-low-2", "band": "low", "kind": "taunt", "text": "你猜我会不会?🤭"}, {"id": "cry-taunt-low-3", "band": "low", "kind": "taunt", "text": "看我的厉害!💪"}, {"id": "cry-taunt-low-4", "band": "low", "kind": "taunt", "text": "小问题,难不倒!✌️"}, {"id": "cry-taunt-low-5", "band": "low", "kind": "taunt", "text": "准备好认输了吗?😝"}, {"id": "cry-taunt-high-1", "band": "high", "kind": "taunt", "text": "哼,让你见识真正的实力。⚡"}, {"id": "cry-taunt-high-2", "band": "high", "kind": "taunt", "text": "在我的知识面前,你毫无胜算。🔥"}, {"id": "cry-taunt-high-3", "band": "high", "kind": "taunt", "text": "颤抖吧,这就是学霸的领域。🌑"}, {"id": "cry-taunt-high-4", "band": "high", "kind": "taunt", "text": "区区难题,也敢挡我去路?😏"}, {"id": "cry-taunt-high-5", "band": "high", "kind": "taunt", "text": "记住这个名字——满分的统治者!👑"}, {"id": "cry-crit-low-9", "band": "low", "kind": "crit", "text": "暴击！厉害炸啦！💥"}, {"id": "cry-crit-low-10", "band": "low", "kind": "crit", "text": "答对！闪闪发光！✨"}, {"id": "cry-crit-high-9", "band": "high", "kind": "crit", "text": "致命暴击·知识闪电·一击破防！⚡"}, {"id": "cry-crit-high-10", "band": "high", "kind": "crit", "text": "超·觉醒暴击！满分意志，碾压全场！🌟"}, {"id": "cry-combo-low-9", "band": "low", "kind": "combo", "text": "连击啦！一二三，停不下来～🎈"}, {"id": "cry-combo-low-10", "band": "low", "kind": "combo", "text": "连对连对！小火车冲冲冲！🚂"}, {"id": "cry-combo-high-9", "band": "high", "kind": "combo", "text": "连击不断·知识连锁·气势成形！🔥"}, {"id": "cry-combo-high-10", "band": "high", "kind": "combo", "text": "无双连击！真理风暴，愈演愈烈！🌪️"}, {"id": "cry-finish-low-6", "band": "low", "kind": "finish", "text": "终极一击！我赢啦撒花！🎉"}, {"id": "cry-finish-low-7", "band": "low", "kind": "finish", "text": "通关咯！我是小冠军！🏆"}, {"id": "cry-finish-high-7", "band": "high", "kind": "finish", "text": "终焉裁决·满分降临·胜负已分！⚖️"}, {"id": "cry-finish-high-8", "band": "high", "kind": "finish", "text": "最终奥义·知识封印·一锤定音！🎓"}, {"id": "cry-taunt-low-6", "band": "low", "kind": "taunt", "text": "嘿嘿，我可厉害啦！😋"}, {"id": "cry-taunt-low-7", "band": "low", "kind": "taunt", "text": "来呀来呀，我不怕～😝"}, {"id": "cry-taunt-high-6", "band": "high", "kind": "taunt", "text": "在我面前，难题也得排队认输。😏"}, {"id": "cry-taunt-high-7", "band": "high", "kind": "taunt", "text": "睁大眼睛，见证满分的统治。👑"}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
insert into public.game_content (game, data, updated_at) values ('battle-disses', $seed$[{"id": "diss-low-1", "band": "low", "text": "你写的字像螃蟹横着爬，老师看了直挠头发～"}, {"id": "diss-low-2", "band": "low", "text": "你跑得比蜗牛还有耐心，慢慢爬呀别着急～"}, {"id": "diss-low-3", "band": "low", "text": "你做题的速度像树懒，一道题能睡个午觉～"}, {"id": "diss-low-4", "band": "low", "text": "你背课文像复读机卡带，嗯嗯啊啊半天没下文～"}, {"id": "diss-low-5", "band": "low", "text": "你的橡皮擦得满桌渣，作业本快变小沙滩～"}, {"id": "diss-low-6", "band": "low", "text": "你举手比乌龟伸头还慢，老师都喊到下一个啦～"}, {"id": "diss-low-7", "band": "low", "text": "你画的太阳是方块的，外星人看了想回家～"}, {"id": "diss-low-8", "band": "low", "text": "你唱歌跑调跑出操场，麻雀听了都搬家～"}, {"id": "diss-low-9", "band": "low", "text": "你叠的纸飞机往后飞，专门跟地心引力做朋友～"}, {"id": "diss-low-10", "band": "low", "text": "你的书包像个百宝箱，可惜从来找不到铅笔～"}, {"id": "diss-low-11", "band": "low", "text": "你系鞋带能系成大麻花，一弯腰就栽个跟头～"}, {"id": "diss-low-12", "band": "low", "text": "你算数学一加一等于窗外，眼睛早飞到天上啦～"}, {"id": "diss-low-13", "band": "low", "text": "你吃饭比考试还认真，最后一名永远是你～"}, {"id": "diss-low-14", "band": "low", "text": "你的字迹龙飞凤舞，连你自己都不认识～"}, {"id": "diss-low-15", "band": "low", "text": "你跳绳一下绊三跤，绳子都想请假休息～"}, {"id": "diss-low-16", "band": "low", "text": "你睡懒觉的功夫天下第一，闹钟都被你熬退休啦～"}, {"id": "diss-low-17", "band": "low", "text": "你的红领巾系成蝴蝶结，蝴蝶看了笑哈哈～"}, {"id": "diss-low-18", "band": "low", "text": "你读拼音读成绕口令，舌头打了八个结～"}, {"id": "diss-low-19", "band": "low", "text": "你折腾一上午橡皮泥，捏出个四不像的小怪兽～"}, {"id": "diss-low-20", "band": "low", "text": "你跑步摆手像小风车，可惜风车原地打转转～"}, {"id": "diss-low-21", "band": "low", "text": "你的水彩笔全是干的，画出来一片空白真清爽～"}, {"id": "diss-low-22", "band": "low", "text": "你抄黑板抄成天书，回家自己都翻译不出来～"}, {"id": "diss-low-23", "band": "low", "text": "你笑起来像被挠痒痒，咯咯咯停都停不下来～"}, {"id": "diss-low-24", "band": "low", "text": "你举手发言全靠蒙，蒙对一次开心一整天～"}, {"id": "diss-high-1", "band": "high", "text": "你这字写得，鬼画符都得拜你当祖师爷。"}, {"id": "diss-high-2", "band": "high", "text": "你跑八百米的速度，连秒表都看睡着了。"}, {"id": "diss-high-3", "band": "high", "text": "你这脑筋急转弯，转了半天还在原地堵车。"}, {"id": "diss-high-4", "band": "high", "text": "你背单词靠缘分，今天会的明天就失联了。"}, {"id": "diss-high-5", "band": "high", "text": "你的逻辑链断得比我手机信号还干脆。"}, {"id": "diss-high-6", "band": "high", "text": "你做选择题全靠玄学，三长一短就选最短。"}, {"id": "diss-high-7", "band": "high", "text": "你这反应速度，加载条都替你着急转圈圈。"}, {"id": "diss-high-8", "band": "high", "text": "你考试时灵魂出窍，卷子写得像意识流文学。"}, {"id": "diss-high-9", "band": "high", "text": "你的记忆力是金鱼授权的，七秒一刷新。"}, {"id": "diss-high-10", "band": "high", "text": "你解几何题画的辅助线，把图都画成蜘蛛网了。"}, {"id": "diss-high-11", "band": "high", "text": "你这英语口语，外教听完默默打开了翻译软件。"}, {"id": "diss-high-12", "band": "high", "text": "你的作文凑字数能力满分，内容含量约等于空气。"}, {"id": "diss-high-13", "band": "high", "text": "你写作业的拖延症，连DDL看了都想报警。"}, {"id": "diss-high-14", "band": "high", "text": "你这立定跳远的距离，蚂蚱看了想伸手扶你一把。"}, {"id": "diss-high-15", "band": "high", "text": "你背公式的样子，像是在跟课本玩躲猫猫。"}, {"id": "diss-high-16", "band": "high", "text": "你这上课走神的本事，魂都漂到月球建基地了。"}, {"id": "diss-high-17", "band": "high", "text": "你算题的草稿纸，比卷子本身还有创意。"}, {"id": "diss-high-18", "band": "high", "text": "你这运动细胞，估计还在快递路上没发货。"}, {"id": "diss-high-19", "band": "high", "text": "你回答问题的语速，标点符号都嫌你磨叽。"}, {"id": "diss-high-20", "band": "high", "text": "你的错题本厚得能当字典卖，建议申请出版。"}, {"id": "diss-high-21", "band": "high", "text": "你这朗读的抑扬顿挫，把课文读成了催眠曲。"}, {"id": "diss-high-22", "band": "high", "text": "你检查试卷的认真劲，把对的全改成错的了。"}, {"id": "diss-high-23", "band": "high", "text": "你这专注力，开五分钟小差能错过一整个朝代。"}, {"id": "diss-high-24", "band": "high", "text": "你的整理书包技术，每次都能把课本变成限量隐藏款。"}, {"id": "diss-low-25", "band": "low", "text": "你藏零食的本事天下第一，可惜每次都被自己的肚子先举报～"}, {"id": "diss-low-26", "band": "low", "text": "你打游戏闯关三天三夜没过去，蘑菇都认识你叫你常客啦～"}, {"id": "diss-low-27", "band": "low", "text": "你睡过头的速度比火箭还快，闹钟响七遍你还在做梦～"}, {"id": "diss-low-28", "band": "low", "text": "你追动画片一集接一集，眼睛都看成两个大铜铃啦～"}, {"id": "diss-low-29", "band": "low", "text": "你上课发呆能看一整朵云，云都飘走了你还在原地～"}, {"id": "diss-low-30", "band": "low", "text": "你的口头禅是「等一下」，等到太阳下山你还没动窝～"}, {"id": "diss-low-31", "band": "low", "text": "你自拍要拍九十九张，最后还是挑了第一张～"}, {"id": "diss-low-32", "band": "low", "text": "你发表情包比说话还多，嘴巴都快忘了怎么张啦～"}, {"id": "diss-low-33", "band": "low", "text": "你吃棒棒糖能吃半小时，舌头都甜得想罢工啦～"}, {"id": "diss-low-34", "band": "low", "text": "你找东西翻箱倒柜，结果它就在你手上拿着呢～"}, {"id": "diss-low-35", "band": "low", "text": "你排队总爱蹦蹦跳跳，前面的人都被你蹦没影啦～"}, {"id": "diss-low-36", "band": "low", "text": "你的水杯天天忘在学校，它都想换个主人养啦～"}, {"id": "diss-high-25", "band": "high", "text": "你囤零食的速度赶超双十一，开学第一周就清仓了。"}, {"id": "diss-high-26", "band": "high", "text": "你打游戏说『最后一把』，最后了八把还没下号。"}, {"id": "diss-high-27", "band": "high", "text": "你睡过头是有天赋的，闹钟在你这儿只是个氛围音效。"}, {"id": "diss-high-28", "band": "high", "text": "你追剧二倍速还嫌慢，进度条都被你催出心理阴影了。"}, {"id": "diss-high-29", "band": "high", "text": "你发呆的时候灵魂出差了，回来还得倒时差缓半天。"}, {"id": "diss-high-30", "band": "high", "text": "你那口头禅『真的假的』，从早问到晚也没研究出结论。"}, {"id": "diss-high-31", "band": "high", "text": "你自拍开美颜把自己P成陌生人，亲妈都得验脸才认。"}, {"id": "diss-high-32", "band": "high", "text": "你聊天全靠表情包接龙，打字的功能怕是已经退役了。"}, {"id": "diss-high-33", "band": "high", "text": "你立的flag比小区旗杆还多，到现在一根都没收回去。"}, {"id": "diss-high-34", "band": "high", "text": "你收藏夹里两百个『马上学』，吃灰吃成了文物级别。"}, {"id": "diss-high-35", "band": "high", "text": "你说『我五分钟就来』，地球都自转一圈你还没出门。"}, {"id": "diss-high-36", "band": "high", "text": "你手机电量永远红着，充电宝看见你都想躲起来。"}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
insert into public.game_content (game, data, updated_at) values ('battle-encounters', $seed$[{"id": "l-enc-001", "band": "low", "prompt": "同学挡在路中间，想跟你比谁跑得快。", "options": [{"id": "a", "text": "「我们一起跑，谁赢都鼓掌！」", "reply": "好呀好呀，冲鸭！", "outcome": "win"}, {"id": "b", "text": "「让开啦，别挡路！」", "reply": "哼，凭什么。", "outcome": "fail"}, {"id": "c", "text": "「我先系个鞋带…其实我没穿鞋带」", "reply": "噗，你好怪哦哈哈。", "outcome": "funny"}]}, {"id": "l-enc-002", "band": "low", "prompt": "同学的橡皮掉地上了，他正趴着找。", "options": [{"id": "a", "text": "帮他一起捡起来递过去", "reply": "谢谢你！你人真好~", "outcome": "win"}, {"id": "b", "text": "假装没看见走过去", "reply": "哼，不理你了。", "outcome": "fail"}, {"id": "c", "text": "「我帮你找！」结果踩到了橡皮", "reply": "啊——它被你踩扁啦哈哈！", "outcome": "funny"}]}, {"id": "l-enc-003", "band": "low", "prompt": "同学举着半块饼干：「你想吃吗？」", "options": [{"id": "a", "text": "「谢谢！我也分你一颗糖🍬」", "reply": "嘿嘿，我们换着吃，好朋友！", "outcome": "win"}, {"id": "b", "text": "一把抢过来塞嘴里", "reply": "喂！那是我的呀！", "outcome": "fail"}]}, {"id": "l-enc-004", "band": "low", "prompt": "同学嘟着嘴：「你昨天没跟我玩滑梯。」", "options": [{"id": "a", "text": "「对不起嘛，今天我们一起玩！」", "reply": "好！那拉钩钩~", "outcome": "win"}, {"id": "b", "text": "「滑梯又不是你家的。」", "reply": "哼，我才不跟你玩。", "outcome": "fail"}, {"id": "c", "text": "「因为我变成乌龟啦，爬得超级慢」", "reply": "噗，乌龟也要一起玩呀哈哈！", "outcome": "funny"}]}, {"id": "l-enc-005", "band": "low", "prompt": "同学神秘兮兮：「我会一个超厉害的魔术，你信不信？」", "options": [{"id": "a", "text": "「哇好厉害！快给我看看！」", "reply": "嘿嘿，那你跟我来~", "outcome": "win"}, {"id": "b", "text": "「假的，你骗人。」", "reply": "哼，不给你看了。", "outcome": "fail"}, {"id": "c", "text": "「我也会！我能把鼻涕变没！」", "reply": "哈哈哈那是擤掉了吧！", "outcome": "funny"}]}, {"id": "l-enc-006", "band": "low", "prompt": "同学摔了一跤坐在地上，眼睛红红的快哭了。", "options": [{"id": "a", "text": "「我拉你起来，吹吹就不疼啦」", "reply": "呜…谢谢你，我们一起走。", "outcome": "win"}, {"id": "b", "text": "「哈哈你摔屁股啦！」", "reply": "哇——你坏！", "outcome": "fail"}]}, {"id": "l-enc-007", "band": "low", "prompt": "同学骄傲地说：「我今天会自己系鞋带了！」", "options": [{"id": "a", "text": "「哇你好棒！给你鼓掌！」", "reply": "嘿嘿，我教你呀！", "outcome": "win"}, {"id": "b", "text": "「这有什么，我早就会了。」", "reply": "哼，没劲。", "outcome": "fail"}, {"id": "c", "text": "「我会系成蝴蝶结，还会飞那种！」", "reply": "蝴蝶结哪会飞呀哈哈！", "outcome": "funny"}]}, {"id": "l-enc-008", "band": "low", "prompt": "同学拿着画：「你看我画的恐龙好不好？」", "options": [{"id": "a", "text": "「好看！它的牙齿好酷呀！」", "reply": "嘻嘻，送给你啦！", "outcome": "win"}, {"id": "b", "text": "「画得好丑哦。」", "reply": "哼，你才丑。", "outcome": "fail"}]}, {"id": "l-enc-009", "band": "low", "prompt": "同学跳到你面前：「我们来玩石头剪刀布！」", "options": [{"id": "a", "text": "「来呀！输了喊对方大王！」", "reply": "哈哈好，三局两胜！", "outcome": "win"}, {"id": "b", "text": "「不玩，幼稚。」", "reply": "小气鬼~", "outcome": "fail"}, {"id": "c", "text": "出了个「石头剪刀布」全都出", "reply": "你三个一起出是犯规呀哈哈！", "outcome": "funny"}]}, {"id": "l-enc-010", "band": "low", "prompt": "同学小声说：「我的牙掉了一颗，你看～」", "options": [{"id": "a", "text": "「哇你要换大牙啦，好厉害！」", "reply": "嘿嘿，我变小兔子啦！", "outcome": "win"}, {"id": "b", "text": "「好恶心，走开。」", "reply": "哼，不给你看了。", "outcome": "fail"}]}, {"id": "l-enc-011", "band": "low", "prompt": "同学举着小水壶：「我忘带水了，渴死啦…」", "options": [{"id": "a", "text": "「喝我的吧，我们轮流喝！」", "reply": "谢谢你，你最好啦！", "outcome": "win"}, {"id": "b", "text": "「谁让你忘带的。」", "reply": "哼，不理你。", "outcome": "fail"}]}, {"id": "l-enc-012", "band": "low", "prompt": "同学神气地挡路：「叫我一声班长我就让开！」", "options": [{"id": "a", "text": "「班长好！请让一让~」", "reply": "哈哈乖，过去吧！", "outcome": "win"}, {"id": "b", "text": "「你又不是真班长。」", "reply": "哼，就不让。", "outcome": "fail"}, {"id": "c", "text": "「宇宙超级无敌大班长好！」", "reply": "噗哈哈，太夸张啦，过吧过吧！", "outcome": "funny"}]}, {"id": "l-enc-013", "band": "low", "prompt": "同学手里抓着一只小瓢虫：「你怕不怕虫子？」", "options": [{"id": "a", "text": "「不怕呀，它好可爱，我们放它飞吧」", "reply": "好！拜拜小瓢虫~", "outcome": "win"}, {"id": "b", "text": "「啊啊啊拿走！」吓得跑开", "reply": "哈哈胆小鬼！", "outcome": "fail"}]}, {"id": "l-enc-014", "band": "low", "prompt": "同学拉住你：「我们交换贴纸好不好？」", "options": [{"id": "a", "text": "「好呀！我这张闪闪的给你」", "reply": "哇谢谢！我们是好朋友啦！", "outcome": "win"}, {"id": "b", "text": "「我的都不给你。」", "reply": "小气！哼。", "outcome": "fail"}]}, {"id": "l-enc-015", "band": "low", "prompt": "同学鼓着腮帮子：「你刚才是不是笑我了？」", "options": [{"id": "a", "text": "「没有啦，我是笑那只小狗，抱抱~」", "reply": "哦…那好吧，抱一个！", "outcome": "win"}, {"id": "b", "text": "「就笑你了怎么样。」", "reply": "哇你坏！我要告老师！", "outcome": "fail"}]}, {"id": "l-enc-016", "band": "low", "prompt": "同学举着两根棒棒糖：「我有两根，可是不知道给谁…」", "options": [{"id": "a", "text": "「那我们一人一根，边走边吃！」", "reply": "好耶！你真聪明~", "outcome": "win"}, {"id": "b", "text": "「两根都给我！」", "reply": "才不要，你好贪心。", "outcome": "fail"}, {"id": "c", "text": "「我帮你吃掉，你就不用烦啦」", "reply": "噗你想得美哈哈！", "outcome": "funny"}]}, {"id": "l-enc-017", "band": "low", "prompt": "同学蹲在地上看蚂蚁搬家，挡住了路。", "options": [{"id": "a", "text": "「我也看！蚂蚁好厉害呀」一起蹲下", "reply": "嘻嘻，你也喜欢蚂蚁呀，走，带你看蚁窝！", "outcome": "win"}, {"id": "b", "text": "一脚想踩过去", "reply": "别踩别踩！你好凶！", "outcome": "fail"}]}, {"id": "l-enc-018", "band": "low", "prompt": "同学嘟嘴：「老师表扬你没表扬我…」", "options": [{"id": "a", "text": "「你今天也很棒呀，我都看见啦！」", "reply": "真的吗…嘿嘿，谢谢你。", "outcome": "win"}, {"id": "b", "text": "「因为我比你乖呀。」", "reply": "哼！不跟你好了。", "outcome": "fail"}]}, {"id": "l-enc-019", "band": "low", "prompt": "同学拿着小汽车：「我的车没电了，你能帮我推吗？」", "options": [{"id": "a", "text": "「我来推！呜——出发！」", "reply": "哈哈太好玩了，一起玩车车！", "outcome": "win"}, {"id": "b", "text": "「自己推去。」", "reply": "哼，小气鬼。", "outcome": "fail"}]}, {"id": "l-enc-020", "band": "low", "prompt": "同学神秘地说：「我知道一个秘密基地哦～你想去吗？」", "options": [{"id": "a", "text": "「想去想去！我们偷偷去！」", "reply": "嘿嘿，跟我来，不许告诉别人！", "outcome": "win"}, {"id": "b", "text": "「假的，哪有什么基地。」", "reply": "哼，不带你去了。", "outcome": "fail"}, {"id": "c", "text": "「是不是在大树后面？我也有一个！」", "reply": "哇被你猜到了哈哈，那是双倍基地！", "outcome": "funny"}]}, {"id": "l-enc-021", "band": "low", "prompt": "同学拽着你的衣角：「我有点怕黑，你能陪我走吗？」", "options": [{"id": "a", "text": "「能呀，我们手拉手就不怕啦」", "reply": "嗯！有你在我就不怕了~", "outcome": "win"}, {"id": "b", "text": "「胆小鬼，我才不陪。」", "reply": "呜…你好坏。", "outcome": "fail"}]}, {"id": "l-enc-022", "band": "low", "prompt": "同学把帽子戴反了还不知道，挡在你面前。", "options": [{"id": "a", "text": "「你帽子戴反啦，我帮你转过来~」", "reply": "咦，谢谢你！嘻嘻。", "outcome": "win"}, {"id": "b", "text": "「哈哈哈傻样！」笑个不停", "reply": "哼，笑什么笑！", "outcome": "fail"}, {"id": "c", "text": "「酷！我也要把帽子戴反！」", "reply": "哈哈我们是反帽子兄弟！", "outcome": "funny"}]}, {"id": "l-enc-023", "band": "low", "prompt": "同学举着风车跑过来：「你看我的风车转得快不快？」", "options": [{"id": "a", "text": "「好快呀！我们去有风的地方比比！」", "reply": "好耶，冲向操场~", "outcome": "win"}, {"id": "b", "text": "「我的更快，你的破破的。」", "reply": "哼，才不破！", "outcome": "fail"}]}, {"id": "l-enc-024", "band": "low", "prompt": "同学小声哭：「我找不到妈妈了…」", "options": [{"id": "a", "text": "「别怕，我陪你去找老师，会找到的！」", "reply": "呜…嗯，谢谢你陪我。", "outcome": "win"}, {"id": "b", "text": "「那是你的事呀。」", "reply": "哇——你都不帮我！", "outcome": "fail"}]}, {"id": "l-enc-025", "band": "low", "prompt": "同学张开双臂挡路：「过路费！要讲一个笑话才行！」", "options": [{"id": "a", "text": "「为什么小鸟不上学？因为它已经会飞啦！」", "reply": "哈哈哈好冷又好好笑，过吧！", "outcome": "win"}, {"id": "b", "text": "「我不会讲笑话。」", "reply": "不讲就不许过~", "outcome": "fail"}, {"id": "c", "text": "做了个超丑的鬼脸", "reply": "噗哈哈哈你这张脸就是笑话！过吧！", "outcome": "funny"}]}, {"id": "h-enc-001", "band": "high", "prompt": "同学叉着腰挡路：「想过去？先夸我三句！」", "options": [{"id": "a", "text": "「球打得好、字写得好、人还讲义气！」", "reply": "哈哈算你会说，过吧过吧。", "outcome": "win"}, {"id": "b", "text": "「就你？我编不出来。」", "reply": "那你别过了。", "outcome": "fail"}, {"id": "c", "text": "「你睫毛今天有 87 根，比昨天多 1 根。」", "reply": "你有病吧哈哈哈哈。", "outcome": "funny"}]}, {"id": "h-enc-002", "band": "high", "prompt": "同学一脸不爽：「上次你没等我一起走。」", "options": [{"id": "a", "text": "「对不起呀，下次一定等你，给你留了零食🍬」", "reply": "…算你有良心，走吧。", "outcome": "win"}, {"id": "b", "text": "「关我什么事。」", "reply": "行，你厉害。", "outcome": "fail"}, {"id": "c", "text": "「我等了，是你走太慢被我甩开了」", "reply": "?? 你还有理了哈哈哈滚吧。", "outcome": "funny"}]}, {"id": "h-enc-003", "band": "high", "prompt": "同学得意地拦住你：「猜猜我月考考了多少？」", "options": [{"id": "a", "text": "「看你这么嘚瑟，肯定进步了，请客啊！」", "reply": "哈哈被你看穿了，走走走我请你。", "outcome": "win"}, {"id": "b", "text": "「不猜，没兴趣。」", "reply": "切，扫兴。", "outcome": "fail"}, {"id": "c", "text": "「负分？卷子白给的那种？」", "reply": "你嘴怎么这么欠哈哈哈。", "outcome": "funny"}]}, {"id": "h-enc-004", "band": "high", "prompt": "同学故作神秘：「我