011", "band": "high", "prompt": "同学拽住你：「帮我个忙，作业借我抄一下行不行？」", "options": [{"id": "a", "text": "「抄不行，但我可以给你讲，三分钟你就会。」", "reply": "…你还挺负责，行，讲吧，谢了。", "outcome": "win"}, {"id": "b", "text": "「不行，别想。」转身就走", "reply": "切，小气，不借拉倒。", "outcome": "fail"}, {"id": "c", "text": "「可以，但你得帮我背一节课的锅」", "reply": "哈哈哈这交易不划算，算了算了。", "outcome": "funny"}]}, {"id": "h-enc-012", "band": "high", "prompt": "同学得意洋洋：「我新买的鞋，限量款，羡慕不？」", "options": [{"id": "a", "text": "「确实好看，眼光可以啊，哪买的？」", "reply": "嘿嘿识货，回头告诉你链接，走吧。", "outcome": "win"}, {"id": "b", "text": "「不就一双鞋，至于吗。」", "reply": "哼，没品位。", "outcome": "fail"}, {"id": "c", "text": "「限量？我家狗的鞋都比这限量」", "reply": "你家狗还穿鞋?哈哈哈你赢了。", "outcome": "funny"}]}, {"id": "h-enc-013", "band": "high", "prompt": "同学挡路：「最近迷上一款游戏，但卡在一关了，你玩过吗？」", "options": [{"id": "a", "text": "「那关我会！晚上联机带你过。」", "reply": "真的假的，太够意思了，加好友！", "outcome": "win"}, {"id": "b", "text": "「玩物丧志，少打点游戏。」", "reply": "行吧老学究，走开走开。", "outcome": "fail"}]}, {"id": "h-enc-014", "band": "high", "prompt": "同学凑过来：「下周运动会你报名了吗？我们组个队呗。」", "options": [{"id": "a", "text": "「组啊！咱俩接力，目标第一！」", "reply": "就喜欢你这股劲儿，说定了！", "outcome": "win"}, {"id": "b", "text": "「我不参加，太累。」", "reply": "啧，没意思，那我找别人了。", "outcome": "fail"}]}, {"id": "h-enc-015", "band": "high", "prompt": "同学装出一副大佬样：「这条路是我罩的，留下买路财——一根辣条。」", "options": [{"id": "a", "text": "「给给给，大哥赏脸吃根辣条。」掏出辣条", "reply": "哈哈哈识相，自己人，过吧过吧。", "outcome": "win"}, {"id": "b", "text": "「你算老几，让开。」", "reply": "哟，不给面子是吧，那站着别动。", "outcome": "fail"}, {"id": "c", "text": "「辣条没了，给你颗薄荷糖压压惊？」", "reply": "薄荷糖?你打发要饭的呢哈哈哈，算了过吧。", "outcome": "funny"}]}, {"id": "h-enc-016", "band": "high", "prompt": "同学一脸郁闷：「我跟同桌闹掰了，烦。」", "options": [{"id": "a", "text": "「啥事啊，说出来听听，没准是误会。」", "reply": "…你说得对，可能是我想多了，谢了。", "outcome": "win"}, {"id": "b", "text": "「那是你俩的事，跟我说干嘛。」", "reply": "行，当我没说。", "outcome": "fail"}]}, {"id": "h-enc-017", "band": "high", "prompt": "同学挡路：「我新学了个魔术，看穿了算你赢。」开始变扑克。", "options": [{"id": "a", "text": "「先不拆穿，给你点面子，挺溜啊！」", "reply": "哈哈懂事，就喜欢有眼力见的，过！", "outcome": "win"}, {"id": "b", "text": "「这破手法我一眼就看穿了。」", "reply": "切，扫兴，那你也别想看下个。", "outcome": "fail"}, {"id": "c", "text": "「你袖子里那张红桃K掉出来了」", "reply": "啊?!哈哈哈穿帮了穿帮了，丢人。", "outcome": "funny"}]}, {"id": "h-enc-018", "band": "high", "prompt": "同学问：「周末去不去打球？还差一个人。」", "options": [{"id": "a", "text": "「去！几点？我带瓶水给大家。」", "reply": "爽快，就等你这句，定了！", "outcome": "win"}, {"id": "b", "text": "「再说吧，看心情。」", "reply": "行吧，你这态度，那当你不去了。", "outcome": "fail"}]}, {"id": "h-enc-019", "band": "high", "prompt": "同学拿着试卷凑过来：「这题我跟你答案不一样，谁对谁错？」", "options": [{"id": "a", "text": "「来对一下过程，错了的请喝奶茶。」", "reply": "哈哈这个赌注我喜欢，开整！", "outcome": "win"}, {"id": "b", "text": "「肯定我对，你那答案一看就错。」", "reply": "哟，这么自信，万一是你错呢。", "outcome": "fail"}]}, {"id": "h-enc-020", "band": "high", "prompt": "同学神秘兮兮：「我藏了包好吃的，但只分给『自己人』。」", "options": [{"id": "a", "text": "「咱俩什么关系，必须自己人啊！」", "reply": "哈哈会说话，给你一半，拿着。", "outcome": "win"}, {"id": "b", "text": "「不稀罕，留着自己吃吧。」", "reply": "行，那我可全吃了哦。", "outcome": "fail"}, {"id": "c", "text": "「自己人？我都把你当亲哥了」", "reply": "打住打住，肉麻死了哈哈，给你给你。", "outcome": "funny"}]}, {"id": "h-enc-021", "band": "high", "prompt": "同学拦住你想斗嘴：「听说你跑步特慢？乌龟见了你都想超车。」", "options": [{"id": "a", "text": "「那是给你留面子，真跑你吃灰。」", "reply": "哈哈哈嘴是真硬，行，改天操场见真章！", "outcome": "win"}, {"id": "b", "text": "「你才慢，你全家都慢。」", "reply": "哟，急了急了，开不起玩笑。", "outcome": "fail"}, {"id": "c", "text": "「我是慢，但我是为了配合你的智商」", "reply": "哈哈哈哈你这嘴真的欠揍，服了。", "outcome": "funny"}]}, {"id": "h-enc-022", "band": "high", "prompt": "同学愁眉苦脸：「明天要上台演讲，我紧张到睡不着。」", "options": [{"id": "a", "text": "「我帮你听一遍稿子，给你提提意见？」", "reply": "太感谢了，有你这朋友值了。", "outcome": "win"}, {"id": "b", "text": "「自己的事自己搞定。」", "reply": "行行行，打扰你了。", "outcome": "fail"}]}, {"id": "h-enc-023", "band": "high", "prompt": "同学一本正经地胡说：「告诉你个内幕，明天体育课改成全员睡觉课。」", "options": [{"id": "a", "text": "「哦？那我得准备好枕头，配合你演下去。」", "reply": "哈哈哈就你接得住，会玩，过吧！", "outcome": "win"}, {"id": "b", "text": "「编，继续编，能不能上点心。」", "reply": "啧，跟你聊天没劲。", "outcome": "fail"}, {"id": "c", "text": "「真的？！那我现在就去铺床」假装躺下", "reply": "哈哈哈哈别真躺啊，地上凉！", "outcome": "funny"}]}, {"id": "h-enc-024", "band": "high", "prompt": "同学小声说：「我偷偷带了游戏卡，要不要课间一起玩？」", "options": [{"id": "a", "text": "「玩可以，但下课玩、别影响上课，安全第一。」", "reply": "懂分寸，就服你这种，约了！", "outcome": "win"}, {"id": "b", "text": "「带这个干嘛，被没收别哭。」", "reply": "好好好，你最守规矩，走开。", "outcome": "fail"}]}, {"id": "h-enc-025", "band": "high", "prompt": "同学摆出守门员姿势：「想过这条走廊？先跟我玩个梗接龙，接不上不准过。」", "options": [{"id": "a", "text": "「来啊，我梗多得是，看你能撑几个回合。」", "reply": "哈哈哈旗鼓相当，痛快，放你过！", "outcome": "win"}, {"id": "b", "text": "「我不玩这些幼稚的。」", "reply": "不玩?那就别想过，站着吧。", "outcome": "fail"}, {"id": "c", "text": "「我一开口你怕是要笑到扶墙」", "reply": "哈哈哈牛皮先吹上了，行，过吧过吧。", "outcome": "funny"}]}, {"id": "l-enc-026", "band": "low", "prompt": "同学举着一颗糖：「分我一半就让你过～」", "options": [{"id": "a", "text": "「好呀，咱俩一人一半！🍬」", "reply": "嘿嘿你真大方，过吧过吧～", "outcome": "win"}, {"id": "b", "text": "「不给，这是我的！」", "reply": "哼，那你别想过去！", "outcome": "fail"}, {"id": "c", "text": "「我把糖纸分你，糖我自己吃～」", "reply": "啊？糖纸……你好坏哈哈哈！", "outcome": "funny"}]}, {"id": "l-enc-027", "band": "low", "prompt": "分组游戏，没人选的同学小声问：「我能跟你一组吗？」", "options": [{"id": "a", "text": "「当然啦，咱俩一组最厉害！」", "reply": "太好啦，我们一定赢！", "outcome": "win"}, {"id": "b", "text": "「不行，我要跟厉害的。」", "reply": "哦……那好吧。（低下头）", "outcome": "fail"}, {"id": "c", "text": "「可以，但你得当队长扛大旗！」", "reply": "啊我才不要哈哈，好吧我扛！", "outcome": "funny"}]}, {"id": "l-enc-028", "band": "low", "prompt": "同学的彩笔滚到你脚边：「能帮我捡一下吗？」", "options": [{"id": "a", "text": "「给你，接住啦！」", "reply": "谢谢你！你人真好～", "outcome": "win"}, {"id": "b", "text": "「自己捡，懒死了。」", "reply": "（撅嘴）不理你了！", "outcome": "fail"}, {"id": "c", "text": "「捡到了，但我先画朵小花再还你～」", "reply": "哈哈哈你画的什么呀！", "outcome": "funny"}]}, {"id": "l-enc-029", "band": "low", "prompt": "排队时同学不小心踩了你一脚，红着脸说：「对不起……」", "options": [{"id": "a", "text": "「没关系，下次小心点就好啦～」", "reply": "你真好，我们做朋友吧！", "outcome": "win"}, {"id": "b", "text": "「踩疼我啦，赔钱！」", "reply": "我又不是故意的……（要哭了）", "outcome": "fail"}, {"id": "c", "text": "「那你站着别动，我踩回来才公平！」", "reply": "哈哈哈别别别我跑啦！", "outcome": "funny"}]}, {"id": "l-enc-030", "band": "low", "prompt": "同学举着新折的纸飞机：「下课要不要一起飞飞机？」", "options": [{"id": "a", "text": "「好呀好呀，咱俩比谁飞得远！」", "reply": "好耶！下课操场见～", "outcome": "win"}, {"id": "b", "text": "「幼稚，我才不玩。」", "reply": "哦……那我自己玩好了。", "outcome": "fail"}, {"id": "c", "text": "「玩可以，但我的飞机叫超级宇宙号！」", "reply": "噗哈哈那我的叫无敌大番薯！", "outcome": "funny"}]}, {"id": "h-enc-026", "band": "high", "prompt": "同学凑过来：「借我抄一下昨天的笔记呗？」", "options": [{"id": "a", "text": "「笔记给你，不过得自己消化，下次小测我考你！」", "reply": "成交，靠谱兄弟，过吧！", "outcome": "win"}, {"id": "b", "text": "「自己上课干嘛去了，不借。」", "reply": "行，下次别找我。", "outcome": "fail"}, {"id": "c", "text": "「可以，但我的笔记是火星文，你能看懂算你赢。」", "reply": "?? 你这鬼画符是给外星人写的吧哈哈。", "outcome": "funny"}]}, {"id": "h-enc-027", "band": "high", "prompt": "体育课分队，俩人都想当队长，僵住了：「这队长归谁？」", "options": [{"id": "a", "text": "「猜拳决定，输的当副队长，照样很重要。」", "reply": "公平公正，我服，来吧！", "outcome": "win"}, {"id": "b", "text": "「必须我当，你水平不行。」", "reply": "哦豁，那这队我退了。", "outcome": "fail"}, {"id": "c", "text": "「咱俩并列队长，输了就一起背锅。」", "reply": "哈哈哈背锅二人组，成交！", "outcome": "funny"}]}, {"id": "h-enc-028", "band": "high", "prompt": "同学一脸阴沉：「听说你在背后说我打球菜？」", "options": [{"id": "a", "text": "「那是误会，我说的是『得练练』，走，现在单挑教学。」", "reply": "……行吧，那放学球场见，真没说菜就行。", "outcome": "win"}, {"id": "b", "text": "「说了又怎样，本来就菜。」", "reply": "好，记住了。（转身就走）", "outcome": "fail"}, {"id": "c", "text": "「冤枉啊，我夸你菜得很有个人风格。」", "reply": "这是夸还是损啊喂哈哈哈哈。", "outcome": "funny"}]}, {"id": "h-enc-029", "band": "high", "prompt": "同学举着手机：「周末开黑差一个人，带我吗？我手有点抖。」", "options": [{"id": "a", "text": "「带，我罩你，输赢都开心最重要。」", "reply": "兄弟够意思，这把听你指挥！", "outcome": "win"}, {"id": "b", "text": "「不带菜鸟，掉分。」", "reply": "行行行，告辞。", "outcome": "fail"}, {"id": "c", "text": "「带，但你只能当我家『钢铁后勤』负责喊加油。」", "reply": "啊这……人形加油器是吧哈哈哈好吧。", "outcome": "funny"}]}, {"id": "h-enc-030", "band": "high", "prompt": "同学小声说：「这次没考好，我妈那关怕是过不去……」", "options": [{"id": "a", "text": "「一次而已，咱俩一起列个计划，下次稳住。」", "reply": "谢了，有你这句话我心里踏实多了。", "outcome": "win"}, {"id": "b", "text": "「考砸活该，谁让你天天摆烂。」", "reply": "……当我没说。", "outcome": "fail"}, {"id": "c", "text": "「别怕，我陪你一起被骂，咱俩有难同当。」", "reply": "哈哈哈这安慰离谱但莫名感动。", "outcome": "funny"}]}, {"id": "l-enc-031", "band": "low", "prompt": "课间同学举着一盒亮闪闪的新蜡笔，到处晃：「看！新买的，48色！」", "options": [{"id": "a", "text": "借我画一笔嘛，我用我的恐龙贴纸跟你换！", "reply": "成交！但只能画一笔哦……好吧两笔。", "outcome": "win"}, {"id": "b", "text": "（捂眼睛假装被闪瞎）啊——太亮了我看不见啦！", "reply": "哈哈哈你别演了，赶紧睁眼。", "outcome": "funny"}, {"id": "c", "text": "切，我家有96色。", "reply": "……那你家的呢？没带是吧。", "outcome": "fail"}]}, {"id": "l-enc-032", "band": "low", "prompt": "排队喝水，前面同学半天不接水，光在那拧瓶盖。", "options": [{"id": "a", "text": "我帮你拧吧，你接水，咱俩快一点。", "reply": "哇你力气真大！谢啦，下一个就你了。", "outcome": "win"}, {"id": "b", "text": "盖子：我赢了。你：……", "reply": "扑哧——这盖子是成精了。", "outcome": "funny"}, {"id": "c", "text": "快点啦快点啦你怎么这么慢！", "reply": "你越喊我越拧不开了啦！", "outcome": "fail"}]}, {"id": "l-enc-033", "band": "low", "prompt": "同桌带了一袋小饼干，瞄了你一眼，没说话。", "options": [{"id": "a", "text": "我有橡皮糖，咱俩换着尝呗？", "reply": "好耶！你这个糖是西瓜味的吗？给我一个我给你两块饼干！", "outcome": "win"}, {"id": "b", "text": "（盯着饼干，狗狗眼，一动不动）", "reply": "你这个眼神……行行行给你一块，别看我了。", "outcome": "funny"}, {"id": "c", "text": "直接伸手抓一把。", "reply": "诶诶诶！我还没说给你呢！", "outcome": "fail"}]}, {"id": "l-enc-034", "band": "low", "prompt": "你不小心踩到了同学的脚，他「哎哟」一声瞪你。", "options": [{"id": "a", "text": "啊对不起！我帮你吹吹？（蹲下假装吹）", "reply": "哈哈哈不用吹啦，没事没事，你这人挺好玩。", "outcome": "win"}, {"id": "b", "text": "是地板自己跳起来的，不怪我。", "reply": "……地板：这锅我不背。", "outcome": "funny"}, {"id": "c", "text": "谁让你脚伸那么长。", "reply": "我脚就在这放着！是你没长眼！", "outcome": "fail"}]}, {"id": "l-enc-035", "band": "low", "prompt": "同学神秘兮兮：「我跟你说个秘密，你别告诉别人哦。」", "options": [{"id": "a", "text": "我嘴最严了，说吧——（做拉拉链动作）", "reply": "好！其实……我今天袜子穿反了，嘘——", "outcome": "win"}, {"id": "b", "text": "（捂耳朵）我不听我不听，我怕憋不住！", "reply": "哈哈哈那算了，等你嘴严了再说。", "outcome": "funny"}, {"id": "c", "text": "什么秘密？我现在就去问问全班。", "reply": "诶你回来！我还没说呢你别瞎说啊！", "outcome": "fail"}]}, {"id": "l-enc-036", "band": "low", "prompt": "玩老鹰捉小鸡，同学非要当老鹰，谁劝都不听。", "options": [{"id": "a", "text": "那你先当老鹰，下一局换我当，咱俩说好啦！", "reply": "一言为定！我当老鹰可厉害了，你们小鸡跑快点！", "outcome": "win"}, {"id": "b", "text": "好啊那我当母鸡，专门保护小鸡，看你抓不抓得到。", "reply": "嘿你这母鸡还挺横！来抓我啊抓我啊！", "outcome": "funny"}, {"id": "c", "text": "不行就得我当，凭什么都听你的。", "reply": "那……那咱不玩了，没意思。", "outcome": "fail"}]}, {"id": "l-enc-037", "band": "low", "prompt": "老师让两人一组,剩下你和一个有点害羞、低着头的同学。", "options": [{"id": "a", "text": "那咱俩一组吧！我画画不太行，你帮我把把关呗？", "reply": "（抬起头）……好啊！其实我画画还可以的。", "outcome": "win"}, {"id": "b", "text": "命运把咱俩绑一块了，认命吧搭档！（伸手击掌）", "reply": "噗……（小声）啪。（轻轻拍了一下你的手）", "outcome": "funny"}, {"id": "c", "text": "唉，怎么剩我跟你。", "reply": "……（头更低了，不说话）", "outcome": "fail"}]}, {"id": "l-enc-038", "band": "low", "prompt": "同学举着一张画问你：「我画的小狗好看吗？」其实……画得有点像土豆。", "options": [{"id": "a", "text": "这耳朵画得真有意思！再添两根胡子,我看就更精神了！", "reply": "对哦！加胡子！你眼光真好，我这就加！", "outcome": "win"}, {"id": "b", "text": "好看！这是一只……圆滚滚的小狗，对吧？", "reply": "嘿你怎么知道它就是圆的!它叫胖墩!", "outcome": "funny"}, {"id": "c", "text": "这哪是狗啊,这是个土豆。", "reply": "……哼，不给你看了。", "outcome": "fail"}]}, {"id": "h-enc-031", "band": "high", "prompt": "课上你俩传纸条被老师逮个正着，老师扫过来：「刚才谁在说话？」同学用胳膊肘悄悄顶你。", "options": [{"id": "a", "text": "（小声）咱俩都别认，证据呢，老师又没看见嘴动。", "reply": "（憋笑）行，攻守同盟，这波稳了。", "outcome": "win"}, {"id": "b", "text": "（站起来一脸正气）报告老师，我怀疑是穿堂风。", "reply": "穿堂风……你可真是我的法务部部长。", "outcome": "funny"}, {"id": "c", "text": "（指同学）老师是他先传给我的。", "reply": "好哇你卖队友？下回纸条没你的份了。", "outcome": "fail"}]}, {"id": "h-enc-032", "band": "high", "prompt": "小组作业，有个同学全程划水一个字没写，最后却说：「咱们这组配合得真好。」", "options": [{"id": "a", "text": "配合是不错，那PPT你来讲呗，毕竟你『贡献』最大。", "reply": "啊这……要不还是你讲吧，我去买奶茶犒劳大家？", "outcome": "win"}, {"id": "b", "text": "对，特别是你那部分——空白页，留白艺术，高级。", "reply": "哈哈哈别说了，那页我标个『此处无声胜有声』。", "outcome": "funny"}, {"id": "c", "text": "你做啥了你就配合？白拿分还有理了。", "reply": "行行行算我没说，至于这么冲吗。", "outcome": "fail"}]}, {"id": "h-enc-033", "band": "high", "prompt": "同学拿到月考成绩，故意凑过来:「哎你这次多少分啊?我反正——还行吧。」一脸欠揍。", "options": [{"id": "a", "text": "你『还行』脸上写着九十五,藏着掖着干嘛,直说嘛学霸。", "reply": "嘿被你看穿了……九十六。下次借你抄笔记?", "outcome": "win"}, {"id": "b", "text": "我考了个『下次一定』,满分『再说吧』。", "reply": "哈哈哈这科系我没听过,挺难的吧。", "outcome": "funny"}, {"id": "c", "text": "关你什么事,显摆够了没。", "reply": "我就随口一问……至于吗你。", "outcome": "fail"}]}, {"id": "h-enc-034", "band": "high", "prompt": "你新换了发型,有点翻车。一进教室,损友第一时间冲上来:「哟!这头是被门夹了?」", "options": [{"id": "a", "text": "时尚你不懂,这叫『随性凌乱风』,下周全校都得学我。", "reply": "得得得,潮流教父,改天带带我呗。", "outcome": "win"}, {"id": "b", "text": "嘘,这是我和理发师吵架的证据,正在维权。", "reply": "哈哈哈维权成功记得分我点精神损失费。", "outcome": "funny"}, {"id": "c", "text": "你管得着吗,你那头型也好不到哪去。", "reply": "我就开个玩笑……火气这么大。", "outcome": "fail"}]}, {"id": "h-enc-035", "band": "high", "prompt": "你忘带笔了,想跟邻桌借,可你俩平时不太熟,他正低头写作业。", "options": [{"id": "a", "text": "（轻轻碰一下）大佬,救命,匀我支笔,下课请你喝水(食堂免费那种)。", "reply": "（笑）就你会说,给,免费水大气!", "outcome": "win"}, {"id": "b", "text": "（默默把空笔袋抖给他看,一脸生无可恋）", "reply": "哈哈哈行行行,你这无声的呐喊我收到了,拿去。", "outcome": "funny"}, {"id": "c", "text": "（一把抽走他桌上的笔）借用一下啊。", "reply": "诶?!你这是借还是抢啊?", "outcome": "fail"}]}, {"id": "h-enc-036", "band": "high", "prompt": "你跟同学约好放学一起走,结果他临时被叫去办公室,让你等。你都等二十分钟了。", "options": [{"id": "a", "text": "（发消息）我在小卖部续命,你出来直接来找我,不急。", "reply": "够意思!我马上好,给你带瓶冰的赔罪!", "outcome": "win"}, {"id": "b", "text": "（发消息）再不来我可要把你那份零食先『保管』了啊。", "reply": "别啊!那是我的!我跑步过来了我跑步过来了!", "outcome": "funny"}, {"id": "c", "text": "（直接走了,不等了）", "reply": "……人呢?说好一起走的,真不讲义气。", "outcome": "fail"}]}, {"id": "h-enc-037", "band": "high", "prompt": "班里转来个新同学,一个人坐着,谁也不认识,显得有点尴尬。", "options": [{"id": "a", "text": "（凑过去）哥们儿,这班最大的雷我先告诉你——别买食堂周三的炒面。", "reply": "哈哈哈第一条情报就这么实用?你这朋友我交定了。", "outcome": "win"}, {"id": "b", "text": "（递过去半块橡皮）入伙费,收下你就是自己人了。", "reply": "就……半块?你们这帮派挺穷啊。（笑）", "outcome": "funny"}, {"id": "c", "text": "（瞄一眼,没理,继续玩自己的）", "reply": "……（新同学默默低下头）", "outcome": "fail"}]}, {"id": "h-enc-038", "band": "high", "prompt": "你不小心把同学的水杯碰倒了,水洒了他半张卷子。他脸一沉。", "options": [{"id": "a", "text": "啊对不起!我抽纸,你抢救卷子,快——这字还能认!", "reply": "（一边擦一边笑）反应挺快啊你,行吧,看你态度诚恳。", "outcome": "win"}, {"id": "b", "text": "好消息:你的卷子现在防水了。坏消息:就这一张。", "reply": "哈哈哈你还有理了?快帮我擦!", "outcome": "funny"}, {"id": "c", "text": "谁让你水杯放那么靠边,活该。", "reply": "??是你碰的还赖我?这人没法处了。", "outcome": "fail"}]}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
insert into public.game_content (game, data, updated_at) values ('battle-fitness', $seed$[{"id": "fit-rope-low-easy", "band": "low", "name": "跳绳挑战·入门", "unit": "次", "emoji": "🪢", "sport": "rope", "target": 20, "durationSec": 60}, {"id": "fit-rope-low-hard", "band": "low", "name": "跳绳挑战·进阶", "unit": "次", "emoji": "🪢", "sport": "rope", "target": 30, "durationSec": 60}, {"id": "fit-rope-high-easy", "band": "high", "name": "跳绳挑战·入门", "unit": "次", "emoji": "🪢", "sport": "rope", "target": 45, "durationSec": 60}, {"id": "fit-rope-high-hard", "band": "high", "name": "跳绳挑战·进阶", "unit": "次", "emoji": "🪢", "sport": "rope", "target": 60, "durationSec": 60}, {"id": "fit-situp-low", "band": "low", "name": "仰卧起坐挑战", "unit": "次", "emoji": "🤸", "sport": "situp", "target": 8, "durationSec": 60}, {"id": "fit-situp-high", "band": "high", "name": "仰卧起坐挑战", "unit": "次", "emoji": "🤸", "sport": "situp", "target": 18, "durationSec": 60}, {"id": "fit-sitreach-low", "band": "low", "name": "坐位体前屈挑战", "unit": "秒", "emoji": "🧘", "sport": "sitreach", "target": 5, "durationSec": 5}, {"id": "fit-sitreach-high", "band": "high", "name": "坐位体前屈挑战", "unit": "秒", "emoji": "🧘", "sport": "sitreach", "target": 8, "durationSec": 8}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
insert into public.game_content (game, data, updated_at) values ('battle-questions', $seed$[{"id": "low-math-001", "band": "low", "answer": "b", "prompt": "一只手有几根手指头呀？", "choices": [{"id": "a", "text": "4根"}, {"id": "b", "text": "5根"}, {"id": "c", "text": "6根"}], "subject": "math", "explanation": "张开一只手数一数：1、2、3、4、5，正好5根。"}, {"id": "low-math-002", "band": "low", "answer": "b", "prompt": "🍎🍎🍎 桌上有几个苹果？", "choices": [{"id": "a", "text": "2个"}, {"id": "b", "text": "3个"}, {"id": "c", "text": "4个"}], "subject": "math", "explanation": "一个一个数：1个、2个、3个，是3个苹果。"}, {"id": "low-math-003", "band": "low", "answer": "b", "prompt": "2 加 3 等于几？", "choices": [{"id": "a", "text": "4"}, {"id": "b", "text": "5"}, {"id": "c", "text": "6"}], "subject": "math", "explanation": "2个再添上3个，一起就是5个。"}, {"id": "low-math-004", "band": "low", "answer": "b", "prompt": "你有 5 颗糖，吃掉 2 颗，还剩几颗？", "choices": [{"id": "a", "text": "2颗"}, {"id": "b", "text": "3颗"}, {"id": "c", "text": "4颗"}], "subject": "math", "explanation": "5颗去掉2颗，还剩下3颗。"}, {"id": "low-math-005", "band": "low", "answer": "a", "prompt": "哪个数更大：7 还是 4？", "choices": [{"id": "a", "text": "7大"}, {"id": "b", "text": "4大"}, {"id": "c", "text": "一样大"}], "subject": "math", "explanation": "7比4多，所以7更大。"}, {"id": "low-math-006", "band": "low", "answer": "b", "prompt": "⭐⭐⭐⭐ 天上有几颗小星星？", "choices": [{"id": "a", "text": "3颗"}, {"id": "b", "text": "4颗"}, {"id": "c", "text": "5颗"}], "subject": "math", "explanation": "一颗一颗数：1、2、3、4，是4颗星星。"}, {"id": "low-math-007", "band": "low", "answer": "b", "prompt": "6 加 6 等于几？", "choices": [{"id": "a", "text": "11"}, {"id": "b", "text": "12"}, {"id": "c", "text": "13"}], "subject": "math", "explanation": "6再加6，就是12。"}, {"id": "low-math-008", "band": "low", "answer": "b", "prompt": "10 减 4 等于几？", "choices": [{"id": "a", "text": "5"}, {"id": "b", "text": "6"}, {"id": "c", "text": "7"}], "subject": "math", "explanation": "10个拿走4个，还剩6个。"}, {"id": "low-math-009", "band": "low", "answer": "b", "prompt": "小猫🐱🐱有2只，小狗🐶有1只，一共几只小动物？", "choices": [{"id": "a", "text": "2只"}, {"id": "b", "text": "3只"}, {"id": "c", "text": "4只"}], "subject": "math", "explanation": "2只猫加上1只狗，一共3只。"}, {"id": "low-math-010", "band": "low", "answer": "a", "prompt": "数一数：1、2、3、__，横线上应该填几？", "choices": [{"id": "a", "text": "4"}, {"id": "b", "text": "5"}, {"id": "c", "text": "6"}], "subject": "math", "explanation": "按顺序数下去，3的后面就是4。"}, {"id": "low-math-011", "band": "low", "answer": "b", "prompt": "哪个数最小：8、3、5？", "choices": [{"id": "a", "text": "8"}, {"id": "b", "text": "3"}, {"id": "c", "text": "5"}], "subject": "math", "explanation": "3比5小，5比8小，所以3最小。"}, {"id": "low-math-012", "band": "low", "answer": "b", "prompt": "9 加 1 等于几？", "choices": [{"id": "a", "text": "9"}, {"id": "b", "text": "10"}, {"id": "c", "text": "11"}], "subject": "math", "explanation": "9再添上1，正好凑成10。"}, {"id": "low-math-013", "band": "low", "answer": "b", "prompt": "🚗🚗🚗🚗🚗 停车场有几辆小汽车？", "choices": [{"id": "a", "text": "4辆"}, {"id": "b", "text": "5辆"}, {"id": "c", "text": "6辆"}], "subject": "math", "explanation": "数一数：1、2、3、4、5，是5辆车。"}, {"id": "low-math-014", "band": "low", "answer": "b", "prompt": "7 减 3 等于几？", "choices": [{"id": "a", "text": "3"}, {"id": "b", "text": "4"}, {"id": "c", "text": "5"}], "subject": "math", "explanation": "7个去掉3个，还剩4个。"}, {"id": "low-math-015", "band": "low", "answer": "b", "prompt": "8 加 5 等于几？", "choices": [{"id": "a", "text": "12"}, {"id": "b", "text": "13"}, {"id": "c", "text": "14"}], "subject": "math", "explanation": "8先凑到10要借2，5里拿出2，剩下3，10加3就是13。"}, {"id": "low-math-016", "band": "low", "answer": "c", "prompt": "一个星期有几天呀？", "choices": [{"id": "a", "text": "5天"}, {"id": "b", "text": "6天"}, {"id": "c", "text": "7天"}], "subject": "math", "explanation": "从星期一数到星期日，一共7天。"}, {"id": "low-math-017", "band": "low", "answer": "b", "prompt": "🐟🐟🐟🐟🐟🐟 鱼缸里有几条鱼？", "choices": [{"id": "a", "text": "5条"}, {"id": "b", "text": "6条"}, {"id": "c", "text": "7条"}], "subject": "math", "explanation": "一条一条数：1到6，是6条鱼。"}, {"id": "low-math-018", "band": "low", "answer": "a", "prompt": "12 比 9 怎么样？", "choices": [{"id": "a", "text": "12比9大"}, {"id": "b", "text": "12比9小"}, {"id": "c", "text": "一样多"}], "subject": "math", "explanation": "12比10还多，9比10少，所以12大。"}, {"id": "low-math-019", "band": "low", "answer": "b", "prompt": "盘子里有4块饼干，妈妈又放了4块，现在有几块？", "choices": [{"id": "a", "text": "7块"}, {"id": "b", "text": "8块"}, {"id": "c", "text": "9块"}], "subject": "math", "explanation": "原来4块，再加4块，一共8块。"}, {"id": "low-math-020", "band": "low", "answer": "b", "prompt": "从大往小数：5、4、3、__，横线上填几？", "choices": [{"id": "a", "text": "1"}, {"id": "b", "text": "2"}, {"id": "c", "text": "6"}], "subject": "math", "explanation": "一个比一个少1，3的后面就是2。"}, {"id": "low-math-021", "band": "low", "answer": "b", "prompt": "20 减 10 等于几？", "choices": [{"id": "a", "text": "5"}, {"id": "b", "text": "10"}, {"id": "c", "text": "15"}], "subject": "math", "explanation": "20里拿走10，还剩10。"}, {"id": "low-math-022", "band": "low", "answer": "b", "prompt": "🎈🎈🎈🎈🎈🎈🎈 手里有几个气球？", "choices": [{"id": "a", "text": "6个"}, {"id": "b", "text": "7个"}, {"id": "c", "text": "8个"}], "subject": "math", "explanation": "一个一个数：1到7，是7个气球。"}, {"id": "low-chinese-001", "band": "low", "answer": "a", "prompt": "“妈妈”的“妈”读什么音呀？", "choices": [{"id": "a", "text": "mā（第一声）"}, {"id": "b", "text": "mǎ（第三声）"}, {"id": "c", "text": "mà（第四声）"}], "subject": "chinese", "explanation": "“妈”读 mā，是平平的第一声。"}, {"id": "low-chinese-002", "band": "low", "answer": "a", "prompt": "小鸭子的“鸭”，拼音是哪个？", "choices": [{"id": "a", "text": "yā"}, {"id": "b", "text": "yá"}, {"id": "c", "text": "wā"}], "subject": "chinese", "explanation": "“鸭”读 yā，跟小鸭叫的声音有点像。"}, {"id": "low-chinese-003", "band": "low", "answer": "a", "prompt": "“水”这个字的拼音是？", "choices": [{"id": "a", "text": "shuǐ"}, {"id": "b", "text": "shuì"}, {"id": "c", "text": "suí"}], "subject": "chinese", "explanation": "“水”读 shuǐ，第三声，喝的水。"}, {"id": "low-chinese-004", "band": "low", "answer": "a", "prompt": "“e”这个韵母，读起来像哪个？", "choices": [{"id": "a", "text": "鹅 é 的声音"}, {"id": "b", "text": "衣 i 的声音"}, {"id": "c", "text": "乌 u 的声音"}], "subject": "chinese", "explanation": "小鹅“é é é”，“e”就读这个音。"}, {"id": "low-chinese-005", "band": "low", "answer": "b", "prompt": "“太阳”的“阳”读第几声？", "choices": [{"id": "a", "text": "第一声 yāng"}, {"id": "b", "text": "第二声 yáng"}, {"id": "c", "text": "第三声 yǎng"}], "subject": "chinese", "explanation": "“阳”读 yáng，第二声，往上扬一扬。"}, {"id": "low-chinese-006", "band": "low", "answer": "a", "prompt": "“一”这个字有几画？", "choices": [{"id": "a", "text": "1 画"}, {"id": "b", "text": "2 画"}, {"id": "c", "text": "3 画"}], "subject": "chinese", "explanation": "“一”就是横着写一笔，只有 1 画。"}, {"id": "low-chinese-007", "band": "low", "answer": "b", "prompt": "“十”字一共要写几笔？", "choices": [{"id": "a", "text": "1 笔"}, {"id": "b", "text": "2 笔"}, {"id": "c", "text": "4 笔"}], "subject": "chinese", "explanation": "“十”是一横加一竖，2 笔。"}, {"id": "low-chinese-008", "band": "low", "answer": "b", "prompt": "“口”字有几画？", "choices": [{"id": "a", "text": "2 画"}, {"id": "b", "text": "3 画"}, {"id": "c", "text": "4 画"}], "subject": "chinese", "explanation": "“口”是一个小方框，写起来是 3 画。"}, {"id": "low-chinese-009", "band": "low", "answer": "b", "prompt": "“火”字一共有几画？", "choices": [{"id": "a", "text": "3 画"}, {"id": "b", "text": "4 画"}, {"id": "c", "text": "5 画"}], "subject": "chinese", "explanation": "“火”是 4 画，像跳动的火苗。"}, {"id": "low-chinese-010", "band": "low", "answer": "a", "prompt": "“大”字可以组成下面哪个词？", "choices": [{"id": "a", "text": "大象"}, {"id": "b", "text": "小猫"}, {"id": "c", "text": "河水"}], "subject": "chinese", "explanation": "“大象”里有“大”字，大象的鼻子长长的。"}, {"id": "low-chinese-011", "band": "low", "answer": "a", "prompt": "用“花”能组成哪个词？", "choices": [{"id": "a", "text": "花朵"}, {"id": "b", "text": "小狗"}, {"id": "c", "text": "太阳"}], "subject": "chinese", "explanation": "“花朵”里有“花”，开得香香的。"}, {"id": "low-chinese-012", "band": "low", "answer": "a", "prompt": "“天”字能跟哪个字组成词？", "choices": [{"id": "a", "text": "天空"}, {"id": "b", "text": "吃饭"}, {"id": "c", "text": "走路"}], "subject": "chinese", "explanation": "“天空”里有“天”，蓝蓝的天空。"}, {"id": "low-chinese-013", "band": "low", "answer": "a", "prompt": "下面哪个词里有“月”字？", "choices": [{"id": "a", "text": "月亮"}, {"id": "b", "text": "苹果"}, {"id": "c", "text": "汽车"}], "subject": "chinese", "explanation": "“月亮”里有“月”，晚上挂在天上。"}, {"id": "low-chinese-014", "band": "low", "answer": "a", "prompt": "“大”的反义词是什么？", "choices": [{"id": "a", "text": "小"}, {"id": "b", "text": "多"}, {"id": "c", "text": "高"}], "subject": "chinese", "explanation": "大的反过来就是小，大苹果、小苹果。"}, {"id": "low-chinese-015", "band": "low", "answer": "a", "prompt": "“上”的反义词是哪个？", "choices": [{"id": "a", "text": "下"}, {"id": "b", "text": "左"}, {"id": "c", "text": "前"}], "subject": "chinese", "explanation": "“上”对着“下”，上楼、下楼。"}, {"id": "low-chinese-016", "band": "low", "answer": "a", "prompt": "“多”的反义词是什么？", "choices": [{"id": "a", "text": "少"}, {"id": "b", "text": "好"}, {"id": "c", "text": "白"}], "subject": "chinese", "explanation": "糖很多，糖很少，“多”和“少”是反着的。"}, {"id": "low-chinese-017", "band": "low", "answer": "a", "prompt": "“黑”的反义词是哪个？", "choices": [{"id": "a", "text": "白"}, {"id": "b", "text": "红"}, {"id": "c", "text": "冷"}], "subject": "chinese", "explanation": "黑黑的夜、白白的云，“黑”对“白”。"}, {"id": "low-chinese-018", "band": "low", "answer": "a", "prompt": "“开”的反义词是什么？", "choices": [{"id": "a", "text": "关"}, {"id": "b", "text": "跑"}, {"id": "c", "text": "坐"}], "subject": "chinese", "explanation": "开门、关门，“开”和“关”是一对。"}, {"id": "low-chinese-019", "band": "low", "answer": "a", "prompt": "一（   ）小鱼，应该填哪个字？", "choices": [{"id": "a", "text": "条"}, {"id": "b", "text": "只"}, {"id": "c", "text": "本"}], "subject": "chinese", "explanation": "小鱼长长的，要说“一条小鱼”。"}, {"id": "low-chinese-020", "band": "low", "answer": "a", "prompt": "一（   ）书，填哪个量词最合适？", "choices": [{"id": "a", "text": "本"}, {"id": "b", "text": "条"}, {"id": "c", "text": "头"}], "subject": "chinese", "explanation": "书要说“一本书”，可以翻着看。"}, {"id": "low-chinese-021", "band": "low", "answer": "a", "prompt": "一（   ）小猫，应该用哪个量词？", "choices": [{"id": "a", "text": "只"}, {"id": "b", "text": "张"}, {"id": "c", "text": "棵"}], "subject": "chinese", "explanation": "小动物常说“一只”，一只小猫喵喵叫。"}, {"id": "low-chinese-022", "band": "low", "answer": "a", "prompt": "一（   ）大树，填哪个字呢？", "choices": [{"id": "a", "text": "棵"}, {"id": "b", "text": "只"}, {"id": "c", "text": "本"}], "subject": "chinese", "explanation": "树要说“一棵树”，高高地长在地上。"}, {"id": "low-english-001", "band": "low", "answer": "a", "prompt": "“苹果”用英语怎么说呀？", "choices": [{"id": "a", "text": "apple"}, {"id": "b", "text": "banana"}, {"id": "c", "text": "orange"}], "subject": "english", "explanation": "apple 就是苹果，红红圆圆的那个～"}, {"id": "low-english-002", "band": "low", "answer": "b", "prompt": "小猫咪用英语叫什么？", "choices": [{"id": "a", "text": "dog（小狗）"}, {"id": "b", "text": "cat（小猫）"}, {"id": "c", "text": "fish（鱼）"}], "subject": "english", "explanation": "cat 就是猫咪，喵喵～"}, {"id": "low-english-003", "band": "low", "answer": "c", "prompt": "红色用英语怎么说？", "choices": [{"id": "a", "text": "blue（蓝色）"}, {"id": "b", "text": "green（绿色）"}, {"id": "c", "text": "red（红色）"}], "subject": "english", "explanation": "red 是红色，像小苹果一样～"}, {"id": "low-english-004", "band": "low", "answer": "b", "prompt": "数字“3”用英语怎么写？", "choices": [{"id": "a", "text": "two"}, {"id": "b", "text": "three"}, {"id": "c", "text": "four"}], "subject": "english", "explanation": "three 就是 3，one two three！"}, {"id": "low-english-005", "band": "low", "answer": "a", "prompt": "字母 A 后面是哪个字母？", "choices": [{"id": "a", "text": "B"}, {"id": "b", "text": "C"}, {"id": "c", "text": "D"}], "subject": "english", "explanation": "A、B、C…… A 的好朋友是 B 哦～"}, {"id": "low-english-006", "band": "low", "answer": "b", "prompt": "“狗狗”用英语怎么说？", "choices": [{"id": "a", "text": "pig（猪）"}, {"id": "b", "text": "dog（狗）"}, {"id": "c", "text": "duck（鸭子）"}], "subject": "english", "explanation": "dog 就是小狗，汪汪汪～"}, {"id": "low-english-007", "band": "low", "answer": "a", "prompt": "黄色用英语怎么说？", "choices": [{"id": "a", "text": "yellow（黄色）"}, {"id": "b", "text": "black（黑色）"}, {"id": "c", "text": "white（白色）"}], "subject": "english", "explanation": "yellow 是黄色，像小鸭子和太阳～"}, {"id": "low-english-008", "band": "low", "answer": "b", "prompt": "“香蕉”用英语怎么说？", "choices": [{"id": "a", "text": "apple"}, {"id": "b", "text": "banana"}, {"id": "c", "text": "grape"}], "subject": "english", "explanation": "banana 就是弯弯的香蕉～"}, {"id": "low-english-009", "band": "low", "answer": "a", "prompt": "数字“1”用英语怎么说？", "choices": [{"id": "a", "text": "one"}, {"id": "b", "text": "ten"}, {"id": "c", "text": "nine"}], "subject": "english", "explanation": "one 就是 1，最小的那个数～"}, {"id": "low-english-010", "band": "low", "answer": "b", "prompt": "蓝色用英语怎么说？（像天空一样）", "choices": [{"id": "a", "text": "pink（粉色）"}, {"id": "b", "text": "blue（蓝色）"}, {"id": "c", "text": "brown（棕色）"}], "subject": "english", "explanation": "blue 是蓝色，像晴天的大天空～"}, {"id": "low-english-011", "band": "low", "answer": "c", "prompt": "字母 C 后面是哪个字母？", "choices": [{"id": "a", "text": "A"}, {"id": "b", "text": "B"}, {"id": "c", "text": "D"}], "subject": "english", "explanation": "A B C D…… C 后面就是 D 啦～"}, {"id": "low-english-012", "band": "low", "answer": "b", "prompt": "“水”用英语怎么说？", "choices": [{"id": "a", "text": "milk（牛奶）"}, {"id": "b", "text": "water（水）"}, {"id": "c", "text": "egg（鸡蛋）"}], "subject": "english", "explanation": "water 就是水，渴了要喝 water～"}, {"id": "low-english-013", "band": "low", "answer": "a", "prompt": "绿色用英语怎么说？（像小草一样）", "choices": [{"id": "a", "text": "green（绿色）"}, {"id": "b", "text": "red（红色）"}, {"id": "c", "text": "orange（橙色）"}], "subject": "english", "explanation": "green 是绿色，像小草和大树～"}, {"id": "low-english-014", "band": "low", "answer": "b", "prompt": "数字“5”用英语怎么说？（一只手有几个手指）", "choices": [{"id": "a", "text": "six"}, {"id": "b", "text": "five"}, {"id": "c", "text": "four"}], "subject": "english", "explanation": "five 就是 5，一只小手有五根手指～"}, {"id": "low-english-015", "band": "low", "answer": "a", "prompt": "“妈妈”用英语怎么叫？", "choices": [{"id": "a", "text": "mom（妈妈）"}, {"id": "b", "text": "dad（爸爸）"}, {"id": "c", "text": "baby（宝宝）"}], "subject": "english", "explanation": "mom 就是妈妈，最爱你的人～"}, {"id": "low-english-016", "band": "low", "answer": "b", "prompt": "“爸爸”用英语怎么叫？", "choices": [{"id": "a", "text": "mom（妈妈）"}, {"id": "b", "text": "dad（爸爸）"}], "subject": "english", "explanation": "dad 就是爸爸～"}, {"id": "low-english-017", "band": "low", "answer": "a", "prompt": "“鸟”用英语怎么说？（会飞的小动物）", "choices": [{"id": "a", "text": "bird（鸟）"}, {"id": "b", "text": "fish（鱼）"}, {"id": "c", "text": "cat（猫）"}], "subject": "english", "explanation": "bird 就是小鸟，叽叽喳喳飞呀飞～"}, {"id": "low-english-018", "band": "low", "answer": "b", "prompt": "黑色用英语怎么说？（晚上天黑黑的颜色）", "choices": [{"id": "a", "text": "white（白色）"}, {"id": "b", "text": "black（黑色）"}, {"id": "c", "text": "yellow（黄色）"}], "subject": "english", "explanation": "black 是黑色，像晚上的天空～"}, {"id": "low-english-019", "band": "low", "answer": "a", "prompt": "字母表里最开始的第一个字母是哪个？", "choices": [{"id": "a", "text": "A"}, {"id": "b", "text": "Z"}, {"id": "c", "text": "M"}], "subject": "english", "explanation": "A 是第一个字母，唱歌就从 A 开始～"}, {"id": "low-english-020", "band": "low", "answer": "a", "prompt": "数字“2”用英语怎么说？", "choices": [{"id": "a", "text": "two"}, {"id": "b", "text": "three"}, {"id": "c", "text": "one"}], "subject": "english", "explanation": "two 就是 2，两只小眼睛～"}, {"id": "low-english-021", "band": "low", "answer": "b", "prompt": "“鱼”用英语怎么说？（在水里游的）", "choices": [{"id": "a", "text": "bird（鸟）"}, {"id": "b", "text": "fish（鱼）"}, {"id": "c", "text": "dog（狗）"}], "subject": "english", "explanation": "fish 就是小鱼，在水里游来游去～"}, {"id": "low-english-022", "band": "low", "answer": "a", "prompt": "白色用英语怎么说？（像云朵和雪一样）", "choices": [{"id": "a", "text": "white（白色）"}, {"id": "b", "text": "black（黑色）"}, {"id": "c", "text": "blue（蓝色）"}], "subject": "english", "explanation": "white 是白色，像白云和雪花～"}, {"id": "low-science-001", "band": "low", "answer": "a", "prompt": "小狗高兴的时候，会怎么摇？", "choices": [{"id": "a", "text": "摇尾巴"}, {"id": "b", "text": "摇耳朵"}, {"id": "c", "text": "摇鼻子"}], "subject": "science", "explanation": "小狗开心或者亲近你的时候，会摇摇小尾巴。"}, {"id": "low-science-002", "band": "low", "answer": "b", "prompt": "小兔子最爱吃下面哪个呀？", "choices": [{"id": "a", "text": "骨头"}, {"id": "b", "text": "胡萝卜和青菜"}, {"id": "c", "text": "小鱼"}], "subject": "science", "explanation": "小兔子爱吃胡萝卜、青草和青菜这些植物。"}, {"id": "low-science-003", "band": "low", "answer": "b", "prompt": "小鸟是用什么飞到天上的？", "choices": [{"id": "a", "text": "用腿跳"}, {"id": "b", "text": "用翅膀"}, {"id": "c", "text": "用尾巴"}], "subject": "science", "explanation": "小鸟扇动翅膀，就能飞起来啦。"}, {"id": "low-science-004", "band": "low", "answer": "a", "prompt": "下雨之前，天上的云一般是什么样子？", "choices": [{"id": "a", "text": "灰灰黑黑的"}, {"id": "b", "text": "亮亮白白的"}, {"id": "c", "text": "没有云"}], "subject": "science", "explanation": "快下雨的时候，云会变得灰灰黑黑、厚厚的。"}, {"id": "low-science-005", "band": "low", "answer": "a", "prompt": "冬天很冷的时候，水会变成什么？", "choices": [{"id": "a", "text": "冰"}, {"id": "b", "text": "糖"}, {"id": "c", "text": "油"}], "subject": "science", "explanation": "天太冷的时候，水会结成硬硬的冰。"}, {"id": "low-science-006", "band": "low", "answer": "b", "prompt": "我们用身体的哪个部分来闻香味？", "choices": [{"id": "a", "text": "耳朵"}, {"id": "b", "text": "鼻子"}, {"id": "c", "text": "手"}], "subject": "science", "explanation": "我们用鼻子来闻花香、闻饭香。"}, {"id": "low-science-007", "band": "low", "answer": "c", "prompt": "我们用哪里来听声音？", "choices": [{"id": "a", "text": "眼睛"}, {"id": "b", "text": "嘴巴"}, {"id": "c", "text": "耳朵"}], "subject": "science", "explanation": "耳朵是用来听声音的，听爸爸妈妈说话、听音乐。"}, {"id": "low-science-008", "band": "low", "answer": "b", "prompt": "一只手有几根手指头？", "choices": [{"id": "a", "text": "三根"}, {"id": "b", "text": "五根"}, {"id": "c", "text": "十根"}], "subject": "science", "explanation": "一只手有五根手指，两只手加起来是十根。"}, {"id": "low-science-009", "band": "low", "answer": "b", "prompt": "小树苗想长大，最需要什么？", "choices": [{"id": "a", "text": "糖果"}, {"id": "b", "text": "阳光和水"}, {"id": "c", "text": "玩具"}], "subject": "science", "explanation": "植物要晒太阳、要喝水，才能慢慢长大。"}, {"id": "low-science-010", "band": "low", "answer": "b", "prompt": "花一般是从哪里长出来的？", "choices": [{"id": "a", "text": "从天上掉下来"}, {"id": "b", "text": "从植物上开出来"}, {"id": "c", "text": "从水里冒出来"}], "subject": "science", "explanation": "花是植物开出来的，先有花骨朵，再慢慢开放。"}, {"id": "low-science-011", "band": "low", "answer": "a", "prompt": "小鱼住在哪里呀？", "choices": [{"id": "a", "text": "水里"}, {"id": "b", "text": "树上"}, {"id": "c", "text": "天上"}], "subject": "science", "explanation": "小鱼用鳃呼吸，住在水里，离开水会不舒服。"}, {"id": "low-science-012", "band": "low", "answer": "a", "prompt": "太阳出来的时候，天气一般是怎样的？", "choices": [{"id": "a", "text": "晴天，亮亮的"}, {"id": "b", "text": "黑漆漆的"}, {"id": "c", "text": "下大雪"}], "subject": "science", "explanation": "太阳高高挂着、没有乌云，就是晴天。"}, {"id": "low-science-013", "band": "low", "answer": "a", "prompt": "下雪天，外面会变成什么颜色？", "choices": [{"id": "a", "text": "白白的"}, {"id": "b", "text": "红红的"}, {"id": "c", "text": "绿绿的"}], "subject": "science", "explanation": "雪是白色的，下完雪，地上、树上都变白啦。"}, {"id": "low-science-014", "band": "low", "answer": "b", "prompt": "小猫喜欢用什么声音叫？", "choices": [{"id": "a", "text": "汪汪"}, {"id": "b", "text": "喵喵"}, {"id": "c", "text": "咕咕"}], "subject": "science", "explanation": "小猫叫起来是“喵喵”，小狗才是“汪汪”。"}, {"id": "low-science-015", "band": "low", "answer": "a", "prompt": "我们用身体的哪里来走路、跑步？", "choices": [{"id": "a", "text": "腿和脚"}, {"id": "b", "text": "头"}, {"id": "c", "text": "肚子"}], "subject": "science", "explanation": "我们用两条腿和脚走路、跑步、跳来跳去。"}, {"id": "low-science-016", "band": "low", "answer": "a", "prompt": "小蜜蜂飞到花上，是去做什么？", "choices": [{"id": "a", "text": "采花蜜"}, {"id": "b", "text": "睡觉"}, {"id": "c", "text": "洗澡"}], "subject": "science", "explanation": "小蜜蜂在花上采花蜜，回去做成甜甜的蜂蜜。"}, {"id": "low-science-017", "band": "low", "answer": "b", "prompt": "刮大风的时候，树叶会怎么样？", "choices": [{"id": "a", "text": "一动不动"}, {"id": "b", "text": "摇来摇去、飘起来"}, {"id": "c", "text": "变成红色"}], "subject": "science", "explanation": "风一吹，树枝树叶就会摇晃，叶子也会飘起来。"}, {"id": "low-science-018", "band": "low", "answer": "b", "prompt": "牙齿是用来做什么的？", "choices": [{"id": "a", "text": "看东西"}, {"id": "b", "text": "咬东西、嚼食物"}, {"id": "c", "text": "听声音"}], "subject": "science", "explanation": "牙齿帮我们咬东西、嚼食物，要好好刷牙保护它。"}, {"id": "low-science-019", "band": "low", "answer": "a", "prompt": "大象的鼻子有什么特别的地方？", "choices": [{"id": "a", "text": "又长又能卷东西"}, {"id": "b", "text": "会发光"}, {"id": "c", "text": "会唱歌"}], "subject": "science", "explanation": "大象的鼻子又长又灵活，能卷起食物、还能吸水。"}, {"id": "low-science-020", "band": "low", "answer": "a", "prompt": "青蛙小时候叫什么？", "choices": [{"id": "a", "text": "小蝌蚪"}, {"id": "b", "text": "小蚂蚁"}, {"id": "c", "text": "小蜗牛"}], "subject": "science", "explanation": "青蛙小时候是黑黑的小蝌蚪，长大才变成青蛙。"}, {"id": "low-science-021", "band": "low", "answer": "a", "prompt": "我们的眼睛是用来做什么的？", "choices": [{"id": "a", "text": "看东西"}, {"id": "b", "text": "吃饭"}, {"id": "c", "text": "走路"}], "subject": "science", "explanation": "眼睛帮我们看东西，看书的时候要注意保护眼睛。"}, {"id": "low-science-022", "band": "low", "answer": "b", "prompt": "到了晚上，天上会出现什么？", "choices": [{"id": "a", "text": "太阳"}, {"id": "b", "text": "月亮和星星"}, {"id": "c", "text": "彩虹"}], "subject": "science", "explanation": "白天有太阳，到了晚上就能看到月亮和一闪一闪的星星。"}, {"id": "low-sports-001", "band": "low", "answer": "b", "prompt": "踢足球的时候，我们主要用身体的哪个部位去踢球呀？", "choices": [{"id": "a", "text": "用手"}, {"id": "b", "text": "用脚"}, {"id": "c", "text": "用头顶"}], "subject": "sports", "explanation": "足球主要用脚踢，守门员才可以用手哦。"}, {"id": "low-sports-002", "band": "low", "answer": "a", "prompt": "打篮球的时候，我们要把球投进哪里才算得分？", "choices": [{"id": "a", "text": "投进篮筐"}, {"id": "b", "text": "踢进球门"}, {"id": "c", "text": "扔进水桶"}], "subject": "sports", "explanation": "篮球要投进高高的篮筐里，进了就得分啦。"}, {"id": "low-sports-003", "band": "low", "answer": "a", "prompt": "上体育课跑步之前，老师为什么先带大家做热身运动？", "choices": [{"id": "a", "text": "为了让身体活动开，不容易受伤"}, {"id": "b", "text": "为了浪费时间"}, {"id": "c", "text": "为了让大家睡觉"}], "subject": "sports", "explanation": "先热身把身体活动开，跑起来才不容易拉伤、扭伤。"}, {"id": "low-sports-004", "band": "low", "answer": "a", "prompt": "游泳的时候我们是在哪里活动呀？", "choices": [{"id": "a", "text": "在水里"}, {"id": "b", "text": "在树上"}, {"id": "c", "text": "在沙坑里"}], "subject": "sports", "explanation": "游泳是在水里进行的运动，下水前要先做热身哦。"}, {"id": "low-sports-005", "band": "low", "answer": "b", "prompt": "骑自行车的时候，为了保护头，我们最好戴上什么？", "choices": [{"id": "a", "text": "帽子手套"}, {"id": "b", "text": "头盔"}, {"id": "c", "text": "围巾"}], "subject": "sports", "explanation": "骑车戴头盔，万一摔倒了也能保护我们的小脑袋。"}, {"id": "low-sports-006", "band": "low", "answer": "a", "prompt": "小朋友跳绳的时候，绳子是用什么甩起来的？", "choices": [{"id": "a", "text": "用两只手甩"}, {"id": "b", "text": "用嘴巴咬"}, {"id": "c", "text": "用脚踢"}], "subject": "sports", "explanation": "跳绳是两只手一起甩绳子，脚再一下一下跳过去。"}, {"id": "low-sports-007", "band": "low", "answer": "b", "prompt": "运动出了很多汗，觉得口渴了，应该怎么办？", "choices": [{"id": "a", "text": "一口气喝很多冰水"}, {"id": "b", "text": "慢慢喝一点温水"}, {"id": "c", "text": "忍着不喝"}], "subject": "sports", "explanation": "运动后慢慢喝点温水最舒服，喝太急或太冰肚子会不舒服。"}, {"id": "low-sports-008", "band": "low", "answer": "a", "prompt": "乒乓球比赛里，我们用什么来打球？", "choices": [{"id": "a", "text": "球拍"}, {"id": "b", "text": "扫把"}, {"id": "c", "text": "勺子"}], "subject": "sports", "explanation": "乒乓球要用小小的球拍来打，乒乒乓乓真好玩。"}, {"id": "low-sports-009", "band": "low", "answer": "a", "prompt": "赛跑的时候，谁会先到达终点？", "choices": [{"id": "a", "text": "跑得最快的人"}, {"id": "b", "text": "跑得最慢的人"}, {"id": "c", "text": "站着不动的人"}], "subject": "sports", "explanation": "赛跑就是比谁快，跑得最快的人最先冲过终点线。"}, {"id": "low-sports-010", "band": "low", "answer": "c", "prompt": "羽毛球飞起来的时候，毛茸茸的那一头叫什么？", "choices": [{"id": "a", "text": "皮球"}, {"id": "b", "text": "毽子"}, {"id": "c", "text": "羽毛球"}], "subject": "sports", "explanation": "羽毛球的一头白白软软像羽毛，用球拍打来打去。"}, {"id": "low-sports-011", "band": "low", "answer": "a", "prompt": "上体育课，穿哪一种鞋子跑跳最合适？", "choices": [{"id": "a", "text": "运动鞋"}, {"id": "b", "text": "小皮鞋"}, {"id": "c", "text": "拖鞋"}], "subject": "sports", "explanation": "运动鞋软软的、不打滑，跑跳起来又稳又舒服。"}, {"id": "low-sports-012", "band": "low", "answer": "b", "prompt": "老鹰捉小鸡这个游戏里，小朋友们要做什么？", "choices": [{"id": "a", "text": "一直坐着"}, {"id": "b", "text": "排成一队躲老鹰"}, {"id": "c", "text": "闭着眼睛走路"}], "subject": "sports", "explanation": "小鸡们排成一队跟着鸡妈妈，躲开来捉它们的老鹰。"}, {"id": "low-sports-013", "band": "low", "answer": "a", "prompt": "小朋友踢毽子，毽子主要是用哪里踢的？", "choices": [{"id": "a", "text": "用脚的内侧踢"}, {"id": "b", "text": "用鼻子顶"}, {"id": "c", "text": "用耳朵接"}], "subject": "sports", "explanation": "踢毽子常用脚的内侧轻轻踢，毽子就一上一下啦。"}, {"id": "low-sports-014", "band": "low", "answer": "a", "prompt": "运动完了身体很累，回家应该怎么做才对身体好？", "choices": [{"id": "a", "text": "好好休息、早点睡觉"}, {"id": "b", "text": "通宵不睡接着玩"}, {"id": "c", "text": "一动也不动一整天"}], "subject": "sports", "explanation": "运动后好好休息、睡个好觉，身体才长得壮壮的。"}, {"id": "low-sports-015", "band": "low", "answer": "a", "prompt": "玩滑梯、爬攀爬架的时候，下面有什么会比较安全？", "choices": [{"id": "a", "text": "软软的垫子或沙子"}, {"id": "b", "text": "硬硬的石头"}, {"id": "c", "text": "尖尖的钉子"}], "subject": "sports", "explanation": "下面铺软软的垫子或沙子，万一摔下来也没那么疼。"}, {"id": "low-sports-016", "band": "low", "answer": "a", "prompt": "看图猜一猜：一个圆圆的球被踢进了有网的球门里，这是什么运动？", "choices": [{"id": "a", "text": "足球"}, {"id": "b", "text": "下棋"}, {"id": "c", "text": "画画"}], "subject": "sports", "explanation": "把球踢进球门，这就是大家都爱玩的足球啦。"}, {"id": "low-sports-017", "band": "low", "answer": "a", "prompt": "玩游戏时不小心摔倒了，膝盖有点疼，最先应该怎么办？", "choices": [{"id": "a", "text": "告诉老师或大人"}, {"id": "b", "text": "偷偷藏起来不说"}, {"id": "c", "text": "继续使劲跑"}], "subject": "sports", "explanation": "受伤了要赶紧告诉老师或大人，让他们帮忙看一看。"}, {"id": "low-sports-018", "band": "low", "answer": "a", "prompt": "小朋友拍皮球的时候，皮球碰到地面会怎么样？", "choices": [{"id": "a", "text": "弹起来"}, {"id": "b", "text": "飞到天上不下来"}, {"id": "c", "text": "变成方块"}], "subject": "sports", "explanation": "皮球软软圆圆的，拍一下碰到地就一蹦一蹦弹起来。"}, {"id": "low-sports-019", "band": "low", "answer": "b", "prompt": "冬天小朋友堆雪人、打雪仗，是在什么季节玩的运动？", "choices": [{"id": "a", "text": "夏天"}, {"id": "b", "text": "冬天"}, {"id": "c", "text": "什么时候都行"}], "subject": "sports", "explanation": "只有冬天下雪了，才能堆雪人、打雪仗，玩得手都凉啦。"}, {"id": "low-sports-020", "band": "low", "answer": "a", "prompt": "运动场上想要做得好，平时最应该怎么样？", "choices": [{"id": "a", "text": "多多练习"}, {"id": "b", "text": "从来不练"}, {"id": "c", "text": "只看别人玩"}], "subject": "sports", "explanation": "只要多多练习，跑得就更快、跳得就更高啦。"}, {"id": "low-sports-021", "band": "low", "answer": "a", "prompt": "做广播体操的时候，小朋友们应该怎么做？", "choices": [{"id": "a", "text": "跟着音乐认真做动作"}, {"id": "b", "text": "坐在地上不动"}, {"id": "c", "text": "互相推来推去"}], "subject": "sports", "explanation": "广播体操要跟着音乐认真做，伸伸胳膊踢踢腿才有用。"}, {"id": "low-sports-022", "band": "low", "answer": "b", "prompt": "比赛输了的时候，一个好朋友应该怎么做呀？", "choices": [{"id": "a", "text": "大哭大闹生气"}, {"id": "b", "text": "笑一笑，下次再加油"}, {"id": "c", "text": "怪别人不帮忙"}], "subject": "sports", "explanation": "输了也没关系，笑一笑，下次再努力就好啦。"}, {"id": "low-life-001", "band": "low", "answer": "b", "prompt": "时钟上短针指着 3，长针指着 12，现在是几点？", "choices": [{"id": "a", "text": "12 点"}, {"id": "b", "text": "3 点"}, {"id": "c", "text": "6 点"}], "subject": "life", "explanation": "短针指几就是几点，长针指 12 表示整点，所以是 3 点。"}, {"id": "low-life-002", "band": "low", "answer": "a", "prompt": "长针指到 6，短针在 8 和 9 中间，现在大约是几点几分？", "choices": [{"id": "a", "text": "8 点半"}, {"id": "b", "text": "6 点整"}, {"id": "c", "text": "9 点整"}], "subject": "life", "explanation": "长针指 6 是 30 分，短针刚过 8，就是 8 点半。"}, {"id": "low-life-003", "band": "low", "answer": "b", "prompt": "一个棒棒糖卖 2 块钱，你给阿姨 5 块钱，应该找回几块？", "choices": [{"id": "a", "text": "2 块"}, {"id": "b", "text": "3 块"}, {"id": "c", "text": "5 块"}], "subject": "life", "explanation": "5 块减去 2 块，找回 3 块钱。"}, {"id": "low-life-004", "band": "low", "answer": "c", "prompt": "下面哪个是最大的钱？", "choices": [{"id": "a", "text": "1 块"}, {"id": "b", "text": "5 毛"}, {"id": "c", "text": "10 块"}], "subject": "life", "explanation": "10 块比 1 块和 5 毛都大。"}, {"id": "low-life-005", "band": "low", "answer": "a", "prompt": "买东西花了 8 块钱，你有一张 10 块的，够不够付？", "choices": [{"id": "a", "text": "够，还能找钱"}, {"id": "b", "text": "不够"}], "subject": "life", "explanation": "10 块比 8 块多，够付，还能找回 2 块。"}, {"id": "low-life-006", "band": "low", "answer": "c", "prompt": "过马路的时候，红绿灯是什么颜色才可以走？", "choices": [{"id": "a", "text": "红灯"}, {"id": "b", "text": "黄灯"}, {"id": "c", "text": "绿灯"}], "subject": "life", "explanation": "红灯停，绿灯行，绿灯亮了才能走。"}, {"id": "low-life-007", "band": "low", "answer": "a", "prompt": "过马路应该走哪里最安全？", "choices": [{"id": "a", "text": "斑马线"}, {"id": "b", "text": "马路中间"}, {"id": "c", "text": "哪里近走哪里"}], "subject": "life", "explanation": "过马路要走斑马线，还要先看看左右有没有车。"}, {"id": "low-life-008", "band": "low", "answer": "b", "prompt": "明天要上语文、数学和美术课，整理书包应该装什么？", "choices": [{"id": "a", "text": "只装语文书"}, {"id": "b", "text": "语文、数学、美术的东西都装好"}, {"id": "c", "text": "装一堆玩具"}], "subject": "life", "explanation": "按明天的课，把每节课要用的东西都准备齐。"}, {"id": "low-life-009", "band": "low", "answer": "b", "prompt": "写完作业后，铅笔、橡皮应该放哪儿？", "choices": [{"id": "a", "text": "扔在地上"}, {"id": "b", "text": "收进文具盒里"}, {"id": "c", "text": "随便丢在床上"}], "subject": "life", "explanation": "用完的文具放回文具盒，下次好找又整齐。"}, {"id": "low-life-010", "band": "low", "answer": "b", "prompt": "玩完积木以后，正确的做法是？", "choices": [{"id": "a", "text": "留在地上等别人收"}, {"id": "b", "text": "自己把积木收进盒子"}], "subject": "life", "explanation": "玩具自己玩完自己收好，房间才不会乱。"}, {"id": "low-life-011", "band": "low", "answer": "a", "prompt": "脏衣服换下来以后，应该放进哪里？", "choices": [{"id": "a", "text": "脏衣篮"}, {"id": "b", "text": "塞回干净的衣柜"}, {"id": "c", "text": "丢在沙发上"}], "subject": "life", "explanation": "脏衣服放进脏衣篮，等着洗，别和干净衣服混在一起。"}, {"id": "low-life-012", "band": "low", "answer": "b", "prompt": "吃完的香蕉皮应该扔进哪个垃圾桶？", "choices": [{"id": "a", "text": "可回收垃圾"}, {"id": "b", "text": "厨余垃圾（湿垃圾）"}, {"id": "c", "text": "有害垃圾"}], "subject": "life", "explanation": "香蕉皮、剩饭这些会烂掉的，属于厨余（湿）垃圾。"}, {"id": "low-life-013", "band": "low", "answer": "a", "prompt": "喝完的塑料矿泉水瓶，应该放进哪个垃圾桶？", "choices": [{"id": "a", "text": "可回收垃圾"}, {"id": "b", "text": "厨余垃圾"}], "subject": "life", "explanation": "干净的塑料瓶可以回收再用，放可回收垃圾桶。"}, {"id": "low-life-014", "band": "low", "answer": "b", "prompt": "用过的废电池应该扔进哪个垃圾桶？", "choices": [{"id": "a", "text": "可回收垃圾"}, {"id": "b", "text": "有害垃圾"}, {"id": "c", "text": "厨余垃圾"}], "subject": "life", "explanation": "废电池里有对环境有害的东西，要放有害垃圾桶。"}, {"id": "low-life-015", "band": "low", "answer": "b", "prompt": "外面在下雪，又冷又飘雪花，你出门该穿什么？", "choices": [{"id": "a", "text": "短袖和凉鞋"}, {"id": "b", "text": "厚棉袄和帽子"}, {"id": "c", "text": "游泳衣"}], "subject": "life", "explanation": "下雪天很冷，要穿厚棉袄、戴帽子才暖和。"}, {"id": "low-life-016", "band": "low", "answer": "a", "prompt": "天上下大雨，出门要带什么才不会淋湿？", "choices": [{"id": "a", "text": "雨伞"}, {"id": "b", "text": "太阳镜"}, {"id": "c", "text": "扇子"}], "subject": "life", "explanation": "下雨天带上雨伞或穿雨衣，就不会被淋湿啦。"}, {"id": "low-life-017", "band": "low", "answer": "b", "prompt": "夏天太阳很大、很热，最合适穿哪样？", "choices": [{"id": "a", "text": "羽绒服"}, {"id": "b", "text": "薄薄的短袖"}, {"id": "c", "text": "厚毛衣"}], "subject": "life", "explanation": "天热就穿薄一点的短袖，凉快又舒服。"}, {"id": "low-life-018", "band": "low", "answer": "a", "prompt": "别人帮了你的忙，你应该说什么？", "choices": [{"id": "a", "text": "谢谢"}, {"id": "b", "text": "不理他"}, {"id": "c", "text": "走开"}], "subject": "life", "explanation": "别人帮了你要说“谢谢”，这样很有礼貌。"}, {"id": "low-life-019", "band": "low", "answer": "a", "prompt": "不小心踩到了别人的脚，应该怎么办？", "choices": [{"id": "a", "text": "说“对不起”"}, {"id": "b", "text": "假装没看见"}, {"id": "c", "text": "怪别人挡路"}], "subject": "life", "explanation": "做错了事要主动说“对不起”，这是讲礼貌的好孩子。"}, {"id": "low-life-020", "band": "low", "answer": "b", "prompt": "早上见到老师，应该怎么打招呼？", "choices": [{"id": "a", "text": "低头快走过去"}, {"id": "b", "text": "说“老师早上好”"}], "subject": "life", "explanation": "见到老师主动问好，说“老师早上好”很有礼貌。"}, {"id": "low-life-021", "band": "low", "answer": "b", "prompt": "有陌生人给你糖、说带你去玩，你应该怎么做？", "choices": [{"id": "a", "text": "高兴地跟他走"}, {"id": "b", "text": "不要，告诉爸爸妈妈或老师"}, {"id": "c", "text": "把糖吃了再说"}], "subject": "life", "explanation": "不能跟陌生人走，要赶紧告诉爸爸妈妈或老师。"}, {"id": "low-life-022", "band": "low", "answer": "b", "prompt": "家里着火了，应该打哪个电话求救？", "choices": [{"id": "a", "text": "110"}, {"id": "b", "text": "119"}, {"id": "c", "text": "120"}], "subject": "life", "explanation": "着火了打 119 找消防员叔叔来救火。"}, {"id": "low-social-001", "band": "low", "answer": "b", "prompt": "同桌借了你的橡皮，过了好几天还没还，你想要回来，怎么说最好？", "choices": [{"id": "a", "text": "“你怎么老不还，赖皮！”"}, {"id": "b", "text": "“我的橡皮你用完了吗？能还给我啦～”"}, {"id": "c", "text": "什么都不说，偷偷从他书包里拿走"}], "subject": "social", "explanation": "好好提醒一下就行，对方多半是忘了，温柔说话朋友更愿意还。"}, {"id": "low-social-002", "band": "low", "answer": "a", "prompt": "排队打饭的时候，有个小朋友想插到你前面，你说哪句最棒？", "choices": [{"id": "a", "text": "“后面排队哦，大家都在等呢。”"}, {"id": "b", "text": "使劲把他推开"}, {"id": "c", "text": "“你再插队我就告诉全班！”"}], "subject": "social", "explanation": "提醒排队既守规矩又不吵架，是最聪明的做法。"}, {"id": "low-social-003", "band": "low", "answer": "b", "prompt": "分组做游戏，没人选你，你心里有点难过，怎么做最好？", "choices": [{"id": "a", "text": "一个人躲在角落生闷气"}, {"id": "b", "text": "走过去笑着问：“我可以加入你们吗？”"}, {"id": "c", "text": "大哭着说“你们都不喜欢我”"}], "subject": "social", "explanation": "主动问一句，大多数小朋友都会欢迎你，勇敢一点就好啦。"}, {"id": "low-social-004", "band": "low", "answer": "b", "prompt": "今天轮到你和小明一起值日，可小明跑出去玩了，你该怎么办？", "choices": [{"id": "a", "text": "我也不扫了，撒手就走"}, {"id": "b", "text": "去找小明：“一起扫吧，扫完我们就能去玩啦！”"}, {"id": "c", "text": "把垃圾全推到小明的座位下面"}], "subject": "social", "explanation": "叫上小朋友一起干，活儿做得快，还不会闹矛盾。"}, {"id": "low-social-005", "band": "low", "answer": "a", "prompt": "你和好朋友因为抢秋千吵架了，现在你想和好，怎么开口最好？", "choices": [{"id": "a", "text": "“刚才我也有不对，我们一起玩好不好？”"}, {"id": "b", "text": "等他先来道歉，不然就不理他"}, {"id": "c", "text": "“哼，再也不跟你玩了！”"}], "subject": "social", "explanation": "先伸出手的人最勇敢，一句“我们一起玩”就能把朋友找回来。"}, {"id": "low-social-006", "band": "low", "answer": "a", "prompt": "同学不小心碰倒了你的水杯，水洒了一桌子，他连说对不起，你怎么回最好？", "choices": [{"id": "a", "text": "“没关系，我们一起擦干净吧。”"}, {"id": "b", "text": "“你赔我！哭哭哭！”"}, {"id": "c", "text": "也去碰倒他的水杯"}], "subject": "social", "explanation": "别人是不小心的，说声没关系再一起收拾，大家都开心。"}, {"id": "low-social-007", "band": "low", "answer": "b", "prompt": "你想用同学的彩笔画画，正确的做法是？", "choices": [{"id": "a", "text": "不打招呼直接拿来用"}, {"id": "b", "text": "问一句：“可以借我用一下彩笔吗？”"}, {"id": "c", "text": "趁他不在偷偷拿走"}], "subject": "social", "explanation": "借东西先问一声，是对小朋友的尊重，对方也更乐意借给你。"}, {"id": "low-social-008", "band": "low", "answer": "c", "prompt": "你借了同学的故事书，不小心折了一页，怎么做最棒？", "choices": [{"id": "a", "text": "假装没看见，悄悄还回去"}, {"id": "b", "text": "把书藏起来不还了"}, {"id": "c", "text": "把页角抚平，告诉他：“对不起，我不小心折到了。”"}], "subject": "social", "explanation": "诚实说出来才是好朋友，藏起来反而会让对方更难过。"}, {"id": "low-social-009", "band": "low", "answer": "a", "prompt": "上课时新来的同学找不到铅笔，急得快哭了，你会怎么做？", "choices": [{"id": "a", "text": "小声说：“别急，我借你一支。”"}, {"id": "b", "text": "笑他：“连铅笔都没有！”"}, {"id": "c", "text": "装作没看见"}], "subject": "social", "explanation": "帮一把新同学，他会记住你的好，你们说不定就成了朋友。"}, {"id": "low-social-010", "band": "low", "answer": "b", "prompt": "做手工，组里只有一把剪刀，大家都想先用，怎么办最好？", "choices": [{"id": "a", "text": "抢到手里谁也不给"}, {"id": "b", "text": "“我们一个一个轮流用吧。”"}, {"id": "c", "text": "把剪刀藏到自己抽屉里"}], "subject": "social", "explanation": "轮流用最公平，谁都能玩到，组里也不会吵架。"}, {"id": "low-social-011", "band": "low", "answer": "b", "prompt": "有同学叫你的外号取笑你，你又生气又难过，最聪明的回应是？", "choices": [{"id": "a", "text": "也给他取个更难听的外号"}, {"id": "b", "text": "认真地说：“我不喜欢这个外号，请叫我的名字。”"}, {"id": "c", "text": "动手打他"}], "subject": "social", "explanation": "清清楚楚说出自己的感受，比吵架打架更有力量。"}, {"id": "low-social-012", "band": "low", "answer": "a", "prompt": "你和同学都说自己跑得最快，谁也不让谁，怎么解决最好玩？", "choices": [{"id": "a", "text": "“那我们比一场，输了也不许哭哦！”"}, {"id": "b", "text": "“你才跑不快，吹牛！”"}, {"id": "c", "text": "气得不理他了"}], "subject": "social", "explanation": "与其吵嘴，不如来一场快乐的比赛，结果一比就知道啦。"}, {"id": "low-social-013", "band": "low", "answer": "a", "prompt": "好朋友今天没带午饭的水果，眼巴巴看着你的，你会怎么做？", "choices": [{"id": "a", "text": "“我分你一半，我们一起吃！”"}, {"id": "b", "text": "赶紧全部吃光"}, {"id": "c", "text": "“这是我的，不给你！”"}], "subject": "social", "explanation": "分享一半，快乐变成两份，好朋友就是这样越来越亲。"}, {"id": "low-social-014", "band": "low", "answer": "b", "prompt": "小组比赛，你们组输了，有人开始怪队友，你说哪句最暖心？", "choices": [{"id": "a", "text": "“都怪你，要不是你我们就赢了！”"}, {"id": "b", "text": "“没关系，下次我们一起加油！”"}, {"id": "c", "text": "“这组太差了，我不玩了。”"}], "subject": "social", "explanation": "输了不怪人、一起想下次，这样的队友谁都喜欢。"}, {"id": "low-social-015", "band": "low", "answer": "c", "prompt": "你看到两个同学吵架，越吵越凶，你能帮的好办法是？", "choices": [{"id": "a", "text": "凑过去喊“打起来打起来”"}, {"id": "b", "text": "走开当没看见"}, {"id": "c", "text": "劝一劝：“别吵啦，有话好好说，要不要找老师帮忙？”"}], "subject": "social", "explanation": "当个小小和事佬，劝几句或请老师帮忙，比起哄要好得多。"}, {"id": "low-social-016", "band": "low", "answer": "b", "prompt": "同学送了你一张他亲手画的画，可你不太喜欢，怎么回最有礼貌？", "choices": [{"id": "a", "text": "“好难看，我不要。”"}, {"id": "b", "text": "“谢谢你！你画画送给我，我很开心。”"}, {"id": "c", "text": "一把把画揉成团"}], "subject": "social", "explanation": "别人的心意要珍惜，说声谢谢，对方画得更带劲啦。"}, {"id": "low-social-017", "band": "low", "answer": "a", "prompt": "你不小心踩到了同学的脚，他“哎哟”叫了一声，你该怎么做？", "choices": [{"id": "a", "text": "赶紧说：“对不起，踩疼你了吗？”"}, {"id": "b", "text": "装作不是自己踩的"}, {"id": "c", "text": "“谁让你脚伸那么长！”"}], "subject": "social", "explanation": "一句真诚的对不起，能让小磕碰马上变得没什么大不了。"}, {"id": "low-social-018", "band": "low", "answer": "b", "prompt": "排队的时候你前面的小朋友系鞋带蹲下了，后面的人都急着往前挤，你怎么做最好？", "choices": [{"id": "a", "text": "推他一把：“快点啦！”"}, {"id": "b", "text": "等他一下：“别急，你系好我们再走。”"}, {"id": "c", "text": "从他身上跨过去"}], "subject": "social", "explanation": "多等一小会儿，给别人一点时间，队伍照样很快就走起来。"}, {"id": "low-social-019", "band": "low", "answer": "b", "prompt": "值日时你已经扫完地了，可同学的活儿还没干完，你会怎么做？", "choices": [{"id": "a", "text": "“我扫完了，我先走啦，拜拜！”"}, {"id": "b", "text": "“我帮你一起擦黑板吧，快一点！”"}, {"id": "c", "text": "坐在旁边看他干，还催他快点"}], "subject": "social", "explanation": "搭把手帮同学，活儿干得快，你也会被夸是好帮手。"}, {"id": "low-social-020", "band": "low", "answer": "a", "prompt": "同学约你下课一起玩，可你今天想自己安静地看书，怎么说最好？", "choices": [{"id": "a", "text": "“今天我想看会儿书，明天再一起玩好吗？”"}, {"id": "b", "text": "“别烦我！”"}, {"id": "c", "text": "不说话扭头就走"}], "subject": "social", "explanation": "不想去也能好好说，约下次一起玩，朋友就不会误会你。"}, {"id": "low-social-021", "band": "low", "answer": "a", "prompt": "你和同学闹了别扭一整天，放学想和好，怎么做最暖？", "choices": [{"id": "a", "text": "走过去说：“我们别生气啦，明天一起上学好不好？”"}, {"id": "b", "text": "继续板着脸谁也不理"}, {"id": "c", "text": "回家跟妈妈说他坏话"}], "subject": "social", "explanation": "别让小别扭过夜，主动说和好，明天又是开开心心的一天。"}, {"id": "low-social-022", "band": "low", "answer": "a", "prompt": "同学借了你的尺子，到了放学还在用，你提醒他还，他说“等一下”，你怎么回最棒？", "choices": [{"id": "a", "text": "“好，那你用完记得还我哦，我等你。”"}, {"id": "b", "text": "直接抢过来：“给我！”"}, {"id": "c", "text": "“你再不还我就再也不借你了！”"}], "subject": "social", "explanation": "耐心等一会儿、再轻轻提醒，既守住了东西又守住了朋友。"}, {"id": "low-interest-001", "band": "low", "answer": "a", "prompt": "小猪佩奇最喜欢做的一件事是什么？", "choices": [{"id": "a", "text": "跳泥坑"}, {"id": "b", "text": "爬大树"}, {"id": "c", "text": "钓大鱼"}], "subject": "interest", "explanation": "佩奇和弟弟乔治最爱穿着雨靴跳泥坑啦。"}, {"id": "low-interest-002", "band": "low", "answer": "b", "prompt": "汪汪队里负责开警车、戴蓝帽子的是哪只小狗？", "choices": [{"id": "a", "text": "毛毛"}, {"id": "b", "text": "阿奇"}, {"id": "c", "text": "天天"}], "subject": "interest", "explanation": "阿奇是警犬，开着警车帮大家解决问题。"}, {"id": "low-interest-003", "band": "low", "answer": "b", "prompt": "玩积木的时候，下面哪种搭法最容易倒？", "choices": [{"id": "a", "text": "大块在下面，小块在上面"}, {"id": "b", "text": "小块在下面，大块压上面"}, {"id": "c", "text": "一块一块平平地铺开"}], "subject": "interest", "explanation": "下小上大头重脚轻，轻轻一碰就倒啦。"}, {"id": "low-interest-004", "band": "low", "answer": "a", "prompt": "踢足球的时候，球进了哪里才算得分？", "choices": [{"id": "a", "text": "踢进球门"}, {"id": "b", "text": "踢出场外"}, {"id": "c", "text": "踢到天上"}], "subject": "interest", "explanation": "把球踢进对方的球门就得一分。"}, {"id": "low-interest-005", "band": "low", "answer": "b", "prompt": "玩跳绳，绳子转一圈，脚要怎么做？", "choices": [{"id": "a", "text": "一直站着不动"}, {"id": "b", "text": "在绳子过来时往上跳一下"}, {"id": "c", "text": "坐到地上"}], "subject": "interest", "explanation": "绳子到脚边时轻轻一跳，就跳过去啦。"}, {"id": "low-interest-006", "band": "low", "answer": "b", "prompt": "画太阳的时候，太阳一般涂成什么颜色？", "choices": [{"id": "a", "text": "黑色"}, {"id": "b", "text": "黄色或红色"}, {"id": "c", "text": "绿色"}], "subject": "interest", "explanation": "太阳暖暖的，小朋友常画成黄色或红色。"}, {"id": "low-interest-007", "band": "low", "answer": "a", "prompt": "搭乐高最后多出来一两块小零件，应该怎么办最好？", "choices": [{"id": "a", "text": "收进盒子里别弄丢"}, {"id": "b", "text": "扔进垃圾桶"}, {"id": "c", "text": "吃进肚子里"}], "subject": "interest", "explanation": "小零件要收好，别丢了也千万别放进嘴里。"}, {"id": "low-interest-008", "band": "low", "answer": "a", "prompt": "奥特曼一般是用来做什么的英雄？", "choices": [{"id": "a", "text": "打怪兽、保护大家"}, {"id": "b", "text": "做饭给大家吃"}, {"id": "c", "text": "专门捣乱"}], "subject": "interest", "explanation": "奥特曼是变大打怪兽、保护城市的英雄。"}, {"id": "low-interest-009", "band": "low", "answer": "b", "prompt": "骑自行车想停下来，应该怎么做？", "choices": [{"id": "a", "text": "使劲蹬得更快"}, {"id": "b", "text": "捏刹车，慢慢停"}, {"id": "c", "text": "闭上眼睛松手"}], "subject": "interest", "explanation": "轻轻捏住刹车，车子就会慢慢停下。"}, {"id": "low-interest-010", "band": "low", "answer": "a", "prompt": "玩橡皮泥，想做一个圆圆的球，要怎么做？", "choices": [{"id": "a", "text": "用两只手把它搓圆"}, {"id": "b", "text": "用力压扁"}, {"id": "c", "text": "撕成一小条一小条"}], "subject": "interest", "explanation": "把橡皮泥放手心里转着搓，就变成小球啦。"}, {"id": "low-interest-011", "band": "low", "answer": "a", "prompt": "小朋友很喜欢的“滑滑梯”，玩的时候应该怎么滑？", "choices": [{"id": "a", "text": "从上面坐着往下滑"}, {"id": "b", "text": "从下往上倒着爬"}, {"id": "c", "text": "站在最高处往下跳"}], "subject": "interest", "explanation": "坐好从上往下滑才安全又好玩。"}, {"id": "low-interest-012", "band": "low", "answer": "a", "prompt": "游泳的时候，下面哪样东西能帮我们浮起来？", "choices": [{"id": "a", "text": "游泳圈"}, {"id": "b", "text": "大石头"}, {"id": "c", "text": "铁锅"}], "subject": "interest", "explanation": "游泳圈里有空气，能把我们托在水面上。"}, {"id": "low-interest-013", "band": "low", "answer": "a", "prompt": "吹泡泡的时候，应该怎么吹泡泡才会变大？", "choices": [{"id": "a", "text": "又轻又慢地吹气"}, {"id": "b", "text": "一下子用力猛吹"}, {"id": "c", "text": "把泡泡水喝掉"}], "subject": "interest", "explanation": "轻轻慢慢吹，泡泡才会越来越大不会破。"}, {"id": "low-interest-014", "band": "low", "answer": "a", "prompt": "小朋友很喜欢的“捉迷藏”，当“鬼”的人要做什么？", "choices": [{"id": "a", "text": "去找躲起来的人"}, {"id": "b", "text": "自己躲起来"}, {"id": "c", "text": "回家睡觉"}], "subject": "interest", "explanation": "当鬼的人要数数，然后去把躲起来的小伙伴找出来。"}, {"id": "low-interest-015", "band": "low", "answer": "a", "prompt": "折纸的时候，想折一只小船，第一步通常要怎么做？", "choices": [{"id": "a", "text": "把纸对折一下"}, {"id": "b", "text": "把纸揉成一团"}, {"id": "c", "text": "把纸剪成碎片"}], "subject": "interest", "explanation": "先把纸对折压平，再一步步折就能折出小船。"}, {"id": "low-interest-016", "band": "low", "answer": "a", "prompt": "唱歌的时候，下面哪种声音听起来最舒服？", "choices": [{"id": "a", "text": "又轻又好听的声音"}, {"id": "b", "text": "使劲大喊大叫"}, {"id": "c", "text": "一直跑调乱唱"}], "subject": "interest", "explanation": "用好听的声音唱，大家都爱听。"}, {"id": "low-interest-017", "band": "low", "answer": "a", "prompt": "小朋友爱玩的“石头剪刀布”，剪刀会输给谁？", "choices": [{"id": "a", "text": "石头"}, {"id": "b", "text": "布"}, {"id": "c", "text": "另一把剪刀"}], "subject": "interest", "explanation": "石头能砸坏剪刀，所以剪刀怕石头。"}, {"id": "low-interest-018", "band": "low", "answer": "a", "prompt": "玩拼图的时候，怎样最容易拼好？", "choices": [{"id": "a", "text": "先找出四个角和边"}, {"id": "b", "text": "随便往上乱放"}, {"id": "c", "text": "把拼图藏起来"}], "subject": "interest", "explanation": "先拼好四边和角，中间就好对上啦。"}, {"id": "low-interest-019", "band": "low", "answer": "a", "prompt": "冬天最适合堆下面哪样东西？", "choices": [{"id": "a", "text": "用雪堆雪人"}, {"id": "b", "text": "用沙子堆雪人"}, {"id": "c", "text": "用水堆雪人"}], "subject": "interest", "explanation": "雪能捏成团，下雪天才能堆出胖胖的雪人。"}, {"id": "low-interest-020", "band": "low", "answer": "a", "prompt": "玩遥控小汽车，按前进键车子会怎么样？", "choices": [{"id": "a", "text": "往前跑"}, {"id": "b", "text": "飞上天"}, {"id": "c", "text": "不动还睡觉"}], "subject": "interest", "explanation": "按前进键，小车就会往前开。"}, {"id": "low-interest-021", "band": "low", "answer": "a", "prompt": "小朋友很爱看的“熊出没”里，光头强最想做什么？", "choices": [{"id": "a", "text": "砍树"}, {"id": "b", "text": "种花"}, {"id": "c", "text": "画画"}], "subject": "interest", "explanation": "光头强老想砍树，熊大熊二就来保护森林。"}, {"id": "low-interest-022", "band": "low", "answer": "a", "prompt": "拍皮球的时候，球碰到地面会怎么样？", "choices": [{"id": "a", "text": "弹起来"}, {"id": "b", "text": "陷进地里"}, {"id": "c", "text": "变成方形"}], "subject": "interest", "explanation": "皮球软软有弹性，拍到地上就会弹回来。"}, {"id": "low-funny-001", "band": "low", "answer": "b", "prompt": "什么东西越洗越脏？", "choices": [{"id": "a", "text": "小手"}, {"id": "b", "text": "水"}, {"id": "c", "text": "袜子"}], "subject": "funny", "explanation": "洗东西的水越用越脏啦！"}, {"id": "low-funny-002", "band": "low", "answer": "a", "prompt": "小白加小白等于什么？（猜一句话）", "choices": [{"id": "a", "text": "小白兔（小白兔=小白two）"}, {"id": "b", "text": "两只白猫"}, {"id": "c", "text": "一片白云"}], "subject": "funny", "explanation": "两个小白，就是“小白 two”，听起来像“小白兔”！"}, {"id": "low-funny-003", "band": "low", "answer": "b", "prompt": "什么动物最爱贴在墙上？", "choices": [{"id": "a", "text": "小狗"}, {"id": "b", "text": "壁虎"}, {"id": "c", "text": "小鱼"}], "subject": "funny", "explanation": "壁虎的“壁”就是墙壁，它最会爬墙啦！"}, {"id": "low-funny-004", "band": "low", "answer": "b", "prompt": "什么帽子永远戴不到头上？", "choices": [{"id": "a", "text": "草帽"}, {"id": "b", "text": "瓶盖（瓶子的帽子）"}, {"id": "c", "text": "棉帽"}], "subject": "funny", "explanation": "瓶盖是瓶子的“帽子”，可没法戴到头上哦！"}, {"id": "low-funny-005", "band": "low", "answer": "b", "prompt": "什么时候太阳会从西边出来？", "choices": [{"id": "a", "text": "下雨天"}, {"id": "b", "text": "做梦的时候"}, {"id": "c", "text": "过生日"}], "subject": "funny", "explanation": "只有在梦里，太阳才会从西边出来呀！"}, {"id": "low-funny-006", "band": "low", "answer": "b", "prompt": "一只小鸟站在树上，为什么不会掉下来？", "choices": [{"id": "a", "text": "它睡着了"}, {"id": "b", "text": "它会抓紧树枝"}, {"id": "c", "text": "它没有重量"}], "subject": "funny", "explanation": "小鸟用小爪子紧紧抓住树枝，就不会掉啦！"}, {"id": "low-funny-007", "band": "low", "answer": "a", "prompt": "什么东西有嘴巴，却不会说话？", "choices": [{"id": "a", "text": "茶杯（杯口叫“杯嘴”）"}, {"id": "b", "text": "小狗"}, {"id": "c", "text": "电视"}], "subject": "funny", "explanation": "杯子有“嘴”，可它一句话也不会说！"}, {"id": "low-funny-008", "band": "low", "answer": "b", "prompt": "什么车没有轮子？", "choices": [{"id": "a", "text": "小汽车"}, {"id": "b", "text": "风车"}, {"id": "c", "text": "自行车"}], "subject": "funny", "explanation": "风车靠风转圈圈，可没有轮子哦！"}, {"id": "low-funny-009", "band": "low", "answer": "b", "prompt": "小明往左走，影子往哪走？", "choices": [{"id": "a", "text": "往右走"}, {"id": "b", "text": "跟着一起走"}, {"id": "c", "text": "飞到天上"}], "subject": "funny", "explanation": "影子是个跟屁虫，你走哪它走哪！"}, {"id": "low-funny-010", "band": "low", "answer": "b", "prompt": "什么水果最爱生气？", "choices": [{"id": "a", "text": "芒果"}, {"id": "b", "text": "火龙果（带“火”）"}, {"id": "c", "text": "香蕉"}], "subject": "funny", "explanation": "火龙果名字里有个“火”，好像在发火气呢！"}, {"id": "low-funny-011", "band": "low", "answer": "a", "prompt": "冰化了以后会变成什么？", "choices": [{"id": "a", "text": "水"}, {"id": "b", "text": "糖"}, {"id": "c", "text": "云"}], "subject": "funny", "explanation": "冰块一化就变成水啦！"}, {"id": "low-funny-012", "band": "low", "answer": "b", "prompt": "什么东西越多越冷？", "choices": [{"id": "a", "text": "太阳"}, {"id": "b", "text": "雪"}, {"id": "c", "text": "火"}], "subject": "funny", "explanation": "雪下得越多，天气就越冷啦！"}, {"id": "low-funny-013", "band": "low", "answer": "b", "prompt": "小猫为什么喜欢抓老鼠？", "choices": [{"id": "a", "text": "想跟它玩游戏"}, {"id": "b", "text": "因为爱吃老鼠"}, {"id": "c", "text": "老鼠欠它钱"}], "subject": "funny", "explanation": "小猫最爱抓老鼠当点心吃啦！"}, {"id": "low-funny-014", "band": "low", "answer": "b", "prompt": "什么门永远关不上？", "choices": [{"id": "a", "text": "大铁门"}, {"id": "b", "text": "球门"}, {"id": "c", "text": "木头门"}], "subject": "funny", "explanation": "足球的球门是空的，关也关不上呀！"}, {"id": "low-funny-015", "band": "low", "answer": "a", "prompt": "什么东西天黑才出来，天亮就不见了？", "choices": [{"id": "a", "text": "月亮和星星"}, {"id": "b", "text": "太阳"}, {"id": "c", "text": "彩虹"}], "subject": "funny", "explanation": "月亮星星只在晚上出来，天一亮就躲起来啦！"}, {"id": "low-funny-016", "band": "low", "answer": "b", "prompt": "大象用什么洗澡？", "choices": [{"id": "a", "text": "毛巾"}, {"id": "b", "text": "长长的鼻子喷水"}, {"id": "c", "text": "小勺子"}], "subject": "funny", "explanation": "大象用长鼻子吸水，再喷到身上洗澡！"}, {"id": "low-funny-017", "band": "low", "answer": "b", "prompt": "什么东西你有，别人也有，但不能借给别人？", "choices": [{"id": "a", "text": "铅笔"}, {"id": "b", "text": "名字"}, {"id": "c", "text": "橡皮"}], "subject": "funny", "explanation": "每个人都有名字，可名字是借不走的哦！"}, {"id": "low-funny-018", "band": "low", "answer": "b", "prompt": "一个人掉进河里，为什么头发没湿？", "choices": [{"id": "a", "text": "他游得快"}, {"id": "b", "text": "他是光头"}, {"id": "c", "text": "河里没有水"}], "subject": "funny", "explanation": "光头没有头发，当然不会湿啦！"}, {"id": "low-funny-019", "band": "low", "answer": "c", "prompt": "什么东西人人都想要，可拿到手就没了？", "choices": [{"id": "a", "text": "糖果"}, {"id": "b", "text": "影子"}, {"id": "c", "text": "泡泡"}], "subject": "funny", "explanation": "泡泡一碰就破，想抓也抓不住！"}, {"id": "low-funny-020", "band": "low", "answer": "a", "prompt": "青蛙为什么会跳？", "choices": [{"id": "a", "text": "因为它腿很有力"}, {"id": "b", "text": "因为它怕痒"}, {"id": "c", "text": "因为它在跳舞"}], "subject": "funny", "explanation": "青蛙的后腿很有劲，一蹬就跳得老远！"}, {"id": "low-funny-021", "band": "low", "answer": "a", "prompt": "什么东西早上四条腿可以坐，你天天都坐它？", "choices": [{"id": "a", "text": "小椅子"}, {"id": "b", "text": "小狗"}, {"id": "c", "text": "皮球"}], "subject": "funny", "explanation": "小椅子有四条腿，每天都给你坐！"}, {"id": "low-funny-022", "band": "low", "answer": "c", "prompt": "什么笔不能写字？", "choices": [{"id": "a", "text": "铅笔"}, {"id": "b", "text": "油画笔"}, {"id": "c", "text": "鼻（鼻子，和“笔”同音）"}], "subject": "funny", "explanation": "“鼻”和“笔”读音很像，可鼻子怎么写字呀！"}, {"id": "high-math-001", "band": "high", "answer": "c", "prompt": "1/2 和 0.5，谁更大？", "choices": [{"id": "a", "text": "1/2 更大"}, {"id": "b", "text": "0.5 更大"}, {"id": "c", "text": "一样大"}], "subject": "math", "explanation": "1/2 写成小数就是 0.5，它俩其实是同一个数。"}, {"id": "high-math-002", "band": "high", "answer": "a", "prompt": "一个正方形边长 5 厘米，它的周长是多少？", "choices": [{"id": "a", "text": "20 厘米"}, {"id": "b", "text": "25 厘米"}, {"id": "c", "text": "10 厘米"}], "subject": "math", "explanation": "正方形四条边一样长，周长 = 5 × 4 = 20 厘米。"}, {"id": "high-math-003", "band": "high", "answer": "b", "prompt": "同样这个边长 5 厘米的正方形，面积又是多少？", "choices": [{"id": "a", "text": "20 平方厘米"}, {"id": "b", "text": "25 平方厘米"}, {"id": "c", "text": "10 平方厘米"}], "subject": "math", "explanation": "面积 = 边长 × 边长 = 5 × 5 = 25 平方厘米。别和周长搞混啦。"}, {"id": "high-math-004", "band": "high", "answer": "a", "prompt": "0.25 化成分数，最简是几分之几？", "choices": [{"id": "a", "text": "1/4"}, {"id": "b", "text": "1/2"}, {"id": "c", "text": "2/5"}], "subject": "math", "explanation": "0.25 = 25/100，约分后就是 1/4。"}, {"id": "high-math-005", "band": "high", "answer": "b", "prompt": "24 是 6 的几倍？", "choices": [{"id": "a", "text": "3 倍"}, {"id": "b", "text": "4 倍"}, {"id": "c", "text": "5 倍"}], "subject": "math", "explanation": "24 ÷ 6 = 4，所以是 4 倍。"}, {"id": "high-math-006", "band": "high", "answer": "a", "prompt": "一本书 80 页，你看了 3/4，还剩多少页没看？", "choices": [{"id": "a", "text": "20 页"}, {"id": "b", "text": "60 页"}, {"id": "c", "text": "40 页"}], "subject": "math", "explanation": "看了 3/4 就还剩 1/4，80 × 1/4 = 20 页。"}, {"id": "high-math-007", "band": "high", "answer": "c", "prompt": "一个长方形长 8 米、宽 3 米，面积是多少？", "choices": [{"id": "a", "text": "11 平方米"}, {"id": "b", "text": "22 平方米"}, {"id": "c", "text": "24 平方米"}], "subject": "math", "explanation": "长方形面积 = 长 × 宽 = 8 × 3 = 24 平方米。"}, {"id": "high-math-008", "band": "high", "answer": "a", "prompt": "这个长 8 米、宽 3 米的长方形，周长是多少？", "choices": [{"id": "a", "text": "22 米"}, {"id": "b", "text": "24 米"}, {"id": "c", "text": "11 米"}], "subject": "math", "explanation": "周长 = (长 + 宽) × 2 = (8 + 3) × 2 = 22 米。"}, {"id": "high-math-009", "band": "high", "answer": "b", "prompt": "1/3 + 1/3 等于多少？", "choices": [{"id": "a", "text": "1/6"}, {"id": "b", "text": "2/3"}, {"id": "c", "text": "2/6"}], "subject": "math", "explanation": "分母相同，分子相加：1 + 1 = 2，结果是 2/3。"}, {"id": "high-math-010", "band": "high", "answer": "a", "prompt": "3.6 + 1.5 等于多少？", "choices": [{"id": "a", "text": "5.1"}, {"id": "b", "text": "4.11"}, {"id": "c", "text": "5.0"}], "subject": "math", "explanation": "小数对齐相加：3.6 + 1.5 = 5.1。"}, {"id": "high-math-011", "band": "high", "answer": "b", "prompt": "一支笔 2.5 元，买 4 支要多少钱？", "choices": [{"id": "a", "text": "8 元"}, {"id": "b", "text": "10 元"}, {"id": "c", "text": "9 元"}], "subject": "math", "explanation": "2.5 × 4 = 10 元。"}, {"id": "high-math-012", "band": "high", "answer": "b", "prompt": "下面哪个数是 7 的倍数？", "choices": [{"id": "a", "text": "27"}, {"id": "b", "text": "42"}, {"id": "c", "text": "50"}], "subject": "math", "explanation": "42 = 7 × 6，所以是 7 的倍数。"}, {"id": "high-math-013", "band": "high", "answer": "a", "prompt": "2/5 化成小数是多少？", "choices": [{"id": "a", "text": "0.4"}, {"id": "b", "text": "0.25"}, {"id": "c", "text": "0.5"}], "subject": "math", "explanation": "2 ÷ 5 = 0.4。"}, {"id": "high-math-014", "band": "high", "answer": "b", "prompt": "小明跑步 5 分钟跑了 1000 米，他平均每分钟跑多少米？", "choices": [{"id": "a", "text": "100 米"}, {"id": "b", "text": "200 米"}, {"id": "c", "text": "500 米"}], "subject": "math", "explanation": "1000 ÷ 5 = 200 米，每分钟跑 200 米。"}, {"id": "high-math-015", "band": "high", "answer": "a", "prompt": "一个数的 3 倍是 27，这个数是多少？", "choices": [{"id": "a", "text": "9"}, {"id": "b", "text": "24"}, {"id": "c", "text": "81"}], "subject": "math", "explanation": "倒过来算：27 ÷ 3 = 9。"}, {"id": "high-math-016", "band": "high", "answer": "a", "prompt": "比较 3/4 和 2/3，谁更大？", "choices": [{"id": "a", "text": "3/4 更大"}, {"id": "b", "text": "2/3 更大"}, {"id": "c", "text": "一样大"}], "subject": "math", "explanation": "通分：3/4 = 9/12，2/3 = 8/12，所以 3/4 更大。"}, {"id": "high-math-017", "band": "high", "answer": "b", "prompt": "一件衣服原价 100 元，打八折后卖多少钱？", "choices": [{"id": "a", "text": "20 元"}, {"id": "b", "text": "80 元"}, {"id": "c", "text": "88 元"}], "subject": "math", "explanation": "八折就是按原价的 80% 卖，100 × 0.8 = 80 元。"}, {"id": "high-math-018", "band": "high", "answer": "a", "prompt": "1 减去 0.3 等于多少？", "choices": [{"id": "a", "text": "0.7"}, {"id": "b", "text": "0.97"}, {"id": "c", "text": "0.3"}], "subject": "math", "explanation": "把 1 看成 1.0，1.0 - 0.3 = 0.7。"}, {"id": "high-math-019", "band": "high", "answer": "a", "prompt": "正方形花坛面积是 36 平方米，它的边长是多少？", "choices": [{"id": "a", "text": "6 米"}, {"id": "b", "text": "9 米"}, {"id": "c", "text": "18 米"}], "subject": "math", "explanation": "哪个数乘自己等于 36？6 × 6 = 36，所以边长 6 米。"}, {"id": "high-math-020", "band": "high", "answer": "b", "prompt": "一堆糖平分给 4 个人，每人 6 颗，原来一共有多少颗？", "choices": [{"id": "a", "text": "10 颗"}, {"id": "b", "text": "24 颗"}, {"id": "c", "text": "2 颗"}], "subject": "math", "explanation": "倒着想：每人 6 颗 × 4 人 = 24 颗。"}, {"id": "high-math-021", "band": "high", "answer": "a", "prompt": "把 3/6 约成最简分数是多少？", "choices": [{"id": "a", "text": "1/2"}, {"id": "b", "text": "1/3"}, {"id": "c", "text": "3/6"}], "subject": "math", "explanation": "分子分母同时除以 3，得到 1/2。"}, {"id": "high-math-022", "band": "high", "answer": "b", "prompt": "妈妈 36 岁，是闫一依年龄的 3 倍，闫一依几岁？", "choices": [{"id": "a", "text": "9 岁"}, {"id": "b", "text": "12 岁"}, {"id": "c", "text": "33 岁"}], "subject": "math", "explanation": "36 ÷ 3 = 12，闫一依 12 岁。"}, {"id": "high-chinese-001", "band": "high", "answer": "b", "prompt": "成语“画蛇添足”是说一个人做了什么？", "choices": [{"id": "a", "text": "把蛇画得很漂亮"}, {"id": "b", "text": "多此一举，反倒坏了事"}, {"id": "c", "text": "画画速度特别快"}], "subject": "chinese", "explanation": "蛇本来没脚，硬给它添上脚——多余的动作反而把事办砸了。"}, {"id": "high-chinese-002", "band": "high", "answer": "b", "prompt": "“狐假虎威”里的“假”是什么意思？", "choices": [{"id": "a", "text": "假的、不是真的"}, {"id": "b", "text": "借、利用"}, {"id": "c", "text": "放假"}], "subject": "chinese", "explanation": "“假”在这里是“借”的意思，狐狸借着老虎的威风吓唬别的动物。"}, {"id": "high-chinese-003", "band": "high", "answer": "b", "prompt": "下面哪句话有语病（说得不通顺）？", "choices": [{"id": "a", "text": "我昨天看了一本很有趣的书。"}, {"id": "b", "text": "通过这次活动，使我懂得了团结。"}, {"id": "c", "text": "春天到了，花儿都开了。"}], "subject": "chinese", "explanation": "“通过……使……”一起用，句子就没主语了，去掉一个就对了。"}, {"id": "high-chinese-004", "band": "high", "answer": "a", "prompt": "“春眠不觉晓”的下一句是什么？", "choices": [{"id": "a", "text": "处处闻啼鸟"}, {"id": "b", "text": "夜来风雨声"}, {"id": "c", "text": "花落知多少"}], "subject": "chinese", "explanation": "出自孟浩然《春晓》：春眠不觉晓，处处闻啼鸟。"}, {"id": "high-chinese-005", "band": "high", "answer": "b", "prompt": "“重”是个多音字。下面哪个词里它读 chóng？", "choices": [{"id": "a", "text": "重要"}, {"id": "b", "text": "重新"}, {"id": "c", "text": "重量"}], "subject": "chinese", "explanation": "“重新”的“重”读 chóng，表示“再一次”；“重要、重量”读 zhòng。"}, {"id": "high-chinese-006", "band": "high", "answer": "b", "prompt": "“胸有成竹”形容一个人怎么样？", "choices": [{"id": "a", "text": "胸口长了竹子"}, {"id": "b", "text": "做事前心里早有把握"}, {"id": "c", "text": "特别喜欢吃竹笋"}], "subject": "chinese", "explanation": "画竹子前心里已经有竹子的样子了，比喻做事前心中早有谋划、很有把握。"}, {"id": "high-chinese-007", "band": "high", "answer": "b", "prompt": "“锲而不舍”是什么意思？", "choices": [{"id": "a", "text": "一刻也舍不得休息"}, {"id": "b", "text": "一直坚持，不放弃"}, {"id": "c", "text": "舍不得花钱"}], "subject": "chinese", "explanation": "“锲”是刻，一直刻下去不停手，比喻有恒心、坚持到底。"}, {"id": "high-chinese-008", "band": "high", "answer": "b", "prompt": "“举头望明月”的下一句是什么？", "choices": [{"id": "a", "text": "疑是地上霜"}, {"id": "b", "text": "低头思故乡"}, {"id": "c", "text": "床前明月光"}], "subject": "chinese", "explanation": "李白《静夜思》：举头望明月，低头思故乡。"}, {"id": "high-chinese-009", "band": "high", "answer": "b", "prompt": "“行”是多音字。“银行”的“行”读什么？", "choices": [{"id": "a", "text": "xíng"}, {"id": "b", "text": "háng"}], "subject": "chinese", "explanation": "“银行、行业”的“行”读 háng；“行走、不行”读 xíng。"}, {"id": "high-chinese-010", "band": "high", "answer": "c", "prompt": "下面哪句话没有语病？", "choices": [{"id": "a", "text": "他大约十二岁左右。"}, {"id": "b", "text": "我们要避免今后不再犯这种错误。"}, {"id": "c", "text": "同学们正在认真地做作业。"}], "subject": "chinese", "explanation": "A的“大约”和“左右”重复；B“避免……不再”是双重否定说反了；C没毛病。"}, {"id": "high-chinese-011", "band": "high", "answer": "b", "prompt": "成语“守株待兔”告诉我们什么道理？", "choices": [{"id": "a", "text": "守在树边一定能等到兔子"}, {"id": "b", "text": "不能靠运气、靠侥幸办事"}, {"id": "c", "text": "兔子跑得很快"}], "subject": "chinese", "explanation": "农夫指望兔子再撞树而死，比喻死等好运、不肯努力，是行不通的。"}, {"id": "high-chinese-012", "band": "high", "answer": "a", "prompt": "“破釜沉舟”里的“釜”指的是什么？", "choices": [{"id": "a", "text": "锅"}, {"id": "b", "text": "斧头"}, {"id": "c", "text": "船"}], "subject": "chinese", "explanation": "“釜”是古代的锅。打破锅、凿沉船，断了退路，比喻下定决心不留后路。"}, {"id": "high-chinese-013", "band": "high", "answer": "a", "prompt": "“千山鸟飞绝”的下一句是什么？", "choices": [{"id": "a", "text": "万径人踪灭"}, {"id": "b", "text": "独钓寒江雪"}, {"id": "c", "text": "孤舟蓑笠翁"}], "subject": "chinese", "explanation": "柳宗元《江雪》：千山鸟飞绝，万径人踪灭。"}, {"id": "high-chinese-014", "band": "high", "answer": "a", "prompt": "“恍然大悟”形容的是哪种感觉？", "choices": [{"id": "a", "text": "突然一下子明白了"}, {"id": "b", "text": "迷迷糊糊想睡觉"}, {"id": "c", "text": "气得说不出话"}], "subject": "chinese", "explanation": "本来不懂，一下子全想通了，就是“恍然大悟”。"}, {"id": "high-chinese-015", "band": "high", "answer": "b", "prompt": "“假”是多音字。“放假”的“假”读什么？", "choices": [{"id": "a", "text": "jiǎ"}, {"id": "b", "text": "jià"}], "subject": "chinese", "explanation": "“放假、假期”读 jià；“真假、假装”读 jiǎ。"}, {"id": "high-chinese-016", "band": "high", "answer": "a", "prompt": "词语“果然”最适合填进哪个句子？", "choices": [{"id": "a", "text": "天气预报说会下雨，傍晚（  ）下起了大雨。"}, {"id": "b", "text": "他（  ）会来吗？我也不确定。"}, {"id": "c", "text": "请你（  ）把门关上。"}], "subject": "chinese", "explanation": "“果然”表示事情和预料的一样，正好配“预报说下雨、傍晚真的下了”。"}, {"id": "high-chinese-017", "band": "high", "answer": "a", "prompt": "下面哪一组都是近义词（意思相近）？", "choices": [{"id": "a", "text": "高兴 — 快乐"}, {"id": "b", "text": "寒冷 — 炎热"}, {"id": "c", "text": "黑夜 — 白天"}], "subject": "chinese", "explanation": "“高兴”和“快乐”意思相近是近义词；B、C是意思相反的反义词。"}, {"id": "high-chinese-018", "band": "high", "answer": "b", "prompt": "“滥竽充数”比喻的是什么样的人？", "choices": [{"id": "a", "text": "吹竽吹得特别好的人"}, {"id": "b", "text": "没真本事却混在里面凑数的人"}, {"id": "c", "text": "数数特别快的人"}], "subject": "chinese", "explanation": "南郭先生不会吹竽，却混在乐队里假装会，比喻没本事的人冒充充数。"}, {"id": "high-chinese-019", "band": "high", "answer": "a", "prompt": "“两个黄鹂鸣翠柳”的下一句是什么？", "choices": [{"id": "a", "text": "一行白鹭上青天"}, {"id": "b", "text": "窗含西岭千秋雪"}, {"id": "c", "text": "门泊东吴万里船"}], "subject": "chinese", "explanation": "杜甫《绝句》：两个黄鹂鸣翠柳，一行白鹭上青天。"}, {"id": "high-chinese-020", "band": "high", "answer": "b", "prompt": "下面哪句话用词不当（用错了词）？", "choices": [{"id": "a", "text": "他认真地听老师讲课。"}, {"id": "b", "text": "操场上突然爆发出一阵热烈的味道。"}, {"id": "c", "text": "弟弟开心地笑了起来。"}], "subject": "chinese", "explanation": "“爆发出……味道”搭配不当，应该是“爆发出热烈的掌声/欢呼”。"}, {"id": "high-chinese-021", "band": "high", "answer": "b", "prompt": "“调”是多音字。“调查”的“调”读什么？", "choices": [{"id": "a", "text": "tiáo"}, {"id": "b", "text": "diào"}], "subject": "chinese", "explanation": "“调查、调动”读 diào；“调皮、调味”读 tiáo。"}, {"id": "high-chinese-022", "band": "high", "answer": "b", "prompt": "成语“井底之蛙”用来形容什么样的人？", "choices": [{"id": "a", "text": "住在井里的青蛙"}, {"id": "b", "text": "见识少、眼界窄的人"}, {"id": "c", "text": "跳得特别高的人"}], "subject": "chinese", "explanation": "井底的青蛙只看得到井口那一小块天，比喻见识短浅、眼界狭小的人。"}, {"id": "high-english-001", "band": "high", "answer": "b", "prompt": "“delicious”是什么意思？", "choices": [{"id": "a", "text": "危险的"}, {"id": "b", "text": "好吃的"}, {"id": "c", "text": "安静的"}], "subject": "english", "explanation": "delicious = 美味的、好吃的，夸饭好吃就用它。"}, {"id": "high-english-002", "band": "high", "answer": "a", "prompt": "一只猫是 cat，那么三只猫怎么写？", "choices": [{"id": "a", "text": "cats"}, {"id": "b", "text": "cat"}, {"id": "c", "text": "cates"}], "subject": "english", "explanation": "大多数名词变复数直接加 s，three cats。"}, {"id": "high-english-003", "band": "high", "answer": "a", "prompt": "别人对你说 “Thank you!”，最自然的回答是？", "choices": [{"id": "a", "text": "You're welcome."}, {"id": "b", "text": "Goodbye."}, {"id": "c", "text": "I am fine."}], "subject": "english", "explanation": "“不客气”就是 You're welcome。"}, {"id": "high-english-004", "band": "high", "answer": "b", "prompt": "下面哪个是 “happy” 的反义词？", "choices": [{"id": "a", "text": "tall"}, {"id": "b", "text": "sad"}, {"id": "c", "text": "fast"}], "subject": "english", "explanation": "happy 开心 ↔ sad 难过。"}, {"id": "high-english-005", "band": "high", "answer": "b", "prompt": "“She ___ to school every day.” 横线上填哪个？", "choices": [{"id": "a", "text": "go"}, {"id": "b", "text": "goes"}, {"id": "c", "text": "going"}], "subject": "english", "explanation": "主语是 she（第三人称单数），一般现在时动词要加 es，goes。"}, {"id": "high-english-006", "band": "high", "answer": "a", "prompt": "“Monday” 是星期几？", "choices": [{"id": "a", "text": "星期一"}, {"id": "b", "text": "星期天"}, {"id": "c", "text": "星期五"}], "subject": "english", "explanation": "Monday = 星期一，一周的开头。"}, {"id": "high-english-007", "band": "high", "answer": "b", "prompt": "下面哪个单词的复数形式是不规则的？", "choices": [{"id": "a", "text": "dog（dogs）"}, {"id": "b", "text": "child（children）"}, {"id": "c", "text": "book（books）"}], "subject": "english", "explanation": "child 的复数是 children，不是加 s，属于不规则变化。"}, {"id": "high-english-008", "band": "high", "answer": "b", "prompt": "问别人“现在几点了”，应该说？", "choices": [{"id": "a", "text": "How old are you?"}, {"id": "b", "text": "What's the time?"}, {"id": "c", "text": "Where are you?"}], "subject": "english", "explanation": "What's the time?（或 What time is it?）= 现在几点了。"}, {"id": "high-english-009", "band": "high", "answer": "b", "prompt": "“This is ___ apple.” 横线上填哪个最对？", "choices": [{"id": "a", "text": "a"}, {"id": "b", "text": "an"}, {"id": "c", "text": "the"}], "subject": "english", "explanation": "apple 以元音音开头，前面用 an，an apple。"}, {"id": "high-english-010", "band": "high", "answer": "a", "prompt": "“weather” 这个词说的是什么？", "choices": [{"id": "a", "text": "天气"}, {"id": "b", "text": "星期"}, {"id": "c", "text": "作业"}], "subject": "english", "explanation": "weather = 天气，注意别和 whether（是否）搞混。"}, {"id": "high-english-011", "band": "high", "answer": "b", "prompt": "“I ___ a student.” 横线上填哪个 be 动词？", "choices": [{"id": "a", "text": "is"}, {"id": "b", "text": "am"}, {"id": "c", "text": "are"}], "subject": "english", "explanation": "I 后面的 be 动词永远用 am。"}, {"id": "high-english-012", "band": "high", "answer": "a", "prompt": "比较级：“tall” 变成“更高”怎么写？", "choices": [{"id": "a", "text": "taller"}, {"id": "b", "text": "tallest"}, {"id": "c", "text": "more tall"}], "subject": "english", "explanation": "短词比较级直接加 er，taller = 更高。"}, {"id": "high-english-013", "band": "high", "answer": "b", "prompt": "“favorite” 是什么意思？", "choices": [{"id": "a", "text": "害怕的"}, {"id": "b", "text": "最喜欢的"}, {"id": "c", "text": "免费的"}], "subject": "english", "explanation": "favorite = 最爱的、最喜欢的，my favorite color 我最喜欢的颜色。"}, {"id": "high-english-014", "band": "high", "answer": "b", "prompt": "别人问 “How are you?”，下面哪个回答最合适？", "choices": [{"id": "a", "text": "I am eleven."}, {"id": "b", "text": "I'm fine, thank you."}, {"id": "c", "text": "It is Monday."}], "subject": "english", "explanation": "问“你好吗”，回答 I'm fine, thank you. 最稳。"}, {"id": "high-english-015", "band": "high", "answer": "b", "prompt": "“There ___ two books on the desk.” 横线上填哪个？", "choices": [{"id": "a", "text": "is"}, {"id": "b", "text": "are"}, {"id": "c", "text": "am"}], "subject": "english", "explanation": "two books 是复数，所以用 there are。"}, {"id": "high-english-016", "band": "high", "answer": "a", "prompt": "下面哪个单词是“蔬菜”的意思？", "choices": [{"id": "a", "text": "vegetable"}, {"id": "b", "text": "animal"}, {"id": "c", "text": "building"}], "subject": "english", "explanation": "vegetable = 蔬菜；animal 动物，building 建筑物。"}, {"id": "high-english-017", "band": "high", "answer": "b", "prompt": "过去式：“go” 的过去式是哪个？", "choices": [{"id": "a", "text": "goed"}, {"id": "b", "text": "went"}, {"id": "c", "text": "gone"}], "subject": "english", "explanation": "go 是不规则动词，过去式是 went。"}, {"id": "high-english-018", "band": "high", "answer": "a", "prompt": "想表达“我喜欢打篮球”，下面哪句对？", "choices": [{"id": "a", "text": "I like playing basketball."}, {"id": "b", "text": "I like play basketball."}, {"id": "c", "text": "I likes basketball play."}], "subject": "english", "explanation": "like 后面接动词时用 doing 形式：like playing basketball。"}, {"id": "high-english-019", "band": "high", "answer": "b", "prompt": "“This is my book. ___ book is over there.” 指别人的书，填哪个？", "choices": [{"id": "a", "text": "My"}, {"id": "b", "text": "His"}, {"id": "c", "text": "Me"}], "subject": "english", "explanation": "His = 他的，His book 他的书；my 是我的，me 是宾格。"}, {"id": "high-english-020", "band": "high", "answer": "b", "prompt": "“difficult” 是什么意思？", "choices": [{"id": "a", "text": "简单的"}, {"id": "b", "text": "困难的"}, {"id": "c", "text": "安静的"}], "subject": "english", "explanation": "difficult = 困难的、难的，反义词是 easy。"}, {"id": "high-english-021", "band": "high", "answer": "a", "prompt": "想约朋友“我们一起去吧”，哪句最自然？", "choices": [{"id": "a", "text": "Let's go together!"}, {"id": "b", "text": "Go you me!"}, {"id": "c", "text": "We go is together."}], "subject": "english", "explanation": "Let's go together! = 我们一起走吧，Let's = let us。"}, {"id": "high-english-022", "band": "high", "answer": "b", "prompt": "“Do you have ___ pens?” 问“有没有一些钢笔”，填哪个？", "choices": [{"id": "a", "text": "some"}, {"id": "b", "text": "any"}, {"id": "c", "text": "a"}], "subject": "english", "explanation": "疑问句、否定句里一般用 any；some 多用于肯定句。"}, {"id": "high-science-001", "band": "high", "answer": "b", "prompt": "天上为什么会打雷？", "choices": [{"id": "a", "text": "云里有人在敲鼓"}, {"id": "b", "text": "云里的电放出来，把空气一下子撑开"}, {"id": "c", "text": "太阳掉到云里了"}], "subject": "science", "explanation": "闪电放电瞬间把周围空气加热膨胀，发出的爆响就是雷声。"}, {"id": "high-science-002", "band": "high", "answer": "a", "prompt": "为什么先看到闪电、过一会儿才听到雷声？", "choices": [{"id": "a", "text": "光比声音跑得快得多"}, {"id": "b", "text": "雷声要先睡个觉"}, {"id": "c", "text": "声音是从地下传上来的"}], "subject": "science", "explanation": "光速约每秒30万公里，声速才约340米/秒，所以光先到。"}, {"id": "high-science-003", "band": "high", "answer": "a", "prompt": "彩虹一般是在什么情况下出现的？", "choices": [{"id": "a", "text": "空气里有小水珠，太阳把光分开了"}, {"id": "b", "text": "有人在天上涂颜料"}, {"id": "c", "text": "只有晚上才会有"}], "subject": "science", "explanation": "阳光被空气中的小水滴折射、反射，分解成七种颜色就成了彩虹。"}, {"id": "high-science-004", "band": "high", "answer": "b", "prompt": "水在标准情况下大约多少摄氏度会沸腾？", "choices": [{"id": "a", "text": "50度"}, {"id": "b", "text": "100度"}, {"id": "c", "text": "200度"}], "subject": "science", "explanation": "在海平面标准气压下，水大约100摄氏度沸腾。"}, {"id": "high-science-005", "band": "high", "answer": "b", "prompt": "冬天玻璃内侧出现的小水珠，是怎么来的？", "choices": [{"id": "a", "text": "从玻璃缝里渗进来的"}, {"id": "b", "text": "屋里热空气碰到冷玻璃，水汽变成了水"}, {"id": "c", "text": "玻璃自己出汗了"}], "subject": "science", "explanation": "这叫凝结：暖湿空气遇冷，水蒸气变回液态水珠。"}, {"id": "high-science-006", "band": "high", "answer": "c", "prompt": "同样重的铁块和棉花，哪个更重？", "choices": [{"id": "a", "text": "铁块更重"}, {"id": "b", "text": "棉花更重"}, {"id": "c", "text": "一样重"}], "subject": "science", "explanation": "题目说\"同样重\"，那当然一样重，棉花只是占的地方更大。"}, {"id": "high-science-007", "band": "high", "answer": "a", "prompt": "人体里负责把氧气送到全身的，主要是什么？", "choices": [{"id": "a", "text": "红细胞（血液里的红色细胞）"}, {"id": "b", "text": "骨头"}, {"id": "c", "text": "指甲"}], "subject": "science", "explanation": "红细胞里的血红蛋白能抓住氧气，随血液送到身体各处。"}, {"id": "high-science-008", "band": "high", "answer": "b", "prompt": "我们呼吸时吸进去的、最有用的气体是哪种？", "choices": [{"id": "a", "text": "二氧化碳"}, {"id": "b", "text": "氧气"}, {"id": "c", "text": "氢气"}], "subject": "science", "explanation": "身体靠氧气把食物里的能量\"烧\"出来，再把二氧化碳呼出去。"}, {"id": "high-science-009", "band": "high", "answer": "b", "prompt": "一天有白天和黑夜，主要是因为什么？", "choices": [{"id": "a", "text": "太阳自己开关灯"}, {"id": "b", "text": "地球在自转（自己转圈）"}, {"id": "c", "text": "月亮挡住了太阳"}], "subject": "science", "explanation": "地球大约24小时自转一圈，朝着太阳的那面是白天，背面是黑夜。"}, {"id": "high-science-010", "band": "high", "answer": "a", "prompt": "一年有四季，主要跟什么有关？", "choices": [{"id": "a", "text": "地球离太阳忽远忽近，而且地轴是斜的"}, {"id": "b", "text": "太阳每年换一次灯泡"}, {"id": "c", "text": "云的颜色会变"}], "subject": "science", "explanation": "地轴倾斜，地球绕太阳公转时各地受到的阳光角度变化，就有了四季。"}, {"id": "high-science-011", "band": "high", "answer": "b", "prompt": "月亮自己会发光吗？", "choices": [{"id": "a", "text": "会，它是个大灯泡"}, {"id": "b", "text": "不会，它是反射太阳的光"}, {"id": "c", "text": "只有满月时会发光"}], "subject": "science", "explanation": "月亮不发光，我们看到的月光其实是它反射的太阳光。"}, {"id": "high-science-012", "band": "high", "answer": "b", "prompt": "把盐放进水里搅一搅就看不见了，这叫什么？", "choices": [{"id": "a", "text": "盐消失了"}, {"id": "b", "text": "盐溶解了，变成很小的粒子混在水里"}, {"id": "c", "text": "盐飞走了"}], "subject": "science", "explanation": "盐没有消失，只是溶解后分散得很均匀，把水蒸干还能找回盐。"}, {"id": "high-science-013", "band": "high", "answer": "a", "prompt": "铁放在潮湿的地方久了会生锈，这其实是什么过程？", "choices": [{"id": "a", "text": "铁和空气里的氧气、水发生了化学变化"}, {"id": "b", "text": "铁被晒黑了"}, {"id": "c", "text": "铁长出了苔藓"}], "subject": "science", "explanation": "生锈是铁慢慢和氧气、水反应生成铁锈，是一种化学变化。"}, {"id": "high-science-014", "band": "high", "answer": "b", "prompt": "声音能在下面哪种环境里传播？", "choices": [{"id": "a", "text": "太空真空里"}, {"id": "b", "text": "空气、水和固体里"}, {"id": "c", "text": "哪儿都传不了"}], "subject": "science", "explanation": "声音要靠物质振动传播，真空里没有介质，所以太空很安静。"}, {"id": "high-science-015", "band": "high", "answer": "a", "prompt": "植物白天靠阳光自己造\"饭吃\"，这个过程叫什么？", "choices": [{"id": "a", "text": "光合作用"}, {"id": "b", "text": "消化作用"}, {"id": "c", "text": "发电作用"}], "subject": "science", "explanation": "光合作用：植物用阳光、水和二氧化碳造出养分，同时放出氧气。"}, {"id": "high-science-016", "band": "high", "answer": "b", "prompt": "海里的水那么多，为什么不会越涨越多漫出来？", "choices": [{"id": "a", "text": "有人偷偷抽走了"}, {"id": "b", "text": "海水蒸发变成云，又下雨回到陆地和海里，循环着"}, {"id": "c", "text": "鱼把水喝掉了"}], "subject": "science", "explanation": "这就是水循环：蒸发、成云、降雨、汇流，水一直在地球上转圈。"}, {"id": "high-science-017", "band": "high", "answer": "b", "prompt": "磁铁最容易吸住下面哪个东西？", "choices": [{"id": "a", "text": "塑料尺"}, {"id": "b", "text": "回形针（铁的）"}, {"id": "c", "text": "玻璃杯"}], "subject": "science", "explanation": "磁铁能吸引铁、镍等金属，塑料和玻璃都不会被吸。"}, {"id": "high-science-018", "band": "high", "answer": "b", "prompt": "人的心脏一直在干什么活儿？", "choices": [{"id": "a", "text": "帮我们思考问题"}, {"id": "b", "text": "像泵一样把血液送到全身"}, {"id": "c", "text": "负责消化食物"}], "subject": "science", "explanation": "心脏是个\"泵\"，不停收缩把血液压送到全身再收回来。"}, {"id": "high-science-019", "band": "high", "answer": "b", "prompt": "为什么松开手，苹果会往下掉而不是往上飞？", "choices": [{"id": "a", "text": "苹果怕高"}, {"id": "b", "text": "因为地球有引力，把东西往下拉"}, {"id": "c", "text": "因为空气在往下吹"}], "subject": "science", "explanation": "地球的重力（引力）把物体往地心方向拉，所以东西会往下落。"}, {"id": "high-science-020", "band": "high", "answer": "b", "prompt": "把同一根筷子斜着插进水杯，看起来像断了，这是为什么？", "choices": [{"id": "a", "text": "筷子真的断了"}, {"id": "b", "text": "光从水里出来时拐了个弯（折射）"}, {"id": "c", "text": "水把筷子咬断了"}], "subject": "science", "explanation": "光从水进入空气时会折射改变方向，看起来筷子就像错位了。"}, {"id": "high-science-021", "band": "high", "answer": "c", "prompt": "在我们太阳系里，离太阳最近的行星是哪个？", "choices": [{"id": "a", "text": "地球"}, {"id": "b", "text": "木星"}, {"id": "c", "text": "水星"}], "subject": "science", "explanation": "从太阳往外数，第一颗行星是水星，离太阳最近。"}, {"id": "high-science-022", "band": "high", "answer": "b", "prompt": "夏天打开冰箱门，门口冒\"白气\"，这白气其实是什么？", "choices": [{"id": "a", "text": "是冰箱在放电"}, {"id": "b", "text": "空气里的水汽遇冷凝成的小水珠"}, {"id": "c", "text": "是烟"}], "subject": "science", "explanation": "冰箱里冒出的冷气让周围水蒸气凝结成小水珠，看起来就像白雾。"}, {"id": "high-sports-001", "band": "high", "answer": "b", "prompt": "篮球比赛里，球员站在三分线外投进一球，能得几分？", "choices": [{"id": "a", "text": "2分"}, {"id": "b", "text": "3分"}, {"id": "c", "text": "1分"}], "subject": "sports", "explanation": "三分线外投中得3分，线内投中是2分，罚球1分。"}, {"id": "high-sports-002", "band": "high", "answer": "a", "prompt": "足球比赛中，球被踢出底线、最后碰到的是防守方球员，应该判什么？", "choices": [{"id": "a", "text": "角球"}, {"id": "b", "text": "球门球"}, {"id": "c", "text": "点球"}], "subject": "sports", "explanation": "防守方最后碰球出底线，判进攻方角球；进攻方碰出去才是球门球。"}, {"id": "high-sports-003", "band": "high", "answer": "b", "prompt": "排球比赛里，每队最多可以连续触球几次再把球打过网？", "choices": [{"id": "a", "text": "2次"}, {"id": "b", "text": "3次"}, {"id": "c", "text": "4次"}], "subject": "sports", "explanation": "一般是“一传、二传、扣球”三次内必须过网，超过算违例（拦网那次不计入）。"}, {"id": "high-sports-004", "band": "high", "answer": "b", "prompt": "一个标准田径跑道，最内圈跑一圈是多少米？", "choices": [{"id": "a", "text": "200米"}, {"id": "b", "text": "400米"}, {"id": "c", "text": "500米"}], "subject": "sports", "explanation": "标准操场内圈一圈400米，所以跑1000米要跑两圈半。"}, {"id": "high-sports-005", "band": "high", "answer": "a", "prompt": "田径短跑比赛起跑时，发令枪响之前就抢跑，叫什么？", "choices": [{"id": "a", "text": "犯规（抢跑）"}, {"id": "b", "text": "加速"}, {"id": "c", "text": "热身"}], "subject": "sports", "explanation": "枪响前起动叫抢跑，属于犯规，正式比赛抢跑一次就可能被取消资格。"}, {"id": "high-sports-006", "band": "high", "answer": "a", "prompt": "体育课跑步前先慢跑、拉伸，最主要是为了什么？", "choices": [{"id": "a", "text": "让身体热起来、减少受伤"}, {"id": "b", "text": "浪费时间"}, {"id": "c", "text": "让人变高"}], "subject": "sports", "explanation": "热身能让肌肉和关节活动开，降低拉伤、扭伤的风险。"}, {"id": "high-sports-007", "band": "high", "answer": "a", "prompt": "乒乓球单局比赛，一般要先到多少分、并且领先2分才算赢？", "choices": [{"id": "a", "text": "11分"}, {"id": "b", "text": "15分"}, {"id": "c", "text": "21分"}], "subject": "sports", "explanation": "现在用11分制，但10平之后要一直打到领先对手2分为止。"}, {"id": "high-sports-008", "band": "high", "answer": "a", "prompt": "羽毛球比赛中，球落在界线“压线”上，算界内还是界外？", "choices": [{"id": "a", "text": "界内（好球）"}, {"id": "b", "text": "界外"}, {"id": "c", "text": "重发"}], "subject": "sports", "explanation": "球只要碰到界线就算界内，所以压线是好球。"}, {"id": "high-sports-009", "band": "high", "answer": "a", "prompt": "立定跳远测的主要是身体的什么能力？", "choices": [{"id": "a", "text": "腿部爆发力"}, {"id": "b", "text": "记忆力"}, {"id": "c", "text": "视力"}], "subject": "sports", "explanation": "立定跳远靠腿一下子用力蹬地起跳，主要测下肢爆发力。"}, {"id": "high-sports-010", "band": "high", "answer": "a", "prompt": "体测里的“坐位体前屈”主要测的是什么？", "choices": [{"id": "a", "text": "身体的柔韧性"}, {"id": "b", "text": "跑步速度"}, {"id": "c", "text": "肺活量"}], "subject": "sports", "explanation": "坐着伸手往前够，看能伸多远，测的是腰背和腿部的柔韧性。"}, {"id": "high-sports-011", "band": "high", "answer": "a", "prompt": "肺活量测试，主要反映的是身体哪个方面的能力？", "choices": [{"id": "a", "text": "一口气能呼出多少空气（呼吸能力）"}, {"id": "b", "text": "能跳多高"}, {"id": "c", "text": "握力大小"}], "subject": "sports", "explanation": "肺活量就是深吸一口气后尽力呼出的气体总量，反映呼吸系统强弱。"}, {"id": "high-sports-012", "band": "high", "answer": "a", "prompt": "运动中突然腿抽筋了，最该先做的是什么？", "choices": [{"id": "a", "text": "停下来，慢慢拉伸抽筋的肌肉"}, {"id": "b", "text": "继续用力跑"}, {"id": "c", "text": "使劲跳几下"}], "subject": "sports", "explanation": "抽筋时要停下来轻轻拉伸、按摩那块肌肉，硬撑容易拉伤。"}, {"id": "high-sports-013", "band": "high", "answer": "b", "prompt": "剧烈运动后，下面哪种做法更合适？", "choices": [{"id": "a", "text": "马上猛灌冰水、立刻坐下"}, {"id": "b", "text": "先慢走放松、少量多次喝温水"}, {"id": "c", "text": "立刻冲冷水澡"}], "subject": "sports", "explanation": "运动后要慢慢平复，小口多次补水，猛灌冰水或立刻坐下都对身体不好。"}, {"id": "high-sports-014", "band": "high", "answer": "b", "prompt": "一场足球比赛上半场一般踢多长时间？", "choices": [{"id": "a", "text": "30分钟"}, {"id": "b", "text": "45分钟"}, {"id": "c", "text": "60分钟"}], "subject": "sports", "explanation": "足球上下半场各45分钟，中间还有补时，总共约90分钟。"}, {"id": "high-sports-015", "band": "high", "answer": "a", "prompt": "篮球比赛中，进攻方在自己半场最多停留多少秒就必须把球推过中线？", "choices": [{"id": "a", "text": "8秒"}, {"id": "b", "text": "3秒"}, {"id": "c", "text": "24秒"}], "subject": "sports", "explanation": "这是“8秒规则”，要在8秒内把球带过中场；24秒是整轮进攻的限时。"}, {"id": "high-sports-016", "band": "high", "answer": "a", "prompt": "跳高比赛里，现在运动员最常用的过杆姿势叫什么？", "choices": [{"id": "a", "text": "背越式"}, {"id": "b", "text": "蛙跳式"}, {"id": "c", "text": "前滚翻式"}], "subject": "sports", "explanation": "背越式是背朝横杆翻过去，是目前最高效、用得最多的跳高姿势。"}, {"id": "high-sports-017", "band": "high", "answer": "a", "prompt": "游泳前最重要的安全准备是什么？", "choices": [{"id": "a", "text": "下水前做好热身、不在不熟悉的水域逞强"}, {"id": "b", "text": "吃得很饱再下水"}, {"id": "c", "text": "比谁憋气憋得久"}], "subject": "sports", "explanation": "游泳前要热身防抽筋，别去陌生深水区，也别空腹或刚吃饱就下水。"}, {"id": "high-sports-018", "band": "high", "answer": "b", "prompt": "马拉松全程大约是多少公里？", "choices": [{"id": "a", "text": "约10公里"}, {"id": "b", "text": "约42公里"}, {"id": "c", "text": "约100公里"}], "subject": "sports", "explanation": "马拉松全程约42.195公里，是非常考验耐力的长跑项目。"}, {"id": "high-sports-019", "band": "high", "answer": "a", "prompt": "判断有氧运动够不够，常说要让什么“跟上来”？", "choices": [{"id": "a", "text": "心率（心跳加快、微微出汗）"}, {"id": "b", "text": "体重一下变轻"}, {"id": "c", "text": "个子马上长高"}], "subject": "sports", "explanation": "有氧运动要让心跳和呼吸加快、身体微微发热出汗，这样才有锻炼效果。"}, {"id": "high-sports-020", "band": "high", "answer": "a", "prompt": "足球场上，守门员可以用手接球，主要是在什么范围内？", "choices": [{"id": "a", "text": "本方禁区（罚球区）内"}, {"id": "b", "text": "整个球场任何地方"}, {"id": "c", "text": "只能在中圈"}], "subject": "sports", "explanation": "守门员只能在自己的禁区内用手处理球，出了禁区用手就算手球犯规。"}, {"id": "high-sports-021", "band": "high", "answer": "a", "prompt": "50米跑测试主要测的是什么能力？", "choices": [{"id": "a", "text": "短距离的速度"}, {"id": "b", "text": "长跑耐力"}, {"id": "c", "text": "柔韧性"}], "subject": "sports", "explanation": "50米属于短跑，看的是谁起动快、跑得快，测的是速度。"}, {"id": "high-sports-022", "band": "high", "answer": "a", "prompt": "羽毛球或乒乓球发球前，下面哪种习惯更有助于打得稳？", "choices": [{"id": "a", "text": "站好位置、放松握拍、看准球"}, {"id": "b", "text": "闭着眼睛随便挥"}, {"id": "c", "text": "用最大力气乱抡"}], "subject": "sports", "explanation": "先站稳、放松、看准来球再出手，比一味用蛮力更容易打中、打稳。"}, {"id": "high-life-001", "band": "high", "answer": "a", "prompt": "钟表上时针指在 3 和 4 中间偏一点，分针指向 6，现在是几点？", "choices": [{"id": "a", "text": "3 点半"}, {"id": "b", "text": "4 点半"}, {"id": "c", "text": "3 点 06 分"}], "subject": "life", "explanation": "分针指 6 是过了半小时，时针在 3 和 4 中间，所以是 3 点 30 分。"}, {"id": "high-life-002", "band": "high", "answer": "b", "prompt": "电影 18:45 开场，路上要花 35 分钟，你最晚几点出门才不迟到？", "choices": [{"id": "a", "text": "18:00"}, {"id": "b", "text": "18:10"}, {"id": "c", "text": "18:30"}], "subject": "life", "explanation": "18:45 往前推 35 分钟是 18:10，再晚就赶不上了。"}, {"id": "high-life-003", "band": "high", "answer": "b", "prompt": "买了 17 块钱的东西，你递给收银员一张 50 和一个 2 块硬币，应该找回多少？", "choices": [{"id": "a", "text": "33 元"}, {"id": "b", "text": "35 元"}, {"id": "c", "text": "43 元"}], "subject": "life", "explanation": "一共付了 52 元，减去 17 元，找回 35 元。多给 2 块是为了凑整找零更方便。"}, {"id": "high-life-004", "band": "high", "answer": "b", "prompt": "一支笔 4.5 元，你想买 3 支，付 20 元够吗？能剩多少？", "choices": [{"id": "a", "text": "不够"}, {"id": "b", "text": "够，剩 6.5 元"}, {"id": "c", "text": "够，剩 5.5 元"}], "subject": "life", "explanation": "4.5×3=13.5 元，20-13.5=6.5 元。"}, {"id": "high-life-005", "band": "high", "answer": "b", "prompt": "过马路时绿灯开始闪烁了，你正站在路边还没下脚，最稳妥的做法是？", "choices": [{"id": "a", "text": "赶紧冲过去"}, {"id": "b", "text": "等下一个绿灯"}, {"id": "c", "text": "走到一半停在路中间"}], "subject": "life", "explanation": "绿灯闪烁说明快变红灯了，没下脚就别冒险，等下一轮最安全。"}, {"id": "high-life-006", "band": "high", "answer": "a", "prompt": "没有红绿灯的路口要过马路，正确顺序是？", "choices": [{"id": "a", "text": "左右都看，确认没车再走"}, {"id": "b", "text": "只看左边就走"}, {"id": "c", "text": "边看手机边走"}], "subject": "life", "explanation": "先看左、再看右、确认两边都没车才通过，全程别玩手机。"}, {"id": "high-life-007", "band": "high", "answer": "b", "prompt": "明天课表有数学、英语、体育、美术，整理书包最该先确认的是？", "choices": [{"id": "a", "text": "把所有课本都塞进去"}, {"id": "b", "text": "对着课表只装明天要用的"}, {"id": "c", "text": "看心情随便装"}], "subject": "life", "explanation": "照着课表装，既不漏带也不会背一书包用不上的书。"}, {"id": "high-life-008", "band": "high", "answer": "b", "prompt": "书桌上文具到处乱放，最有效的收纳办法是？", "choices": [{"id": "a", "text": "全堆进一个抽屉"}, {"id": "b", "text": "按类别分格子放，常用的放手边"}, {"id": "c", "text": "都摆在桌面上方便拿"}], "subject": "life", "explanation": "同类归同类、高频放近处，找东西才快，桌面也清爽。"}, {"id": "high-life-009", "band": "high", "answer": "a", "prompt": "换季了，夏天的衣服暂时不穿，怎么收最省地方又好找？", "choices": [{"id": "a", "text": "叠好放进收纳箱并贴上标签"}, {"id": "b", "text": "随手塞进衣柜最里面"}, {"id": "c", "text": "堆在床底下"}], "subject": "life", "explanation": "分类装箱贴标签，下次换季一眼就能找到，也不占衣柜常用空间。"}, {"id": "high-life-010", "band": "high", "answer": "b", "prompt": "一个人在家时门铃响了，对方说是查水表的，你该怎么办？", "choices": [{"id": "a", "text": "直接开门让他进来"}, {"id": "b", "text": "隔着门说大人不在，先给爸妈打电话"}, {"id": "c", "text": "假装没人但去开门看看"}], "subject": "life", "explanation": "陌生人上门不要开门，先联系家长核实，安全第一。"}, {"id": "high-life-011", "band": "high", "answer": "c", "prompt": "厨房锅里的油突然着火了，最不能做的是哪一件？", "choices": [{"id": "a", "text": "关掉火源"}, {"id": "b", "text": "用锅盖盖住灭火"}, {"id": "c", "text": "往锅里泼水"}], "subject": "life", "explanation": "油锅着火泼水会让火爆溅、越烧越大，应该盖锅盖隔绝空气并关火。"}, {"id": "high-life-012", "band": "high", "answer": "b", "prompt": "插座或电器进水了，你想拔掉它，正确做法是？", "choices": [{"id": "a", "text": "湿手直接去拔插头"}, {"id": "b", "text": "先关总闸，手干了再处理"}, {"id": "c", "text": "用金属夹子去夹"}], "subject": "life", "explanation": "水和湿手都导电，先断总电源、保持手干燥再操作，避免触电。"}, {"id": "high-life-013", "band": "high", "answer": "b", "prompt": "别人帮了你一个忙，最得体的回应是？", "choices": [{"id": "a", "text": "当作没发生"}, {"id": "b", "text": "真诚地说声谢谢"}, {"id": "c", "text": "默默走开"}], "subject": "life", "explanation": "接受帮助后表达感谢，是基本的礼貌，也让人愿意继续帮你。"}, {"id": "high-life-014", "band": "high", "answer": "a", "prompt": "到同学家做客，进门时比较有礼貌的做法是？", "choices": [{"id": "a", "text": "主动跟对方家长打招呼"}, {"id": "b", "text": "直接冲进房间玩"}, {"id": "c", "text": "把鞋随便踢在门口"}], "subject": "life", "explanation": "到别人家先和长辈问好、把鞋摆整齐，是受欢迎的客人。"}, {"id": "high-life-015", "band": "high", "answer": "b", "prompt": "吃饭时想夹离自己很远的那盘菜，比较有礼貌的做法是？", "choices": [{"id": "a", "text": "站起来伸长胳膊去够"}, {"id": "b", "text": "请旁边的人帮忙递一下"}, {"id": "c", "text": "把盘子整个端到自己面前"}], "subject": "life", "explanation": "够不到就客气地请人帮忙传，比起身横扫餐桌更得体。"}, {"id": "high-life-016", "band": "high", "answer": "a", "prompt": "天气预报说今天 12 到 28 度、午后有雷阵雨，出门怎么穿带最合适？", "choices": [{"id": "a", "text": "穿短袖、带一件薄外套和伞"}, {"id": "b", "text": "只穿短袖什么都不带"}, {"id": "c", "text": "穿厚棉袄"}], "subject": "life", "explanation": "早晚 12 度凉、午间 28 度热，温差大要带薄外套，午后有雨得带伞。"}, {"id": "high-life-017", "band": "high", "answer": "a", "prompt": "出门看到天阴沉沉、风也变大了，比较聪明的判断是？", "choices": [{"id": "a", "text": "可能要下雨，带把伞"}, {"id": "b", "text": "肯定是大晴天"}, {"id": "c", "text": "和天气没关系"}], "subject": "life", "explanation": "乌云压顶加起风往往是降雨的前兆，带伞有备无患。"}, {"id": "high-life-018", "band": "high", "answer": "a", "prompt": "冬天从很热的室内走到很冷的室外，对身体最友好的做法是？", "choices": [{"id": "a", "text": "出门前先把外套穿好再走出去"}, {"id": "b", "text": "光着膀子冲出去凉快"}, {"id": "c", "text": "出去后觉得冷再回来加衣"}], "subject": "life", "explanation": "温差大时提前穿好外套，能避免忽冷忽热着凉感冒。"}, {"id": "high-life-019", "band": "high", "answer": "a", "prompt": "喝完的塑料矿泉水瓶，应该扔进哪类垃圾桶？", "choices": [{"id": "a", "text": "可回收物"}, {"id": "b", "text": "厨余垃圾"}, {"id": "c", "text": "有害垃圾"}], "subject": "life", "explanation": "塑料瓶干净可再利用，属于可回收物，最好先倒空压扁。"}, {"id": "high-life-020", "band": "high", "answer": "b", "prompt": "用完的废旧电池和过期药品，应该投到哪一类？", "choices": [{"id": "a", "text": "其他垃圾"}, {"id": "b", "text": "有害垃圾"}, {"id": "c", "text": "可回收物"}], "subject": "life", "explanation": "电池、药品含有害物质，要单独投到有害垃圾，不能随便丢。"}, {"id": "high-life-021", "band": "high", "answer": "a", "prompt": "吃剩的苹果核和菜叶子，属于哪一类垃圾？", "choices": [{"id": "a", "text": "厨余（湿）垃圾"}, {"id": "b", "text": "可回收物"}, {"id": "c", "text": "有害垃圾"}], "subject": "life", "explanation": "果皮、菜叶、剩饭这类容易腐烂的食物残渣属于厨余垃圾。"}, {"id": "high-life-022", "band": "high", "answer": "b", "prompt": "一杯没喝完的奶茶要扔掉，最规范的丢弃步骤是？", "choices": [{"id": "a", "text": "连杯带奶茶整杯扔进可回收"}, {"id": "b", "text": "倒掉液体、料归厨余，杯子和吸管再分别处理"}, {"id": "c", "text": "随手扔进任意一个桶"}], "subject": "life", "explanation": "先倒掉剩余液体，珍珠等料属厨余，塑料杯和吸管按规定分类，这才是正确的拆分丢弃。"}, {"id": "high-social-001", "band": "high", "answer": "b", "prompt": "你借给同桌的笔，过了一周他还没还，每次问他都说“忘带了”。最聪明又不伤感情的做法是？", "choices": [{"id": "a", "text": "当众喊“你又赖账”，让大家都听见"}, {"id": "b", "text": "笑着说“明天记得带哈，我画画要用，给你设个闹钟提醒？”"}, {"id": "c", "text": "从此再也不理他"}], "subject": "social", "explanation": "给个具体时间点和理由，再帮他“记住”，既要回了东西又没撕破脸。"}, {"id": "high-social-002", "band": "high", "answer": "b", "prompt": "同学想借你刚买的新书，可你还没看完。怎么回应最得体？", "choices": [{"id": "a", "text": "“不借，自己买去”"}, {"id": "b", "text": "“我先看完，周五给你，行不行？”"}, {"id": "c", "text": "勉强借了，心里却一直生气"}], "subject": "social", "explanation": "不必硬撑着借出去，说清自己的安排、再给个时间，是真诚也是边界。"}, {"id": "high-social-003", "band": "high", "answer": "b", "prompt": "你总借东西忘了还，朋友有点不高兴了。最负责的做法是？", "choices": [{"id": "a", "text": "说“多大点事，至于吗”"}, {"id": "b", "text": "主动说“对不起拖太久了”，并立刻还回去"}, {"id": "c", "text": "装作没这回事"}], "subject": "social", "explanation": "借了要还、错了要认，主动归还比一百句解释都管用。"}, {"id": "high-social-004", "band": "high", "answer": "b", "prompt": "排队打饭时，有人直接插到你前面。怎么提醒最机智、不吵架？", "choices": [{"id": "a", "text": "一把把他推开"}, {"id": "b", "text": "微笑提醒“后面排队哦，我也等好一会儿啦”"}, {"id": "c", "text": "什么都不说，憋着生气"}], "subject": "social", "explanation": "语气友好但立场清楚，多数人被礼貌点到都会不好意思地排回去。"}, {"id": "high-social-005", "band": "high", "answer": "b", "prompt": "低年级小同学不懂事插了队。比较好的处理是？", "choices": [{"id": "a", "text": "凶他一顿让他长记性"}, {"id": "b", "text": "蹲下来轻声说“小朋友，我们要从后面排队哦”"}, {"id": "c", "text": "推他出去"}], "subject": "social", "explanation": "对更小的孩子，耐心解释规则比凶巴巴更有用，也是大哥哥大姐姐的样子。"}, {"id": "high-social-006", "band": "high", "answer": "b", "prompt": "朋友招手让你“来我这儿插个队”，可后面还有很多人在等。你怎么做最妥当？", "choices": [{"id": "a", "text": "赶紧钻过去，反正有人罩着"}, {"id": "b", "text": "说“谢啦，我还是去后面排，不然别人该有意见了”"}, {"id": "c", "text": "骂朋友多管闲事"}], "subject": "social", "explanation": "不占这个便宜既公平又顾全别人，还能婉拒得让朋友不尴尬。"}, {"id": "high-social-007", "band": "high", "answer": "b", "prompt": "分组时有个同学没人愿意带，被晾在一边。最善意的做法是？", "choices": [{"id": "a", "text": "跟着大家一起躲开他"}, {"id": "b", "text": "主动说“来我们组吧，正好缺个人”"}, {"id": "c", "text": "假装没看见"}], "subject": "social", "explanation": "一句邀请就能让一个人不被孤立，这是真正的善良和勇气。"}, {"id": "high-social-008", "band": "high", "answer": "b", "prompt": "你想和最好的朋友同一组，但老师已经分好了别的组。怎么应对最成熟？", "choices": [{"id": "a", "text": "赌气不参与活动"}, {"id": "b", "text": "接受安排，跟新组员好好合作，课后再约朋友玩"}, {"id": "c", "text": "一直缠着老师非要换组"}], "subject": "social", "explanation": "不是所有事都能如愿，能跟不熟的人也合作得来，是很厉害的能力。"}, {"id": "high-social-009", "band": "high", "answer": "b", "prompt": "小组里有个同学总不出力，光想拿大家的成果。怎么处理比较聪明？", "choices": [{"id": "a", "text": "当面骂他懒鬼"}, {"id": "b", "text": "私下问他“你想负责哪部分？画画还是查资料？”给他具体任务"}, {"id": "c", "text": "什么都自己扛，心里默默记仇"}], "subject": "social", "explanation": "给一个明确又好上手的任务，比指责更能让人真正动起来。"}, {"id": "high-social-010", "band": "high", "answer": "b", "prompt": "今天轮到你和另一个同学值日，他却偷偷溜走了。最得体的做法是？", "choices": [{"id": "a", "text": "也跟着不扫了，谁怕谁"}, {"id": "b", "text": "先把自己那份做完，明天提醒他“今天我替你顶了，下次到你哦”"}, {"id": "c", "text": "马上去老师那儿告状，添油加醋"}], "subject": "social", "explanation": "该做的先做好，再温和地把约定挑明，比直接告状更显风度也更有效。"}, {"id": "high-social-011", "band": "high", "answer": "b", "prompt": "你值日时不小心把垃圾桶碰倒了，撒了一地。最该做的是？", "choices": [{"id": "a", "text": "趁没人看见赶紧溜"}, {"id": "b", "text": "自己收拾干净，需要帮忙就喊一声同学"}, {"id": "c", "text": "怪是垃圾桶放得不对"}], "subject": "social", "explanation": "自己弄的自己收拾，必要时请人帮忙——担责任不丢人，逃避才丢人。"}, {"id": "high-social-012", "band": "high", "answer": "b", "prompt": "值日搭档干得很认真，把活儿都揽了，连你的那份也做了。你最好怎么说？", "choices": [{"id": "a", "text": "“正好，省我事了”就走人"}, {"id": "b", "text": "“谢谢你！剩下的我来，下次我请你喝牛奶”"}, {"id": "c", "text": "什么都不说，下次还指望他"}], "subject": "social", "explanation": "别人的好意要看见、要道谢，再把活儿接回来，合作才长久。"}, {"id": "high-social-013", "band": "high", "answer": "b", "prompt": "你和好朋友吵架了，三天没说话，但你其实挺想和好。最勇敢的一步是？", "choices": [{"id": "a", "text": "一直等对方先开口"}, {"id": "b", "text": "主动发个消息“那天我也有不对，我们还是好朋友吧”"}, {"id": "c", "text": "到处说他的坏话出气"}], "subject": "social", "explanation": "先迈一步道歉不是认输，而是更看重这段友谊——这需要勇气。"}, {"id": "high-social-014", "band": "high", "answer": "b", "prompt": "朋友来跟你道歉，可你还有点气。怎么回应最大气？", "choices": [{"id": "a", "text": "“晚了，我不想理你”"}, {"id": "b", "text": "“没事啦，我也有不对，过去就过去了”"}, {"id": "c", "text": "冷冷地“哦”一声"}], "subject": "social", "explanation": "别人鼓起勇气道歉时，给个台阶接住，是一种温柔的强大。"}, {"id": "high-social-015", "band": "high", "answer": "b", "prompt": "两个好朋友因为误会闹翻，都来找你诉苦。你最该做的是？", "choices": [{"id": "a", "text": "选一边站，帮一个去骂另一个"}, {"id": "b", "text": "两边都听听，帮他们把误会说清楚，劝他们当面谈"}, {"id": "c", "text": "把两人说的话互相传，越传越乱"}], "subject": "social", "explanation": "当“和事佬”要公正、要传真话，目标是化解误会而不是火上浇油。"}, {"id": "high-social-016", "band": "high", "answer": "b", "prompt": "同学开玩笑说“你今天发型像被雷劈过”。既不生气又能漂亮回击的是？", "choices": [{"id": "a", "text": "“你才像，你全家都像”"}, {"id": "b", "text": "哈哈一笑“那我可是有电的人，离我远点哦”"}, {"id": "c", "text": "当场哭出来"}], "subject": "social", "explanation": "把玩笑接住再幽默地抛回去，既化解尴尬又显得自信，谁都不受伤。"}, {"id": "high-social-017", "band": "high", "answer": "b", "prompt": "有人故意激你“就你那分数也敢说会做题？”最聪明的回应是？", "choices": [{"id": "a", "text": "“关你什么事”然后扭头就走"}, {"id": "b", "text": "平静地说“这题我确实会，要不我讲给你听？”"}, {"id": "c", "text": "气得把卷子撕了"}], "subject": "social", "explanation": "用实力和善意回应挑衅，比对骂更有底气，对方往往就没词了。"}, {"id": "high-social-018", "band": "high", "answer": "b", "prompt": "同学拌嘴时说了句过分的话，你看出他其实是嘴硬。最成熟的做法是？", "choices": [{"id": "a", "text": "马上回敬一句更狠的"}, {"id": "b", "text": "深呼吸一下，说“你是不是今天有啥不开心？我们别吵了”"}, {"id": "c", "text": "记仇等机会报复"}], "subject": "social", "explanation": "看穿对方的情绪、先停下争吵，常常能把一场火药味变成关心。"}, {"id": "high-social-019", "band": "high", "answer": "b", "prompt": "小组讨论时你和同学意见不合，争得脸红脖子粗。怎么收场最好？", "choices": [{"id": "a", "text": "谁声音大谁说了算"}, {"id": "b", "text": "说“我们各有道理，要不两个方案都列出来，让大家投票”"}, {"id": "c", "text": "直接退出不干了"}], "subject": "social", "explanation": "意见不同很正常，把分歧交给规则（比如投票）来定，比吵赢更服众。"}, {"id": "high-social-020", "band": "high", "answer": "b", "prompt": "你不小心听到同学在背后议论你的缺点。最聪明的态度是？", "choices": [{"id": "a", "text": "冲过去大吵一架"}, {"id": "b", "text": "先想想有没有道理，有则改之，没必要的话就一笑而过"}, {"id": "c", "text": "也偷偷去说他坏话"}], "subject": "social", "explanation": "别人的话当镜子用：有用的留下，没用的放下，不必为闲话伤了自己。"}, {"id": "high-social-021", "band": "high", "answer": "b", "prompt": "新转来的同学一个人吃饭、不太敢说话。你能做的最暖的事是？", "choices": [{"id": "a", "text": "觉得跟自己没关系"}, {"id": "b", "text": "主动坐过去“嗨，我叫……要不要一起吃？”"}, {"id": "c", "text": "远远地观察他"}], "subject": "social", "explanation": "一句主动的招呼，可能就是别人在新环境里收到的第一份温暖。"}, {"id": "high-social-022", "band": "high", "answer": "b", "prompt": "同学考砸了很难过，跑来跟你哭。最贴心的回应是？", "choices": [{"id": "a", "text": "“我早说你不努力吧”"}, {"id": "b", "text": "先陪着听他说，再说“这次没考好没关系，下次一起加油”"}, {"id": "c", "text": "“别哭了，烦不烦”"}], "subject": "social", "explanation": "难过的人最需要的是被听见和被鼓励，而不是被评判。"}, {"id": "high-interest-001", "band": "high", "answer": "a", "prompt": "《原神》《崩坏：星穹铁道》这类游戏里，玩家抽到角色和武器的玩法一般叫什么？", "choices": [{"id": "a", "text": "抽卡（祈愿）"}, {"id": "b", "text": "种菜"}, {"id": "c", "text": "钓鱼"}], "subject": "interest", "explanation": "这种用资源随机获得角色的系统就叫抽卡，原神里好听点叫“祈愿”。"}, {"id": "high-interest-002", "band": "high", "answer": "b", "prompt": "《我的世界》里把矿石、木头放进去能合成工具的那个 3×3 格子界面叫什么？", "choices": [{"id": "a", "text": "熔炉"}, {"id": "b", "text": "工作台"}, {"id": "c", "text": "箱子"}], "subject": "interest", "explanation": "工作台提供 3×3 的合成格，熔炉是用来烧炼的，箱子只能存东西。"}, {"id": "high-interest-003", "band": "high", "answer": "b", "prompt": "篮球比赛里在三分线外投进一个球，能得几分？", "choices": [{"id": "a", "text": "2 分"}, {"id": "b", "text": "3 分"}, {"id": "c", "text": "1 分"}], "subject": "interest", "explanation": "三分线外命中算 3 分，线内是 2 分，罚球才是 1 分。"}, {"id": "high-interest-004", "band": "high", "answer": "b", "prompt": "玩拼装积木时，要让两块零件“咬”得很牢，关键是什么？", "choices": [{"id": "a", "text": "颜色一样"}, {"id": "b", "text": "凸点和凹槽对齐压紧"}, {"id": "c", "text": "零件越大越好"}], "subject": "interest", "explanation": "积木靠上面的凸点扣进下面的凹槽来固定，对齐压紧才结实，跟颜色没关系。"}, {"id": "high-interest-005", "band": "high", "answer": "a", "prompt": "羽毛球里把球高高打到对方后场底线，逼对方退后的那一拍，常被叫做什么？", "choices": [{"id": "a", "text": "高远球"}, {"id": "b", "text": "搓小球"}, {"id": "c", "text": "发球"}], "subject": "interest", "explanation": "高远球又高又远落到底线，能把对手逼到后场；搓小球是吊到网前的小球。"}, {"id": "high-interest-006", "band": "high", "answer": "a", "prompt": "很多手游和电脑游戏里的“FPS”说的是哪个意思？", "choices": [{"id": "a", "text": "每秒画面帧数"}, {"id": "b", "text": "游戏价格"}, {"id": "c", "text": "玩家人数"}], "subject": "interest", "explanation": "FPS 指每秒显示多少帧画面，数字越高画面越流畅。"}, {"id": "high-interest-007", "band": "high", "answer": "b", "prompt": "听歌时一首歌里最容易让人跟着唱、反复出现的高潮部分，一般叫什么？", "choices": [{"id": "a", "text": "前奏"}, {"id": "b", "text": "副歌"}, {"id": "c", "text": "尾奏"}], "subject": "interest", "explanation": "副歌就是那段重复出现、最抓耳的高潮，前奏在开头、尾奏在结尾。"}, {"id": "high-interest-008", "band": "high", "answer": "a", "prompt": "折纸时想折出一只立体的纸鹤，最开始通常要把正方形纸折成什么基础形？", "choices": [{"id": "a", "text": "正方基础形（双正方形）"}, {"id": "b", "text": "揉成一团"}, {"id": "c", "text": "卷成筒"}], "subject": "interest", "explanation": "纸鹤一般从“正方基础形”开始一步步折出翅膀和头颈，揉团和卷筒都折不成。"}, {"id": "high-interest-009", "band": "high", "answer": "a", "prompt": "足球比赛中，守门员用手接球只能在哪个范围里？", "choices": [{"id": "a", "text": "本方禁区内"}, {"id": "b", "text": "整个半场"}, {"id": "c", "text": "随便哪都行"}], "subject": "interest", "explanation": "只有在自己的禁区内门将才能用手碰球，出了禁区用手就要犯规。"}, {"id": "high-interest-010", "band": "high", "answer": "a", "prompt": "很多动画和漫画里说的“声优”，指的是做什么的人？", "choices": [{"id": "a", "text": "给角色配音的人"}, {"id": "b", "text": "画画的人"}, {"id": "c", "text": "写剧本的人"}], "subject": "interest", "explanation": "声优就是配音演员，用声音演活动画角色；画画的叫原画/作画。"}, {"id": "high-interest-011", "band": "high", "answer": "a", "prompt": "玩魔方时，一次能让一个面转 90 度的最小操作单位，通常被称为什么？", "choices": [{"id": "a", "text": "一步（一个转动）"}, {"id": "b", "text": "一层贴纸"}, {"id": "c", "text": "一个角块"}], "subject": "interest", "explanation": "魔方的解法都用“步数”来数，每转动一个面就是一步。"}, {"id": "high-interest-012", "band": "high", "answer": "a", "prompt": "打乒乓球时，球落到自己台面再弹起、对手没接住，这一分算谁的？", "choices": [{"id": "a", "text": "算发球/击球方得分"}, {"id": "b", "text": "算对手得分"}, {"id": "c", "text": "不算分重发"}], "subject": "interest", "explanation": "球正常过网落到对方台面、对方没接好，得分的是把球打过去的一方。"}, {"id": "high-interest-013", "band": "high", "answer": "a", "prompt": "不少卡牌和手游里的“SSR”表示什么？", "choices": [{"id": "a", "text": "最稀有、最高级的卡"}, {"id": "b", "text": "最便宜的卡"}, {"id": "c", "text": "坏掉的卡"}], "subject": "interest", "explanation": "R、SR、SSR 是稀有度等级，SSR 通常是最稀有最强的那一档。"}, {"id": "high-interest-014", "band": "high", "answer": "a", "prompt": "画画时把红色和黄色调在一起，会得到什么颜色？", "choices": [{"id": "a", "text": "橙色"}, {"id": "b", "text": "绿色"}, {"id": "c", "text": "紫色"}], "subject": "interest", "explanation": "红加黄出橙，黄加蓝出绿，红加蓝出紫，这是颜料三原色的基本搭配。"}, {"id": "high-interest-015", "band": "high", "answer": "a", "prompt": "滑板上做的最基础、能让人和板一起跳起来的招式，常被叫什么？", "choices": [{"id": "a", "text": "Ollie（豚跳）"}, {"id": "b", "text": "刹车"}, {"id": "c", "text": "坐着滑"}], "subject": "interest", "explanation": "Ollie 是滑板入门必学的弹跳动作，几乎所有花式都从它开始。"}, {"id": "high-interest-016", "band": "high", "answer": "a", "prompt": "看动画时常说的“番剧”里的“一番”，最接近下面哪个意思？", "choices": [{"id": "a", "text": "一季（一档连载动画）"}, {"id": "b", "text": "一集"}, {"id": "c", "text": "一个角色"}], "subject": "interest", "explanation": "“番”来自日语，指一档/一季连载的动画作品，不是单指一集。"}, {"id": "high-interest-017", "band": "high", "answer": "a", "prompt": "玩团队竞技游戏时常说的“团灭”是什么意思？", "choices": [{"id": "a", "text": "一方全队被击败"}, {"id": "b", "text": "游戏崩溃了"}, {"id": "c", "text": "所有人都赢了"}], "subject": "interest", "explanation": "团灭就是一整队的人全被打倒，常常会直接决定一波团战的胜负。"}, {"id": "high-interest-018", "band": "high", "answer": "a", "prompt": "做手工想把两张纸牢牢粘住又不想等很久，下面哪种更合适？", "choices": [{"id": "a", "text": "固体胶/双面胶"}, {"id": "b", "text": "清水"}, {"id": "c", "text": "橡皮"}], "subject": "interest", "explanation": "固体胶或双面胶粘纸又快又牢，清水粘不住，橡皮是用来擦的。"}, {"id": "high-interest-019", "band": "high", "answer": "a", "prompt": "游泳比赛里，趴着、两只手臂同时向前划再分开的泳姿是哪种？", "choices": [{"id": "a", "text": "蝶泳"}, {"id": "b", "text": "自由泳"}, {"id": "c", "text": "仰泳"}], "subject": "interest", "explanation": "蝶泳双臂同时往前划水、腿像海豚摆动；自由泳是轮流划手，仰泳则是脸朝上。"}, {"id": "high-interest-020", "band": "high", "answer": "a", "prompt": "很多养成、模拟游戏里说的“肝”，玩家口中一般指什么？", "choices": [{"id": "a", "text": "花很多时间反复刷"}, {"id": "b", "text": "花钱充值"}, {"id": "c", "text": "退出游戏"}], "subject": "interest", "explanation": "“肝”指靠大量时间反复刷资源；靠花钱堆数值那个一般叫“氪”。"}, {"id": "high-interest-021", "band": "high", "answer": "a", "prompt": "弹尤克里里（小吉他）时，左手按住琴弦、右手拨弦，主要是为了得到什么？", "choices": [{"id": "a", "text": "不同的音高"}, {"id": "b", "text": "更大的声音"}, {"id": "c", "text": "换个颜色"}], "subject": "interest", "explanation": "左手按在不同品位会改变弦的振动长度，从而弹出不同高低的音。"}, {"id": "high-interest-022", "band": "high", "answer": "a", "prompt": "跳绳想连续跳得久又不绊脚，下面哪个习惯最有帮助？", "choices": [{"id": "a", "text": "主要用手腕甩绳、轻轻起跳"}, {"id": "b", "text": "整条手臂使劲大甩"}, {"id": "c", "text": "每次都跳得越高越好"}], "subject": "interest", "explanation": "靠手腕带绳、起跳别太高最省力也最稳；大甩手臂、跳太高反而容易累和绊到。"}, {"id": "high-funny-001", "band": "high", "answer": "b", "prompt": "一个人走在沙漠里，背上背了个大包，为什么死了？", "choices": [{"id": "a", "text": "渴死了"}, {"id": "b", "text": "降落伞没打开"}, {"id": "c", "text": "中暑了"}], "subject": "funny", "explanation": "那个大包其实是没打开的降落伞，他是摔下来的。"}, {"id": "high-funny-002", "band": "high", "answer": "b", "prompt": "什么车永远不需要加油也不需要充电，却能一直跑？", "choices": [{"id": "a", "text": "玩具车"}, {"id": "b", "text": "风车"}, {"id": "c", "text": "碰碰车"}], "subject": "funny", "explanation": "风车靠风转，根本不烧油也不用电。"}, {"id": "high-funny-003", "band": "high", "answer": "a", "prompt": "考试时同桌问你借橡皮，你借了，但是他成绩反而比你高，为什么？", "choices": [{"id": "a", "text": "他本来就比你聪明"}, {"id": "b", "text": "橡皮把你的好答案擦掉了"}, {"id": "c", "text": "这道题没有标准答案"}], "subject": "funny", "explanation": "别想太多，橡皮跟成绩没关系——这是个故意带歪你的脑筋急转弯。"}, {"id": "high-funny-004", "band": "high", "answer": "a", "prompt": "什么字大家看了都念错？", "choices": [{"id": "a", "text": "错"}, {"id": "b", "text": "对"}, {"id": "c", "text": "念"}], "subject": "funny", "explanation": "题目说\"念错\"，那个字就是\"错\"字本身。"}, {"id": "high-funny-005", "band": "high", "answer": "c", "prompt": "一个数学老师丢了一只猫，他在黑板上写了什么寻猫启事？", "choices": [{"id": "a", "text": "求一只猫的解"}, {"id": "b", "text": "已知一只猫，求猫"}, {"id": "c", "text": "设这只猫为 X"}], "subject": "funny", "explanation": "数学老师当然把走丢的未知猫设成 X 啦。"}, {"id": "high-funny-006", "band": "high", "answer": "a", "prompt": "冰箱里放了一只大象，怎么才能再放进一只长颈鹿？", "choices": [{"id": "a", "text": "先把大象拿出来"}, {"id": "b", "text": "把冰箱换大一点"}, {"id": "c", "text": "把长颈鹿折起来"}], "subject": "funny", "explanation": "经典连环问：要放长颈鹿，得先把大象请出来。"}, {"id": "high-funny-007", "band": "high", "answer": "b", "prompt": "什么东西你一说出它的名字，它就立刻消失了？", "choices": [{"id": "a", "text": "影子"}, {"id": "b", "text": "安静"}, {"id": "c", "text": "泡泡"}], "subject": "funny", "explanation": "你一开口说\"安静\"，安静就被你打破了。"}, {"id": "high-funny-008", "band": "high", "answer": "b", "prompt": "小明把一张纸对折，能对折多少次后厚度超过他的身高？", "choices": [{"id": "a", "text": "大约 100 次"}, {"id": "b", "text": "其实折几次手就折不动了"}, {"id": "c", "text": "永远折不到"}], "subject": "funny", "explanation": "理论上 7 次左右厚度就翻很多倍，但普通纸对折六七次手就折不动了，根本到不了身高。"}, {"id": "high-funny-009", "band": "high", "answer": "c", "prompt": "什么情况下，1 加 1 不等于 2？", "choices": [{"id": "a", "text": "永远等于 2"}, {"id": "b", "text": "算错的时候"}, {"id": "c", "text": "一堆沙加一堆沙，还是一堆"}], "subject": "funny", "explanation": "一堆沙倒进另一堆沙，合起来还是\"一堆\"，所以 1 堆 + 1 堆 = 1 堆。"}, {"id": "high-funny-010", "band": "high", "answer": "b", "prompt": "一座桥写着\"限重 5 吨\"，一辆 4 吨的卡车正好开到桥中间，这时一只 1 公斤的小鸟落在车顶，桥会塌吗？", "choices": [{"id": "a", "text": "会，正好超重了"}, {"id": "b", "text": "不会，差得远呢"}, {"id": "c", "text": "会，因为小鸟很重"}], "subject": "funny", "explanation": "4 吨加 1 公斤离 5 吨还差着将近 1 吨，小鸟那点重量根本不算啥。"}, {"id": "high-funny-011", "band": "high", "answer": "a", "prompt": "什么东西明明是你的，但别人用得比你多？", "choices": [{"id": "a", "text": "你的名字"}, {"id": "b", "text": "你的橡皮"}, {"id": "c", "text": "你的书包"}], "subject": "funny", "explanation": "你的名字是你的，可平时都是别人在叫你、在用它。"}, {"id": "high-funny-012", "band": "high", "answer": "a", "prompt": "钟表店里所有的钟都停了，可老板说生意照样很好，为什么？", "choices": [{"id": "a", "text": "大家来买不会停的钟"}, {"id": "b", "text": "停了的钟一天也能准两次"}, {"id": "c", "text": "老板在吹牛"}], "subject": "funny", "explanation": "钟都停了说明它们都坏了，大家正好来买新的、能走的钟，所以生意好。"}, {"id": "high-funny-013", "band": "high", "answer": "b", "prompt": "小红把同一道题做了三遍，每遍答案都不一样，老师却给了满分，为什么？", "choices": [{"id": "a", "text": "老师没看仔细"}, {"id": "b", "text": "那是一道开放题，答案不止一个"}, {"id": "c", "text": "老师很喜欢小红"}], "subject": "funny", "explanation": "开放性题目本来就允许多种答案，三个都对当然满分。"}, {"id": "high-funny-014", "band": "high", "answer": "b", "prompt": "一个房间里有 10 根蜡烛，风吹灭了 3 根，过一会儿又吹灭了 2 根，最后房间里还剩几根蜡烛？", "choices": [{"id": "a", "text": "5 根"}, {"id": "b", "text": "10 根"}, {"id": "c", "text": "5 根，灭的烧没了"}], "subject": "funny", "explanation": "蜡烛被吹灭只是不亮了，又没消失，房间里还是 10 根。"}, {"id": "high-funny-015", "band": "high", "answer": "a", "prompt": "什么东西，越往里走越往外？", "choices": [{"id": "a", "text": "隧道"}, {"id": "b", "text": "迷宫"}, {"id": "c", "text": "螺丝（往里拧就往里走，往外拧就出来）"}], "subject": "funny", "explanation": "隧道走到一半之后，越往前走其实就越接近出口、越往\"外\"了。"}, {"id": "high-funny-016", "band": "high", "answer": "a", "prompt": "一个班 30 个同学，每人和其他每个人都握一次手，老师却说一共握了不到 30 次，可能吗？", "choices": [{"id": "a", "text": "不可能，肯定超过 30 次"}, {"id": "b", "text": "可能，老师在开玩笑"}, {"id": "c", "text": "可能，只数了自己的"}], "subject": "funny", "explanation": "30 个人两两握手要 435 次，远超 30，老师这话明显不对——别被绕进去。"}, {"id": "high-funny-017", "band": "high", "answer": "a", "prompt": "什么字，去掉一半还是它自己？", "choices": [{"id": "a", "text": "半"}, {"id": "b", "text": "田"}, {"id": "c", "text": "日"}], "subject": "funny", "explanation": "\"半\"这个字，意思就是去掉一半——它本身就在说自己。"}, {"id": "high-funny-018", "band": "high", "answer": "c", "prompt": "小华倒着把日历从 12 月看到 1 月，他发现一年里最短的月份是哪个？", "choices": [{"id": "a", "text": "二月"}, {"id": "b", "text": "十二月"}, {"id": "c", "text": "怎么看都是二月"}], "subject": "funny", "explanation": "不管正着看还是倒着看，二月天数最少，永远是最短的那个月。"}, {"id": "high-funny-019", "band": "high", "answer": "b", "prompt": "什么东西，你越分给别人，自己反而越多？", "choices": [{"id": "a", "text": "零食"}, {"id": "b", "text": "快乐"}, {"id": "c", "text": "零花钱"}], "subject": "funny", "explanation": "快乐分享给别人，自己不但不会少，反而会更开心。"}, {"id": "high-funny-020", "band": "high", "answer": "b", "prompt": "一只蜗牛要爬 10 米高的井，白天爬 3 米，晚上滑下 2 米，它第几天能爬出井口？", "choices": [{"id": "a", "text": "第 10 天"}, {"id": "b", "text": "第 8 天"}, {"id": "c", "text": "永远爬不出来"}], "subject": "funny", "explanation": "每天净爬 1 米，第 7 天结束在 7 米，第 8 天白天爬 3 米正好到 10 米爬出去了，不会再滑下来。"}, {"id": "high-funny-021", "band": "high", "answer": "a", "prompt": "什么问题，不管你怎么回答都是错的？", "choices": [{"id": "a", "text": "\"你睡着了吗？\""}, {"id": "b", "text": "\"你叫什么名字？\""}, {"id": "c", "text": "\"现在几点了？\""}], "subject": "funny", "explanation": "真睡着了你根本没法回答；能开口答\"睡着了\"，那就说明你没睡——怎么答都不对。"}, {"id": "high-funny-022", "band": "high", "answer": "b", "prompt": "老师说：\"谁能用一句话让我又哭又笑？\" 哪个回答最可能成功？", "choices": [{"id": "a", "text": "\"老师，您今天真好看。\""}, {"id": "b", "text": "\"老师，我帮您把作业全改完了……改错了。\""}, {"id": "c", "text": "\"老师，下课了。\""}], "subject": "funny", "explanation": "听到有人帮忙改作业先笑了，再听说全改错了又想哭，一句话同时戳中两种情绪。"}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
