insert into public.game_content (game, data, updated_at) values ('dice', $seed$[{"tag": "动作", "text": "单脚站立 10 秒，不许扶东西"}, {"tag": "动作", "text": "原地跳 10 下，边跳边数数"}, {"tag": "动作", "text": "做 5 个深蹲，最后一个停住 3 秒"}, {"tag": "动作", "text": "学小兔子蹦着走到门口再蹦回来"}, {"tag": "动作", "text": "把双手举高，慢慢转一个圈"}, {"tag": "动作", "text": "做一个最帅的造型，保持 5 秒不动"}, {"tag": "动作", "text": "原地踏步走 10 步，像在阅兵"}, {"tag": "动作", "text": "伸个最大的懒腰，再打个夸张的哈欠"}, {"tag": "动作", "text": "用手指在空中写下自己的名字"}, {"tag": "动作", "text": "左右手同时画圈，一个顺时针一个逆时针"}, {"tag": "动作", "text": "金鸡独立，闭上眼睛坚持 5 秒"}, {"tag": "动作", "text": "学螃蟹横着走，从这边走到那边"}, {"tag": "动作", "text": "把一本书顶在头上走 5 步不掉下来"}, {"tag": "动作", "text": "原地转三圈，再走一条直线试试"}, {"tag": "动作", "text": "做 3 个开合跳，节奏要稳"}, {"tag": "动作", "text": "弯腰摸到脚尖，再慢慢站直"}, {"tag": "动作", "text": "用脚趾夹起一张纸巾"}, {"tag": "动作", "text": "学小袋鼠双脚并拢往前跳 5 下"}, {"tag": "模仿", "text": "学一种动物叫 3 声，让大家猜是什么"}, {"tag": "模仿", "text": "模仿一只猫伸懒腰的样子"}, {"tag": "模仿", "text": "模仿一个老师上课点名的样子"}, {"tag": "模仿", "text": "模仿妈妈喊你起床的语气"}, {"tag": "模仿", "text": "学小狗摇尾巴开心的样子"}, {"tag": "模仿", "text": "模仿一个机器人走路、说话"}, {"tag": "模仿", "text": "学风吹大树摇摆的样子"}, {"tag": "模仿", "text": "模仿大公鸡打鸣，叫醒全家"}, {"tag": "模仿", "text": "学企鹅走路，从这头摇到那头"}, {"tag": "模仿", "text": "模仿你最喜欢的一个动画角色说一句话"}, {"tag": "模仿", "text": "模仿超人飞起来的动作和表情"}, {"tag": "模仿", "text": "学一只小鸭子摇摇摆摆找妈妈"}, {"tag": "模仿", "text": "模仿超市收银员扫码结账的样子"}, {"tag": "模仿", "text": "学闹钟响、再装作被吵醒揉眼睛"}, {"tag": "模仿", "text": "模仿一位画家专心画画的样子"}, {"tag": "模仿", "text": "学猫咪舔爪子洗脸的样子"}, {"tag": "模仿", "text": "模仿厨师颠勺炒菜的动作"}, {"tag": "模仿", "text": "模仿一只猫头鹰转头观察四周"}, {"tag": "才艺", "text": "唱一首歌的副歌部分，唱几句就行"}, {"tag": "才艺", "text": "背一首古诗，或者你会的任何几句"}, {"tag": "才艺", "text": "说一个绕口令，慢一点也没关系"}, {"tag": "才艺", "text": "哼一段旋律，让大家猜是什么歌"}, {"tag": "才艺", "text": "用手比划一个简单的舞蹈动作"}, {"tag": "才艺", "text": "说出 5 个水果的名字，越快越好"}, {"tag": "才艺", "text": "从 1 数到 20，跳过所有带 3 的数字"}, {"tag": "才艺", "text": "用三种不同的语气说\"今天天气真好\""}, {"tag": "才艺", "text": "现场画一个简笔画太阳，加上笑脸"}, {"tag": "才艺", "text": "说三个你会的英文单词，并比出意思"}, {"tag": "才艺", "text": "用筷子敲杯子，敲出一段简单的节奏"}, {"tag": "才艺", "text": "即兴编两句押韵的话，逗大家笑"}, {"tag": "才艺", "text": "说出 5 种动物的叫声，连着来"}, {"tag": "才艺", "text": "倒着把自己的名字念一遍"}, {"tag": "才艺", "text": "用手影在墙上比一只小动物"}, {"tag": "才艺", "text": "一口气说出一周七天，不能停顿"}, {"tag": "才艺", "text": "清唱一句你最近常听的歌"}, {"tag": "搞怪", "text": "做一个最夸张的鬼脸，坚持 3 秒"}, {"tag": "搞怪", "text": "用最低沉的声音说一句\"早上好\""}, {"tag": "搞怪", "text": "装作正在吃一根超级酸的柠檬"}, {"tag": "搞怪", "text": "假装自己是一个超慢动作的人，走两步"}, {"tag": "搞怪", "text": "用鼻子哼出一段\"生日快乐\""}, {"tag": "搞怪", "text": "把舌头卷起来，做得到就赢，做不到就笑一个"}, {"tag": "搞怪", "text": "假装在打一个很长很长的喷嚏"}, {"tag": "搞怪", "text": "学一个打不开的瓶盖，使劲拧的表情"}, {"tag": "搞怪", "text": "用很骄傲的语气夸自己一句"}, {"tag": "搞怪", "text": "假装手机响了，接起来演一段无厘头通话"}, {"tag": "搞怪", "text": "用慢动作假装喝到一杯超甜的果汁"}, {"tag": "搞怪", "text": "做出\"被冰水浇到\"的夸张反应"}, {"tag": "搞怪", "text": "把脸憋成大花猫，逗笑身边的人"}, {"tag": "搞怪", "text": "假装自己是一台卡住的复读机"}, {"tag": "搞怪", "text": "用气泡音说一句\"我是外星人\""}, {"tag": "搞怪", "text": "假装在吹一个永远吹不大的泡泡"}, {"tag": "问答", "text": "说出 3 个红色的东西"}, {"tag": "问答", "text": "说出 3 种你最爱吃的菜"}, {"tag": "问答", "text": "说出 3 个动物的名字，不能重复"}, {"tag": "问答", "text": "说出你今天最开心的一件事"}, {"tag": "问答", "text": "说出 3 个圆形的东西"}, {"tag": "问答", "text": "说出家里你最喜欢的一个角落，为什么"}, {"tag": "问答", "text": "说出一个你长大想做的事"}, {"tag": "问答", "text": "说出 3 个可以在天上看到的东西"}, {"tag": "问答", "text": "说出你最喜欢的一个季节，理由说一句"}, {"tag": "问答", "text": "说出 3 个会发出声音的东西"}, {"tag": "问答", "text": "说出 3 种甜的食物"}, {"tag": "问答", "text": "说出 3 个家里电器的名字"}, {"tag": "问答", "text": "说出 3 个白色的东西"}, {"tag": "问答", "text": "说出你今天最想感谢的一个人"}, {"tag": "问答", "text": "说出 3 种交通工具，越多越好"}, {"tag": "问答", "text": "说出一件你小时候最爱玩的游戏"}, {"tag": "问答", "text": "说出 3 个绿色的东西"}, {"tag": "合作", "text": "给身边的人比一个心"}, {"tag": "合作", "text": "和身边的人击掌三次，喊\"加油\""}, {"tag": "合作", "text": "全家一起喊\"一二三，茄子\"，并摆个合影造型"}, {"tag": "合作", "text": "选一个人，真诚地夸 TA 一句优点"}, {"tag": "合作", "text": "和左手边的人玩一次石头剪刀布"}, {"tag": "合作", "text": "抱一抱身边的家人 3 秒钟"}, {"tag": "合作", "text": "和大家一起做同一个手势，比如点赞"}, {"tag": "合作", "text": "请一位家人和你一起学小鸭子走路"}, {"tag": "合作", "text": "对全家说一句感谢的话"}, {"tag": "合作", "text": "和身边的人背靠背站一会儿，看谁先笑"}, {"tag": "合作", "text": "和身边的人合作摆出一个字母的造型"}, {"tag": "合作", "text": "两人一组，背对背把一个气球夹住走两步"}, {"tag": "合作", "text": "和一位家人对视 5 秒，谁先笑谁认输"}, {"tag": "合作", "text": "邀请一位家人一起唱一句同一首歌"}, {"tag": "合作", "text": "和身边的人手拉手一起原地转一圈"}, {"tag": "合作", "text": "请大家轮流说一个对方的优点"}, {"tag": "动作", "text": "踮起脚尖走 5 步，像踩在棉花上"}, {"tag": "动作", "text": "把双手交叉抱住肩膀，原地扭一扭腰"}, {"tag": "动作", "text": "蹲下来再跳起来，连做 3 次"}, {"tag": "动作", "text": "学小青蛙蹲着跳 3 下"}, {"tag": "动作", "text": "把右手摸左耳、左手摸右鼻，再换过来"}, {"tag": "动作", "text": "挺直腰背贴墙站好，坚持 8 秒"}, {"tag": "动作", "text": "把一只袜子团成球，抛起来再接住"}, {"tag": "动作", "text": "原地小跑 10 步，越跑越轻越好"}, {"tag": "模仿", "text": "模仿小狗听到\"出去玩\"时兴奋的样子"}, {"tag": "模仿", "text": "学一只猫被挠下巴时眯眼睛的表情"}, {"tag": "模仿", "text": "模仿老爷爷拄着拐杖慢慢走路"}, {"tag": "模仿", "text": "模仿快递员敲门送件喊\"有人在家吗\""}, {"tag": "模仿", "text": "学一台洗衣机甩干衣服晃来晃去"}, {"tag": "模仿", "text": "模仿售货员热情地招呼客人"}, {"tag": "模仿", "text": "学一只小松鼠抱着松果啃的样子"}, {"tag": "才艺", "text": "用手指比出从 1 到 5，每个数配一个表情"}, {"tag": "才艺", "text": "把\"小星星\"这首歌哼出来，哼对就赢"}, {"tag": "才艺", "text": "说出 5 种颜色，每种再指一样身边的东西"}, {"tag": "才艺", "text": "用左手在空中画一个尽量圆的圆"}, {"tag": "才艺", "text": "一口气说出 5 个城市的名字"}, {"tag": "才艺", "text": "说一句话，每个字都用同一个声调"}, {"tag": "才艺", "text": "用拍手打出一段简单的节奏，让大家跟着拍"}, {"tag": "搞怪", "text": "假装自己是慢慢融化的雪人，慢慢蹲下去"}, {"tag": "搞怪", "text": "用很认真的表情说一句最普通的话，比如\"我要喝水\""}, {"tag": "搞怪", "text": "假装鼻子被夹住，捏着鼻子说三句话"}, {"tag": "搞怪", "text": "做出\"吃到超辣辣椒\"的夸张表情，再扇扇风"}, {"tag": "搞怪", "text": "假装自己是一只刚睡醒、伸懒腰的小猫"}, {"tag": "搞怪", "text": "用气声悄悄说一句\"嘘，有秘密\""}, {"tag": "问答", "text": "说出 3 种你会做的家务"}, {"tag": "问答", "text": "说出 3 个又圆又会滚的东西"}, {"tag": "问答", "text": "说出 3 样冰箱里常有的东西"}, {"tag": "问答", "text": "说出一个你最近学会的新本领"}, {"tag": "问答", "text": "说出 3 种天上会飞的东西"}, {"tag": "问答", "text": "说出你最喜欢和家人一起做的一件事"}, {"tag": "合作", "text": "和身边的人合作传递一个想象中的西瓜"}, {"tag": "合作", "text": "两人一起数到 10，一人一个数轮流报"}, {"tag": "合作", "text": "请一位家人和你一起摆个\"胜利\"的造型"}, {"tag": "合作", "text": "和大家一起做三次深呼吸，慢慢吸慢慢呼"}, {"tag": "合作", "text": "和一位家人合作，一人比动作一人猜是什么"}, {"tag": "合作", "text": "全家一起为今天点个赞，齐喊一声\"棒\""}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
