insert into public.game_content (game, data, updated_at) values ('know-you', $seed$[{"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "魂斗罗调 30 条命的秘籍是什么？", "emoji": "🎮", "answer": "标题画面输入\"上上下下左右左右BABA\"再按开始"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "\"上上下下左右左右BABA\"其实是哪家游戏公司的通用秘籍？", "emoji": "🕹️", "answer": "科乐美(Konami),《沙罗曼蛇》时期就有,叫\"科乐美秘籍\""}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "小霸王学习机的代言人是谁？广告词是什么?", "emoji": "🐉", "answer": "成龙,\"同是天下父母心,望子成龙小霸王\""}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "\"小霸王其乐无穷啊\"这句开机语是谁配的音？", "emoji": "📢", "answer": "疯狂英语创始人李阳"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "游戏卡带读不出来时,80 后的\"祖传维修法\"是什么？", "emoji": "💨", "answer": "拔下来对着金手指吹气(或用橡皮擦触点)"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "当年买游戏卡带最划算的是什么卡？", "emoji": "💾", "answer": "\"几十合一\"\"上百合一\"的合集卡"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "小霸王学习机键盘上印的是什么字根？", "emoji": "⌨️", "answer": "五笔字根"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "超级玛丽里的马里奥最早是什么职业？", "emoji": "🔨", "answer": "木匠(1981 年《大金刚》登场),1983 年才改行当水管工"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "马里奥的全名是什么？", "emoji": "🍄", "answer": "Mario Mario(马里奥·马里奥)"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "马里奥骑的耀西官方设定是什么动物？", "emoji": "🐢", "answer": "乌龟一族(背上那是龟壳),不是恐龙"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "史上最畅销的电子游戏是超级玛丽还是俄罗斯方块？", "emoji": "🧱", "answer": "俄罗斯方块,累计超 1.5 亿份"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "《四驱兄弟》里星马豪的赛车叫什么名字？", "emoji": "🏎️", "answer": "旋风冲锋"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "当年国产四驱车最大的牌子是什么？广告词?", "emoji": "💎", "answer": "奥迪双钻,\"奥迪双钻,我的伙伴\""}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "让悠悠球火遍全国的国产动画叫什么？", "emoji": "🪀", "answer": "《火力少年王》"}, {"tag": "童年玩具", "kind": "trivia", "role": "dad", "text": "小浣熊干脆面的水浒卡一共多少张？", "emoji": "🃏", "answer": "108 张好汉卡 + 6 张恶人卡"}, {"tag": "