ood"}, {"name": "自热火锅（中份一盒）", "note": "电商常见价，倒一杯凉水就能「无火自熟」，靠的是发热包遇水放热的化学反应", "unit": "一盒", "price": 19, "category": "food"}, {"name": "珠海长隆海洋王国门票（平日成人一张）", "note": "官方平日价，鲸鲨馆是全球最大的水族馆之一，特定日票价涨到 450 元", "unit": "一张", "price": 395, "category": "ticket"}, {"name": "北京动物园门票（旺季成人一张）", "note": "官方旺季价，加 4 元就能看大熊猫，可能是性价比最高的「遛娃胜地」", "unit": "一张", "price": 15, "category": "ticket"}, {"name": "尤尼克斯比赛羽毛球（一筒 12 只）", "note": "两年价格翻倍，鸭鹅出栏减少让羽毛球「涨价比黄金还猛」，中产直呼打不起", "unit": "一筒", "price": 190, "category": "ticket"}, {"name": "牧高笛自动帐篷（入门款一顶）", "note": "电商常见价，「公园露营」标配，一抛一撑就成型，野餐党的快乐小屋", "unit": "一顶", "price": 299, "category": "ticket"}, {"name": "比亚迪海鸥（入门版一辆）", "note": "2025 款起售价 6.98 万，「年轻人的第一辆电车」，把代步车价格打到了新低", "unit": "一辆", "price": 69800, "category": "big"}, {"name": "美的 1.5 匹一级能效空调（挂机一台）", "note": "电商常见价，夏天的「续命神器」，赶上以旧换新国补还能再省一笔", "unit": "一台", "price": 2299, "category": "big"}, {"name": "五粮液第八代普五（52 度 500ml 一瓶）", "note": "2026 年初市场价，和飞天茅台并称白酒「茅五」，逢年过节的餐桌「硬通货」", "unit": "一瓶", "price": 830, "category": "big"}, {"name": "雅马哈 P 系列电钢琴（入门款一台）", "note": "电商常见价，88 键带配重，比真钢琴便宜十倍，初学者的「平替练习神器」", "unit": "一台", "price": 2601, "category": "big"}, {"name": "维他柠檬茶（250ml*24 盒一箱）", "note": "电商常见价，平均一盒不到 2 元，「锡纸包+小吸管」是不少人的下午茶记忆", "unit": "一箱", "price": 45, "category": "snack"}, {"name": "康师傅冰红茶（1L 大瓶一瓶）", "note": "超市常见价，告别「4 元时代」涨到 4.5-5 元，曾经夏天解渴的「快乐源泉」", "unit": "一瓶", "price": 4.5, "category": "snack"}, {"name": "钟薛高临期雪糕（电商一支）", "note": "曾经一支卖到 60 元的「雪糕刺客」，倒下后临期货低至 5 元，沦为「雪糕显眼包」", "unit": "一支", "price": 5, "category": "snack"}, {"name": "奈雪的茶·霸气芝士葡萄（中杯一杯）", "note": "门店参考价，奈雪全线告别「30 元时代」，鲜果茶里能喝到大颗去皮葡萄", "unit": "一杯", "price": 21, "category": "snack"}, {"name": "书亦烧仙草（大杯一杯）", "note": "门店常见价，「半杯都是料」的招牌，里面塞满仙草冻、珍珠、红豆、花生", "unit": "一杯", "price": 13, "category": "snack"}, {"name": "蒙牛纯甄常温酸奶（200g×10 盒一箱）", "note": "超市常见价，平均一盒 5 块多，常温酸奶不用冷藏，是走亲访友的「箱装担当」", "unit": "一箱", "price": 52, "category": "snack"}, {"name": "胖东来网红大月饼（散装一个）", "note": "官方售价 29.8 元，中秋前被黄牛炒到 119 元、代购加价到 80 元，一饼难求", "unit": "一个", "price": 29.8, "category": "snack"}, {"name": "名创优品 Chiikawa 联名毛绒玩偶（中号一只）", "note": "门店常见价，上架三天卖出 800 万元，「吉伊卡哇」三人组让大人小孩一起上头", "unit": "一只", "price": 40, "category": "toy"}, {"name": "万代 RG 高达拼装模型（普通款一盒）", "note": "电商常见价，1/144 比例上百个零件，拼一只能耗掉一下午，「拼乐高的进阶版」", "unit": "一盒", "price": 199, "category": "toy"}, {"name": "任天堂《塞尔达传说·王国之泪》游戏卡带（一张）", "note": "电商百亿补贴价，国行未发售，海外神作的「一张小卡片」抵得上半台红米手机", "unit": "一张", "price": 337, "category": "toy"}, {"name": "小米平板 7（8+128G 一台）", "note": "官方售价，11.2 英寸高刷大屏，赶上国补能压到一千多元，学生党的「网课平替」", "unit": "一台", "price": 2299, "category": "digital"}, {"name": "Apple Watch Series 11 国行（GPS 款一只）", "note": "2025 年 9 月发布起售价，新增高血压提示和睡眠评分，手腕上的「健康小管家」", "unit": "一只", "price": 2999, "category": "digital"}, {"name": "vivo X Fold5 折叠屏手机（12+256G 一台）", "note": "2025 年发布起售价，展开是平板合起是手机，一台顶得上一台标准版 iPhone 加一半", "unit": "一台", "price": 6999, "category": "digital"}, {"name": "二手 Kindle Paperwhite 电子书阅读器（老款一台）", "note": "亚马逊书城关停后二手价跳水，曾经的「盖泡面神器」如今几百元满地都是", "unit": "一台", "price": 250, "category": "digital"}, {"name": "影石 Insta360 X4 全景运动相机（标准版一台）", "note": "电商常见价，8K 全景拍摄+「隐形自拍杆」，能拍出「无人机视角」的运动神器", "unit": "一台", "price": 2113, "category": "digital"}, {"name": "彩棠三色高光修容盘（2.0 版一盘）", "note": "官方价，珀莱雅旗下国货彩妆爆款，一盘年销 50 万+，化妆「修脸」靠它", "unit": "一盘", "price": 179, "category": "beauty"}, {"name": "蜂花柔顺护发素（1L 大瓶一瓶）", "note": "电商常见价，几十年不涨价的国货「老实人」，曾因「土包装」意外爆火出圈", "unit": "一瓶", "price": 20, "category": "beauty"}, {"name": "巴沙鱼柳（冷冻一斤）", "note": "超市常见价，没刺好嚼，酸菜鱼、烤鱼店里多半用的就是它，平价水产「顶流」", "unit": "一斤", "price": 10, "category": "daily"}, {"name": "海南香蕉（一斤）", "note": "菜市场常见价，2025 年「水果普跌、香蕉独涨」上过热搜，运动后补能量的好搭档", "unit": "一斤", "price": 3, "category": "daily"}, {"name": "清风原木抽纸（3 层 20 包一箱）", "note": "电商常见价，平均一包一块五，家里「永远在用又永远要囤」的隐形消耗品", "unit": "一箱", "price": 30, "category": "daily"}, {"name": "塔斯汀·香辣鸡腿堡（券后一个）", "note": "门店优惠价，主打「现烤堡胚」的中式汉堡，靠低价开出近万家店冲击「汉堡之王」", "unit": "一个", "price": 8.9, "category": "food"}, {"name": "杨国福麻辣烫（自选称重吃一顿）", "note": "人均常见价，论斤称重的鼻祖，「想吃啥夹啥」的快乐，吃饱一顿其实越来越贵", "unit": "人均", "price": 25, "category": "food"}, {"name": "绝味鸭脖招牌鸭脖（一斤）", "note": "门店常见价，追剧「啃手」必备，被吐槽「钱包刺客」后年轻人直呼「少抓点」", "unit": "一斤", "price": 48, "category": "food"}, {"name": "海底捞自助小料（一位）", "note": "门店常见价，从 9 元涨到过 11 元，蘸料台能 DIY 出「全网最好吃」的灵魂蘸碟", "unit": "一位", "price": 9, "category": "food"}, {"name": "迪卡侬室外篮球（7 号一个）", "note": "电商常见价，平价运动品牌的耐磨款，球场「人手一个」的性价比之选", "unit": "一个", "price": 150, "category": "ticket"}, {"name": "三亚双飞 5 日跟团游（一人）", "note": "旺季纯玩团常见报价，含往返机票+酒店+景点，挑团要认准「0 购物 0 自费」", "unit": "一人", "price": 2500, "category": "ticket"}, {"name": "《原神》最大档充值（648 元一单）", "note": "游戏内最高充值档，「648」已成手游氪金代名词，约能换 40 多次「抽卡」", "unit": "一单", "price": 648, "category": "ticket"}, {"name": "宇树科技 Unitree G1 人形机器人（一台）", "note": "国内官方售价 9.9 万元起，身高约 1.27 米能跑能跳，国产人形机器人「卷王」", "unit": "一台", "price": 99000, "category": "big"}, {"name": "理想 L6（入门版一辆）", "note": "2025 年起售价 24.98 万，连续多月坐稳中大型 SUV 销量冠军，「家庭奶爸车」代表", "unit": "一辆", "price": 249800, "category": "big"}, {"name": "《哪吒之魔童闹海》全球总票房", "note": "约 154.46 亿元，2025 年全球票房冠军、全球影史第 5，一部动画电影=22 架 C919", "unit": "总票房", "price": 15446000000, "category": "big"}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
