 "螺丝帽", "title": "脑筋急转弯", "prompt": "什么「帽」永远戴不到头上？", "wrongs": ["草帽", "安全帽"]}, {"why": "把 8 横过来，就成了数学里的无穷大符号 ∞。", "right": "无穷大（∞）", "title": "脑筋急转弯", "prompt": "数字 8 一躺下，就变成了什么？", "wrongs": ["数字 0", "一副眼镜"]}, {"why": "爆竹是用来过年放的，可不是从地里长出来的。", "right": "爆竹", "title": "脑筋急转弯", "prompt": "什么「竹」不长在土里？", "wrongs": ["毛竹", "竹笋"]}, {"why": "没下雨，自然谁也淋不湿——别被「撑伞」带跑了。", "right": "因为当时根本没下雨", "title": "脑筋急转弯", "prompt": "三个人合撑一把小伞走在街上，为什么衣服都没淋湿？", "wrongs": ["伞特别大", "他们跑得特别快"]}, {"why": "「破纪录」是好事，比如跑出了更快的成绩。", "right": "纪录", "title": "脑筋急转弯", "prompt": "什么东西破了，大家不但不心疼，反而都很高兴？", "wrongs": ["气球", "存钱罐"]}, {"why": "「脸蛋」是脸，当然打不烂也不能吃。", "right": "脸蛋", "title": "脑筋急转弯", "prompt": "什么「蛋」打不烂、煮不熟，也不能吃？", "wrongs": ["鸡蛋", "鸭蛋"]}, {"why": "闪电和雷声几乎同时产生，只是光速远快于声速，所以闪电先到眼睛。", "right": "光跑得比声音快得多", "title": "冷知识", "prompt": "这是为什么？", "wrongs": ["闪电先发生、打雷后发生", "耳朵反应比眼睛慢"], "scenario": "打雷下雨时，我们总是先看到闪电，过一会儿才听到雷声。"}, {"why": "舌头颜色深是因为色素多，能像防晒霜一样挡住强烈的阳光。", "right": "偏蓝紫的深色", "title": "冷知识", "prompt": "它的舌头大多是什么颜色？", "wrongs": ["粉红色", "草绿色"], "scenario": "长颈鹿要伸长舌头去够高处带刺的树叶，一够就是大半天。"}, {"why": "右手没法去拿右手自己——别的都拿得到。", "right": "你自己的右手", "title": "脑筋急转弯", "prompt": "什么东西，你的右手永远拿不到？", "wrongs": ["你的左手", "你的影子"]}, {"why": "梯子有十米高，可他站的是最底下一级，根本没多高。", "right": "他是从最低那一级摔下来的", "title": "脑筋急转弯", "prompt": "一个人从十米高的梯子上摔下来，却一点儿没受伤，怎么回事？", "wrongs": ["他穿了护具", "下面有水"]}, {"why": "足球场上的球门是敞开的，本来就不用关。", "right": "球门", "title": "脑筋急转弯", "prompt": "什么门，永远也关不上？", "wrongs": ["防盗门", "玻璃门"]}, {"why": "立交桥架在马路上，桥下是车流，不是河水。", "right": "立交桥", "title": "脑筋急转弯", "prompt": "什么桥的下面，一滴水都没有？", "wrongs": ["石拱桥", "独木桥"]}, {"why": "不先睁眼，怎么知道天亮了——这就是醒来的第一件事。", "right": "睁开眼睛", "title": "脑筋急转弯", "prompt": "每天早上一睁眼，所有人都要做的第一件事是什么？", "wrongs": ["刷牙", "伸懒腰"]}, {"why": "名字是你的，可叫你名字的几乎都是别人。", "right": "你的名字", "title": "脑筋急转弯", "prompt": "有样东西是你的，可别人用它的次数比你还多，是什么？", "wrongs": ["你的牙刷", "你的书包"]}, {"why": "橡皮越擦越短，用到最后就只剩一点点。", "right": "橡皮", "title": "脑筋急转弯", "prompt": "什么东西越用越小，最后干脆没了？", "wrongs": ["尺子", "铅笔盒"]}, {"why": "0 怎么转都是 0，而 6 倒过来会变成 9。", "right": "0", "title": "脑筋急转弯", "prompt": "哪个数字，上下倒过来看还是它本身？", "wrongs": ["6", "7"]}, {"why": "蚊子刚吸完你的血，一拍，流的当然是你的血。", "right": "蚊子", "title": "脑筋急转弯", "prompt": "什么小动物，你把它拍死了，流出来的却是你自己的血？", "wrongs": ["苍蝇", "蚂蚁"]}, {"why": "指南针是用来辨方向的，可不是拿来缝东西的。", "right": "指南针", "title": "脑筋急转弯", "prompt": "什么「针」，缝不了一件衣服？", "wrongs": ["缝衣针", "别针"]}, {"why": "把「错」字写出来，写的正是「错」——这是个文字游戏。", "right": "「错」字", "title": "脑筋急转弯", "prompt": "有一个字，几乎人人都会把它写「错」，是哪个字？", "wrongs": ["「难」字", "「写」字"]}, {"why": "未来还没到，谁也看不见，可它就在前方等着你。", "right": "未来", "title": "脑筋急转弯", "prompt": "什么东西明明就在你眼前，你却怎么也看不见？", "wrongs": ["空气", "玻璃"]}, {"why": "钟摆在原地，指针却一直在「走」，我们也常说「钟走得准」。", "right": "钟表", "title": "脑筋急转弯", "prompt": "什么东西自己不动，却能日夜不停地「走」？", "wrongs": ["汽车", "河水"]}, {"why": "婴儿约有近 300 块骨头，长大后许多块慢慢融合，最后定在 206 块。", "right": "206 块", "title": "冷知识", "prompt": "成年人全身大约有多少块骨头？", "wrongs": ["300 块", "100 块"], "scenario": "小宝宝刚出生时，身上的骨头数量其实比大人还多。"}, {"why": "虾的心脏其实在靠近头的位置，被坚硬的头胸甲保护着。", "right": "头部附近", "title": "冷知识", "prompt": "虾的心脏长在身体的哪个部位？", "wrongs": ["尾巴里", "肚子中间"], "scenario": "虾的身体被硬硬的壳包着，心脏藏得让人想不到。"}, {"why": "我们常说「瓶颈」，瓶子有脖子（瓶颈），可没有头。", "right": "瓶子", "title": "脑筋急转弯", "prompt": "什么东西有脖子，却偏偏没有头？", "wrongs": ["长颈鹿", "围巾"]}, {"why": "邮票贴在信封一角，随信寄到天南海北，可它从没离开那个角。", "right": "邮票", "title": "脑筋急转弯", "prompt": "什么东西能跟着信封环游世界，自己却一直待在角落里？", "wrongs": ["指南针", "小蜗牛"]}, {"why": "梳子那一排「齿」就是它的牙，可它只会梳头，不会吃东西。", "right": "梳子", "title": "脑筋急转弯", "prompt": "什么东西满嘴是「牙」，却一口饭也吃不了？", "wrongs": ["锯子", "拉链"]}, {"why": "钢琴的「键」是琴键，用来弹曲子，可不是开锁的钥匙。", "right": "钢琴", "title": "脑筋急转弯", "prompt": "什么东西有好多「键」，却一把锁也打不开？", "wrongs": ["电脑", "保险箱"]}, {"why": "土挖得越多，坑就越大——别的东西挖了只会越来越小。", "right": "坑（洞）", "title": "脑筋急转弯", "prompt": "什么东西，你越往外挖，它反而越大？", "wrongs": ["宝藏", "蛋糕"]}, {"why": "海绵满是小孔，水却能被吸进这些孔里牢牢存住。", "right": "海绵", "title": "脑筋急转弯", "prompt": "什么东西浑身是洞，却照样装得住水？", "wrongs": ["筛子", "渔网"]}, {"why": "「瀑布」是飞流直下的水，哪是剪刀剪得断的——这是个谐音游戏。", "right": "瀑布", "title": "脑筋急转弯", "prompt": "什么「布」，再锋利的剪刀也剪不断？", "wrongs": ["桌布", "抹布"]}, {"why": "年龄一年比一年大，只增不减——掉下来的可不是它。", "right": "年龄", "title": "脑筋急转弯", "prompt": "什么东西只会一个劲往上长，却从来不会往下掉？", "wrongs": ["气球", "风筝"]}, {"why": "「扒手」就是偷东西的小偷，名字里带手，可一点都不老实。", "right": "扒手", "title": "脑筋急转弯", "prompt": "什么「手」最不老实，专门去拿别人的东西？", "wrongs": ["歌手", "助手"]}, {"why": "蜗牛名字带牛，却驮着壳「房子」爬，吃的也不是草。", "right": "蜗牛", "title": "脑筋急转弯", "prompt": "什么「牛」从来不吃草，还背着房子慢慢走？", "wrongs": ["水牛", "牦牛"]}, {"why": "「自食其后果」——后果可不是水果，是做错事要承担的结果。", "right": "后果", "title": "脑筋急转弯", "prompt": "什么「果」，谁也不敢吃，吃了还可能要负责？", "wrongs": ["芒果", "腰果"]}, {"why": "流星根本不是星星，而是太空里的小碎石高速冲进大气层，摩擦生热烧出来的亮光。", "right": "太空小石块冲进大气层烧了起来", "title": "冷知识", "prompt": "这道光其实是什么在发亮？", "wrongs": ["一颗星星掉了下来", "飞机的尾灯"], "scenario": "夜里偶尔能看到一道亮光「唰」地划过天空，大家都叫它流星。"}, {"why": "它叫镫骨，长在耳朵深处，只有几毫米长，帮我们把声音的震动传进去。", "right": "耳朵里", "title": "冷知识", "prompt": "这块最小的骨头长在哪里？", "wrongs": ["小拇指尖", "鼻子里"], "scenario": "人全身最小的一块骨头，藏在一个想不到的地方。"}, {"why": "切开洋葱会放出一种气体，飘到眼睛里和泪水反应生成微量刺激物，眼睛便赶紧多流泪把它冲走。", "right": "洋葱放出的气体遇到眼泪变成了刺激性物质", "title": "冷知识", "prompt": "这是为什么？", "wrongs": ["洋葱里藏着辣椒粉", "是被洋葱的味道熏哭的"], "scenario": "切洋葱的时候，常常切着切着就忍不住流眼泪。"}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
insert into public.game_content (game, data, updated_at) values ('yiyi-truefalse', $seed$[{"why": "真的：两颗给鳃供血，一颗负责全身血液循环。", "fact": "章鱼有三颗心脏。", "joke": "只有星期三才跳", "real": true}, {"why": "真的：蜂蜜含水极少又偏酸，细菌很难存活。", "fact": "蜂蜜保存得当，放很多年也几乎不会坏。", "joke": "只有放冰箱才不会坏", "real": true}, {"why": "真的：哺乳动物大多 7 块，长颈鹿只是每块特别长。", "fact": "长颈鹿和人脖子里都是 7 块颈椎骨。", "joke": "长颈鹿有 70 块", "real": true}, {"why": "真的：闪电可达上万摄氏度，比太阳表面还烫。", "fact": "闪电那一瞬间的温度，比太阳表面还高。", "joke": "和洗澡水差不多", "real": true}, {"why": "真的：黑皮肤更吸热，毛是半透明的中空管，看起来才发白。", "fact": "北极熊的皮肤其实是黑色的。", "joke": "北极熊是透明的隐形熊", "real": true}, {"why": "真的：鲨鱼已经在海里游了好几亿年，比树还古老。", "fact": "鲨鱼比地球上第一棵树出现得还早。", "joke": "鲨鱼是上个月才进化出来的", "real": true}, {"why": "真的：鸵鸟眼睛大得惊人，脑子反而小小一颗。", "fact": "鸵鸟的眼睛比它的大脑还大。", "joke": "鸵鸟根本没长眼睛", "real": true}, {"why": "真的：按植物学定义香蕉是浆果，而草莓反倒不是。", "fact": "香蕉在植物学上其实算一种浆果。", "joke": "香蕉其实是蔬菜", "real": true}, {"why": "真的：左边要给心脏让地方，所以左肺小一些。", "fact": "人的左肺比右肺小一点。", "joke": "人只有一个肺", "real": true}, {"why": "真的：蓝鲸的体重超过已知任何恐龙。", "fact": "蓝鲸是地球上出现过的最大动物，比恐龙还大。", "joke": "蓝鲸和金鱼差不多大", "real": true}, {"why": "真的：没有空气传声，宇航员只能靠无线电对讲。", "fact": "月球上是真空，面对面大喊也听不见。", "joke": "月球上回声特别响", "real": true}, {"why": "真的：企鹅是鸟类，翅膀进化成了划水的鳍。", "fact": "企鹅是鸟，可它一辈子都不会飞。", "joke": "企鹅能飞越南极", "real": true}, {"why": "真的：土星的平均密度比水还小。", "fact": "土星太轻了，理论上能浮在一大盆水上。", "joke": "土星比铁球还沉", "real": true}, {"why": "真的：海星靠分布在全身的神经网络活动，没有大脑。", "fact": "海星没有大脑。", "joke": "海星有五个大脑", "real": true}, {"why": "真的：条纹连皮肤都印着，不只是长在毛上。", "fact": "老虎剃光毛之后，皮肤上也有条纹。", "joke": "条纹是饲养员画上去的", "real": true}, {"why": "假的：研究发现金鱼能记住事情好几个月。", "fact": "金鱼的记忆只有三秒。", "joke": "夏天三秒、冬天五秒", "real": false}, {"why": "假的：心跳并不会因为打喷嚏而停止。", "fact": "人打喷嚏的时候，心脏会停跳一下。", "joke": "会停整整一分钟", "real": false}, {"why": "假的：这是流传很广的误传，肉眼其实很难看清长城。", "fact": "在太空里用肉眼能看到的人造建筑，只有长城。", "joke": "还能看到学校操场", "real": false}, {"why": "假的：这是误传，它只是低头察看或翻动鸟蛋。", "fact": "鸵鸟一害怕就把头埋进沙子里。", "joke": "它会把全身都埋起来", "real": false}, {"why": "假的：这早被辟谣，大脑各区域都在工作。", "fact": "人一辈子只用了大脑的 10%。", "joke": "只用了 1%", "real": false}, {"why": "假的：驼峰里装的是脂肪，可不是一袋水。", "fact": "骆驼的驼峰里装的是水。", "joke": "装的是沙子", "real": false}, {"why": "假的：一年地球只绕太阳转 1 圈，约 365 天。", "fact": "地球一年绕着太阳转 365 圈。", "joke": "一年转 12 圈", "real": false}, {"why": "真的：金星浓厚的大气像被子一样锁住热量，表面比水星还烫。", "fact": "太阳系里最热的行星是金星，不是离太阳最近的水星。", "joke": "最热的是地球", "real": true}, {"why": "真的：在太空里看太阳是白的，是地球大气散射才让它看着偏黄。", "fact": "太阳本身的颜色其实是白色的。", "joke": "太阳是绿色的", "real": true}, {"why": "真的：猫的舌头缺少感受甜味的味觉受体，吃糖也尝不出甜。", "fact": "猫尝不出甜味。", "joke": "猫只爱吃甜的", "real": true}, {"why": "真的：蜂鸟是唯一能稳定向后飞行的鸟。", "fact": "蜂鸟能像直升机一样倒着往后飞。", "joke": "所有的鸟都能倒着飞", "real": true}, {"why": "真的：古代胡萝卜多为紫色或黄色，橙色是后来才培育出来的。", "fact": "胡萝卜最早其实是紫色的，不是橙色。", "joke": "胡萝卜原来是蓝色的", "real": true}, {"why": "真的：它的肠道结构特殊，能把便便挤成方块，还不容易滚走。", "fact": "袋熊拉出来的便便是方块形的。", "joke": "袋熊的便便是三角形的", "real": true}, {"why": "真的：水中声速约为空气里的四倍多。", "fact": "声音在水里传得比在空气里更快。", "joke": "声音在水里根本传不动", "real": true}, {"why": "真的：蝴蝶脚上有味觉感受器，落在植物上就能尝出能不能吃。", "fact": "蝴蝶是用脚来「尝味道」的。", "joke": "蝴蝶用翅膀尝味道", "real": true}, {"why": "假的：恰恰相反，金星自转极慢，它的一天比一年还长。", "fact": "在金星上，一天比一年还短。", "joke": "金星上没有白天", "real": false}, {"why": "假的：高塔、大楼常被反复击中，比如帝国大厦每年都被劈很多次。", "fact": "闪电从不会两次击中同一个地方。", "joke": "闪电只往新地方劈", "real": false}, {"why": "假的：花生长在地下，属于豆科，和豌豆、黄豆是亲戚，不是坚果。", "fact": "花生其实是一种坚果。", "joke": "花生其实是水果", "real": false}, {"why": "假的：牛分辨不出红色，惹它的是斗牛士挥动的布在晃动。", "fact": "公牛看到红色就会被激怒、冲过去。", "joke": "公牛最怕粉红色", "real": false}, {"why": "假的：「味觉地图」是误传，整条舌头各种味道都能尝到。", "fact": "舌头尖只能尝甜、舌根只能尝苦，分区明确。", "joke": "只有左半边舌头管尝味道", "real": false}, {"why": "假的：蝙蝠并不瞎，它在黑暗里靠超声波回声定位，眼睛也能看。", "fact": "蝙蝠是瞎子，什么都看不见。", "joke": "蝙蝠有八只眼睛", "real": false}, {"why": "假的：它们并没有变长，是皮肤干缩后显得头发指甲更长了。", "fact": "人去世以后，头发和指甲还会继续生长。", "joke": "会一直长到天花板", "real": false}, {"why": "假的：它变色更多是为了调节体温和表达情绪，伪装只是次要。", "fact": "变色龙变色主要是为了融入背景、把自己藏起来。", "joke": "它变色是为了赶时髦", "real": false}, {"why": "真的：胃酸主要是盐酸，酸性很强，连金属都能被它腐蚀。", "fact": "人胃里的胃酸，浓到能慢慢腐蚀掉铁钉。", "joke": "胃酸其实是甜的，像汽水", "real": true}, {"why": "真的：水结冰时体积膨胀约 9%，密度变小，冰才浮得起来。", "fact": "水结成冰以后会变大、变轻，所以冰能浮在水面上。", "joke": "冰其实比水重，会沉到水底", "real": true}, {"why": "真的：它一大半藏在海里，从海底算起总高度超过珠峰。", "fact": "从海底量到山顶，夏威夷的冒纳凯阿火山比珠穆朗玛峰还高。", "joke": "世界最高的山其实是富士山", "real": true}, {"why": "真的：金字塔建成约在公元前 2560 年，比她早 2500 多年；而登月离她只 2000 年。", "fact": "埃及艳后生活的年代，离登月比离金字塔建成更近。", "joke": "埃及艳后亲眼看过金字塔开工", "real": true}, {"why": "真的：牛津早在 1096 年就有教学，比阿兹特克建都早了两百多年。", "fact": "英国牛津大学比美洲的阿兹特克帝国还要古老。", "joke": "牛津大学是上个世纪才建的", "real": true}, {"why": "真的：两者都是纯碳，只是原子排列方式不同，软硬就天差地别。", "fact": "钻石和铅笔芯，其实都是由同一种元素「碳」组成的。", "joke": "钻石是由金子变来的", "real": true}, {"why": "真的：香蕉富含钾，其中钾-40 有微弱放射性，但量极小、对人无害。", "fact": "香蕉本身带有一点点天然放射性。", "joke": "吃香蕉会在黑暗里发光", "real": true}, {"why": "真的：澳大利亚东西约 4000 公里，月球直径约 3474 公里。", "fact": "澳大利亚东西最宽处，比月亮的直径还要宽。", "joke": "澳大利亚比整个太阳还大", "real": true}, {"why": "真的：树懒新陈代谢极慢，一片叶子要消化好多天，是哺乳动物里最慢的。", "fact": "树懒消化一顿饭，可能要花上好几个星期。", "joke": "树懒吃完一秒就消化完了", "real": true}, {"why": "真的：声音在氦气里传得更快，改变了喉咙的共鸣，音色就变尖了。", "fact": "吸一口氦气球里的气体说话，声音会变得又尖又细。", "joke": "氦气会把你的舌头冻住", "real": true}, {"why": "假的：血一直都是红的，静脉看起来发蓝只是皮肤对光的折射造成的错觉。", "fact": "人身体里的血，在血管里其实是蓝色的。", "joke": "生气的时候血会变绿", "real": false}, {"why": "假的：除了这五种，人还有平衡感、本体感觉（闭眼也知道手在哪）等好多种。", "fact": "人只有五种感觉：视、听、嗅、味、触。", "joke": "人其实只有一种感觉", "real": false}, {"why": "假的：多项研究都没发现掰指关节会增加关节炎风险，响声只是关节里的气泡爆开。", "fact": "老掰手指关节「咔咔」响，以后会得关节炎。", "joke": "掰多了手指会变长", "real": false}, {"why": "假的：没有任何科学证据支持，这只是流传很久的误传。", "fact": "刚吃完饭马上下水游泳，会抽筋淹死，必须等很久。", "joke": "吃完饭游泳会让水变咸", "real": false}, {"why": "假的：刮毛只是把毛切平，断面摸着扎手，颜色粗细其实没变。", "fact": "汗毛或胡子刮掉以后，会长得更粗、更黑。", "joke": "刮一次就再也长不出来了", "real": false}, {"why": "假的：「十倍」是老说法，新研究发现细菌和人体细胞数量其实差不多，约一比一。", "fact": "人身上的细菌数量，是自身细胞的整整十倍。", "joke": "人身上一个细菌都没有", "real": false}, {"why": "假的：这是网上编出来的假消息，从没有真实记录，蜘蛛根本不会主动爬进嘴里。", "fact": "人每年睡觉时，会不知不觉吞下大约 8 只蜘蛛。", "joke": "吞下的其实是 80 只", "real": false}, {"why": "假的：多项研究都没找到糖让孩子更亢奋的证据，多半是大人的心理作用。", "fact": "小孩吃了糖就会变得特别亢奋、坐不住。", "joke": "吃糖会让人原地跳起来", "real": false}, {"why": "假的：狗能看到蓝色和黄色，只是分不清红和绿，并非只有黑白。", "fact": "狗的眼睛里只有黑白两色，看不到任何颜色。", "joke": "狗只能看见紫色", "real": false}, {"why": "假的：口香糖虽然不被消化，但会跟着其他食物在几天内正常排出体外。", "fact": "不小心咽下去的口香糖，会在肚子里待整整七年。", "joke": "咽下去会粘住整个胃", "real": false}, {"why": "真的：沙漠按「降水极少」来算，南极几乎不下雨雪，面积比撒哈拉还大。", "fact": "世界上最大的沙漠不是撒哈拉，而是南极洲。", "joke": "最大的沙漠其实在月球上", "real": true}, {"why": "真的：海沟最深约 11000 米，比珠峰还高出 2000 多米。", "fact": "把珠穆朗玛峰整座搬进马里亚纳海沟，山顶上方还能再盖一英里深的海水。", "joke": "海沟其实只有游泳池那么深", "real": true}, {"why": "真的：蟑螂靠身体两侧的小孔呼吸，神经也分散在全身，没头照样能动好几天。", "fact": "蟑螂被砍掉头以后，还能活上大约一个星期。", "joke": "蟑螂掉了头会立刻长出新的", "real": true}, {"why": "真的：冥王星绕太阳一圈要约 248 年，要等到 2178 年才转满第一圈。", "fact": "冥王星从 1930 年被发现到现在，还没绕太阳转完一整圈。", "joke": "冥王星一天就能绕太阳一圈", "real": true}, {"why": "真的：木星个头最大，转得却最快，不到 10 小时就自转一周。", "fact": "木星是太阳系里「一天」最短的行星，自转一圈才约 10 小时。", "joke": "木星转一圈要一百年", "real": true}, {"why": "真的：章鱼血里靠含铜的血蓝蛋白运氧，遇氧就显蓝色，跟我们的红血不一样。", "fact": "章鱼的血是蓝色的。", "joke": "章鱼的血是透明的", "real": true}, {"why": "真的：蜗牛舌头上有一条叫齿舌的带子，密密麻麻排着上万颗微小的牙。", "fact": "小小的蜗牛，嘴里其实长着上千颗细密的牙齿。", "joke": "蜗牛一颗牙都没有，靠吸的", "real": true}, {"why": "真的：霸王龙距今约 6600 万年，距剑龙却隔了 8000 多万年，剑龙对它来说才是「老古董」。", "fact": "霸王龙生活的年代，离我们人类比离剑龙还要近。", "joke": "霸王龙和剑龙天天一起玩", "real": true}, {"why": "真的：俄罗斯东西特别长，最东边天亮时，最西边还在深夜。", "fact": "俄罗斯一个国家，横跨了整整 11 个时区。", "joke": "俄罗斯全国共用一个钟点", "real": true}, {"why": "真的：它爱吃的小虾和藻类含有类胡萝卜素，色素沉积到羽毛上，就慢慢变粉了；刚出生时它是灰色的。", "fact": "火烈鸟身上那身粉红色，其实是「吃」出来的。", "joke": "火烈鸟是被夕阳染红的", "real": true}, {"why": "假的：他身高放在当时其实属于中等，「矮」多半来自漫画丑化和英法度量单位换算的误会。", "fact": "拿破仑个子矮得出奇，是出了名的小矮个。", "joke": "他矮得要踩凳子才够得着桌子", "real": false}, {"why": "假的：舌头其实是八块肌肉拼在一起的，所以它才能灵活地卷、伸、顶。", "fact": "人的舌头是一整块大肌肉。", "joke": "舌头里还藏着一根小骨头", "real": false}, {"why": "假的：按植物学定义西红柿是果实，甚至算浆果，「蔬菜」只是日常和法律上的叫法。", "fact": "西红柿在植物学上其实是一种蔬菜。", "joke": "西红柿其实是一种坚果", "real": false}, {"why": "假的：昆虫是六条腿、身体分三段；蜘蛛八条腿、身体分两段，属于蛛形纲，不是昆虫。", "fact": "蜘蛛是一种昆虫。", "joke": "蜘蛛是会织网的小鸟", "real": false}, {"why": "假的：企鹅有膝盖，只是膝盖藏在厚厚的羽毛和身体里，看着才像没有。", "fact": "企鹅的腿是直的，根本没有膝盖。", "joke": "企鹅的腿是橡皮做的，能弯成任意形状", "real": false}, {"why": "假的：天蓝是因为空气把阳光里波长短的蓝光散射得到处都是，跟海一点关系都没有。", "fact": "天空之所以是蓝的，是因为它倒映了大海的蓝色。", "joke": "天是被蓝色颜料刷出来的", "real": false}, {"why": "假的：月亮总以同一面朝着地球，但背面照样会被太阳照到，并不是永远黑的。", "fact": "月亮有一面永远照不到太阳，是漆黑一片的「暗面」。", "joke": "月亮的背面住着月兔", "real": false}, {"why": "假的：跑得最快的是鸵鸟，时速能到约 70 公里；火鸡可追不上它。", "fact": "陆地上跑得最快的鸟是火鸡。", "joke": "跑得最快的鸟是企鹅", "real": false}, {"why": "假的：牛只有一个胃，只是分成了四个相连的隔间，轮流帮它消化粗硬的草。", "fact": "牛有四个各自独立的胃。", "joke": "牛有四个胃还外加一个备用胃", "real": false}, {"why": "假的：蜜蜂回巢后跳一种「摇摆舞」，用舞步的方向和时长来告诉同伴花在哪、有多远。", "fact": "蜜蜂是靠大声喊话，告诉同伴花田在哪个方向。", "joke": "蜜蜂会画一张地图递给同伴", "real": false}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
